const NAV_UNMOUNT_SEGMENTS = new Set(["login", "onboarding", "import-songs", "downloads", "profile", "delete-account"]);
const NAV_OVERLAY_SEGMENTS = new Set(["playlist", "artist"]);

const GLOBAL_TOAST_VISIBLE_MS = 1050;

const paperTheme = {
  ...MD3DarkTheme,
