export const PlayerScreen = memo(function PlayerScreen() {
  const { height: screenHeight } = useWindowDimensions();

  const { currentSong, queue, queueIndex } = usePlaybackNowPlaying();
  const activeSong = currentSong ?? queue[queueIndex] ?? queue[0] ?? null;

  const [uiState, setUiState] = useState<PlayerUIState>(() => playerUIStateStore.current);

  useEffect(() => playerUIStateStore.subscribe(setUiState), []);

  useEffect(() => {
    if (activeSong && playerUIStateStore.current === "hidden") {
      playerUIStateStore.showMini();
    } else if (!activeSong && playerUIStateStore.current !== "hidden") {
      playerUIStateStore.hidePlayer();
    }
  }, [activeSong]);

  const translateY = useSharedValue(screenHeight);

  useEffect(() => {
    if (uiState === "expanded") {
      translateY.value = withSpring(0, SPRING_CONFIG);
    } else if (uiState === "mini" || uiState === "hidden") {
      translateY.value = withSpring(screenHeight, SPRING_CONFIG);
    }
  }, [uiState, screenHeight, translateY]);

  useEffect(() => {
    if (!IS_ANDROID) return;
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      if (playerUIStateStore.current === "expanded") {
        playerUIStateStore.collapsePlayer();
        return true;
      }
      return false;
    });
    return () => sub.remove();
  }, []);

  /* eslint-disable react-hooks/immutability -- Gesture callbacks update Reanimated shared values after render. */
  const panGesture = Gesture.Pan()
    .activeOffsetY(8)
    .failOffsetY(-8)
    .failOffsetX([-35, 35])
    .onUpdate((e) => {
      if (e.translationY > 0) {
        translateY.value = e.translationY;
      }
    })
    .onEnd((e) => {
      if (e.translationY > 100 || (e.translationY > 20 && e.velocityY > 500)) {
        translateY.value = withSpring(screenHeight, SPRING_CONFIG);
        scheduleOnRN(collapseOnJS);
      } else {
        translateY.value = withSpring(0, SPRING_CONFIG);
      }
    });
  /* eslint-enable react-hooks/immutability */

  const containerStyle = useAnimatedStyle(() => {
    const isHidden = translateY.value >= screenHeight - 100;
    return {
      transform: [{ translateY: Math.max(0, translateY.value) }],
      opacity: isHidden ? 0 : 1,
    };
  });

  if (!activeSong || uiState === "hidden") return null;

  const isExpanded = uiState === "expanded";

  return (
    <Reanimated.View
      pointerEvents={isExpanded ? "auto" : "none"}
      style={[
        styles.sheetContainer,
        StyleSheet.absoluteFillObject,
        containerStyle,
      ]}
    >
      <GestureDetector gesture={panGesture}>
        <Reanimated.View style={styles.contentWrap}>
          <LegacyPlayerScreenView translateY={translateY} />
        </Reanimated.View>
      </GestureDetector>
    </Reanimated.View>
  );
});

PlayerScreen.displayName = "PlayerScreen";

export default PlayerScreen;

import { useLocalSearchParams } from "expo-router";

function pickFirstParam(value: string | string[] | undefined): string {
  if (Array.isArray(value)) return value[0] ?? "";
  return value ?? "";
}

export function usePlaylistDetailParams() {
  const params = useLocalSearchParams<{
    id?: string | string[];
    jiosaavn?: string | string[];
    album?: string | string[];
    song?: string | string[];
    type?: string | string[];
    link?: string | string[];
    firestore?: string | string[];
    title?: string | string[];
    description?: string | string[];
    cover?: string | string[];
    songCount?: string | string[];
    source?: string | string[];
  }>();

  const playlistId = pickFirstParam(params.id).trim();
  const sourceLink = pickFirstParam(params.link).trim();
  const firestoreParam = pickFirstParam(params.firestore);
  const jiosaavnParam = pickFirstParam(params.jiosaavn);
  const sourceParam = pickFirstParam(params.source).toLowerCase();

  const isYouTubeSource = false;

  const isSongSource =
    pickFirstParam(params.song) === "true" ||
    pickFirstParam(params.type) === "song" ||
    sourceLink.includes("/song/");
  const isAlbumSource =
    !isSongSource &&
    (pickFirstParam(params.album) === "true" ||
      pickFirstParam(params.type) === "album" ||
      sourceLink.includes("/album/"));
  const isFirestoreSource = firestoreParam === "true";
  const isExplicitLocal = firestoreParam === "false" && jiosaavnParam === "false";
  const isLocalCustomPlaylist = isExplicitLocal || playlistId.startsWith("user_");
  const isJioSaavnSource =
    !isFirestoreSource &&
    !isLocalCustomPlaylist &&
    (jiosaavnParam === "true" || isSongSource || isAlbumSource || sourceLink.length > 0);
  const initialTitle = pickFirstParam(params.title).trim();
  const initialCover = pickFirstParam(params.cover).trim();
  const initialDescription = pickFirstParam(params.description).trim();
  const initialSongCount = Math.max(0, Number(pickFirstParam(params.songCount)) || 0);
  const hasPrefilledHeader = initialTitle.length > 0 || initialCover.length > 0 || initialSongCount > 0;

  return {
    playlistId,
    sourceLink,
    isSongSource,
    isAlbumSource,
    isFirestoreSource,
    isLocalCustomPlaylist,
    isJioSaavnSource,
    isYouTubeSource,
    initialTitle,
    initialCover,
    initialDescription,
    initialSongCount,
    hasPrefilledHeader,
  };
}

import React, { useCallback, useMemo, useRef, useState } from "react";
