export function SearchScreen() {
  return <SearchScreenView />;
}

export default SearchScreen;

function SearchScreenView() {
  const params = useLocalSearchParams<{ q?: string | string[]; name?: string | string[] }>();
  const searchEngine = useSearchEngine(params);
  const inputRef = useRef<TextInput>(null);

  const {
    isOnline,
    topInset,
    query,
    isSearchMode,
    isHeaderElevated,
    suggestionsOpen,
    suggestions,
    showFocusedRecentSearches,
    showBrowse,
    recentSearches,
    browseCategories,
    resultFilter,
    searchLoading,
    hasResults,
    searchDisplayQuery,
    resultDataKey,
    displayedSongs,
    songResults,
    albumResults,
    artistResults,
    playlistResults,
    topSong,
    topArtist,
    featuredAlbums,
    featuredArtists,
    featuredPlaylists,
    resultsPlaylistsListRef,
    resultsAlbumsListRef,
    resultsArtistsListRef,
    resultsSongsListRef,
    handleHeaderScroll,
    handleChangeText,
    handleSubmitSearch,
    handleClear,
    handleActivateSearchMode,
    handleCancelSearchMode,
    handleGenrePress,
    handleRecentSearchPress,
    handleSuggestionPress,
    handleRemoveRecentSearch,
    handleResultFilterSelect,
    handleSongResultPress,
    handleArtistPress,
    handleAlbumPress,
    handlePlaylistPress,
  } = searchEngine;

  const onFocusSearch = useCallback(() => {
    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
    handleActivateSearchMode();
  }, [handleActivateSearchMode]);

  const onCancelSearch = useCallback(() => {
    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
    Keyboard.dismiss();
    inputRef.current?.blur();
    handleCancelSearchMode();
  }, [handleCancelSearchMode]);

  const renderSuggestion = useCallback(
    ({ item: suggestion }: { item: string }) => (
      <Pressable
        style={({ pressed }) => [styles.suggestionRow, pressed && styles.suggestionRowPressed]}
        onPressIn={() => handleSuggestionPress(suggestion)}
      >
        <Ionicons name="search-outline" size={18} color={Colors.subtext} style={styles.suggestionIcon} />
        <Text style={styles.suggestionText} numberOfLines={1}>
          {suggestion}
        </Text>
      </Pressable>
    ),
    [handleSuggestionPress]
  );

  // Early return for offline idle state
  if (!isOnline && query.length === 0) {
    return (
      <View style={styles.container}>
        <AppTopHeader
          topInset={topInset}
          elevated={false}
          title="Search"
          left={<AppTopHeaderProfileButton />}
          right={<AppTopHeaderDownloadButton />}
        />
        <OfflineScreen
          message="Search requires an internet connection."
          hideDownloadsButton={false}
        />
      </View>
    );
  }

  return (
    <View style={styles.container}>
      {!isOnline && <OfflineBanner />}

      {/* ── Header ── */}
      {isSearchMode ? (
        <View
          style={[
            styles.activeSearchHeader,
            { paddingTop: topInset + 6 },
            isHeaderElevated && styles.activeSearchHeaderElevated,
          ]}
        >
          <View style={styles.activeSearchBarRow}>
            <View style={styles.activeSearchFieldWrap}>
              <SearchHeaderField
                ref={inputRef}
                value={query}
                onChangeText={handleChangeText}
                onSubmit={handleSubmitSearch}
                onClear={handleClear}
                autoFocus={true}
                placeholder="Search songs, artists, albums..."
                theme="dark"
              />
            </View>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Cancel search"
              onPress={onCancelSearch}
              hitSlop={{ top: 12, bottom: 12, left: 10, right: 10 }}
              style={({ pressed }) => [styles.searchCancelButton, pressed && styles.searchCancelButtonPressed]}
            >
              <Text style={styles.searchCancelText}>Cancel</Text>
            </Pressable>
          </View>

          {/* Liquid Glass Scope Bar integrated directly in header */}
          <View style={styles.headerScopeBarWrap}>
            <LiquidGlassScopeBar
              options={RESULT_FILTERS}
              activeKey={resultFilter}
              onSelect={handleResultFilterSelect}
            />
          </View>
        </View>
      ) : (
        <AppTopHeader
          topInset={topInset}
          elevated={isHeaderElevated}
          title="Search"
          left={<AppTopHeaderProfileButton />}
          right={<AppTopHeaderDownloadButton />}
        />
      )}

      {/* ── Native Liquid Glass Search Button ── */}
      {!isSearchMode && (
        <View style={[styles.searchBarRow, { paddingTop: topInset + APP_TOP_HEADER_HEIGHT + 8 }]}>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel="Search songs, albums, artists, playlists"
            style={({ pressed }) => [styles.searchGlassButton, pressed && styles.searchGlassButtonPressed]}
            onPress={onFocusSearch}
          >
            <LiquidGlassView
              style={styles.liquidGlassBar}
              intensity={55}
              tint="systemMaterialDark"
              borderRadius={24}
            >
              <Ionicons name="search" size={19} color="rgba(255, 255, 255, 0.70)" style={styles.searchIcon} />
              <Text style={styles.inactiveSearchText} numberOfLines={1}>
                Search songs, artists, albums...
              </Text>
            </LiquidGlassView>
          </Pressable>
        </View>
      )}

      {/* Inline suggestions below search header */}
      {isSearchMode && suggestionsOpen && suggestions.length > 0 && query.trim().length >= 2 && (
        <View style={[styles.suggestionsDropdown, { top: topInset + 104 }]}>
          <FlatList
            data={suggestions}
            keyboardDismissMode="none"
            keyboardShouldPersistTaps="always"
            keyExtractor={(suggestion) => `suggestion-${suggestion}`}
            renderItem={renderSuggestion}
          />
        </View>
      )}

      {showFocusedRecentSearches ? (
        <SearchRecentSection
          topInset={topInset}
          recentSearches={recentSearches}
          onScroll={handleHeaderScroll}
          onRecentSearchPress={handleRecentSearchPress}
          onRemoveRecentSearch={handleRemoveRecentSearch}
        />
      ) : showBrowse ? (
        <SearchBrowseSection
          browseCategories={browseCategories}
          onScroll={handleHeaderScroll}
          onGenrePress={handleGenrePress}
        />
      ) : (
        <SearchResultsSection
          topInset={topInset}
          resultFilter={resultFilter}
          searchLoading={searchLoading}
          hasResults={hasResults}
          searchDisplayQuery={searchDisplayQuery}
          resultDataKey={resultDataKey}
          displayedSongs={displayedSongs}
          songResults={songResults}
          albumResults={albumResults}
          artistResults={artistResults}
          playlistResults={playlistResults}
          topSong={topSong}
          topArtist={topArtist}
          featuredAlbums={featuredAlbums}
          featuredArtists={featuredArtists}
          featuredPlaylists={featuredPlaylists}
          onScroll={handleHeaderScroll}
          onFilterSelect={handleResultFilterSelect}
          onSongPress={handleSongResultPress}
          onArtistPress={handleArtistPress}
          onAlbumPress={handleAlbumPress}
          onPlaylistPress={handlePlaylistPress}
          resultsPlaylistsListRef={resultsPlaylistsListRef}
          resultsAlbumsListRef={resultsAlbumsListRef}
          resultsArtistsListRef={resultsArtistsListRef}
          resultsSongsListRef={resultsSongsListRef}
        />
      )}
    </View>
  );
}

import { Platform } from "react-native";

type AnalyticsModule = {
  analytics: unknown;
  logEvent: (analytics: unknown, eventName: string, params?: Record<string, unknown>) => void;
};

let analyticsModulePromise: Promise<AnalyticsModule | null> | null = null;

async function loadAnalyticsModule(): Promise<AnalyticsModule | null> {
  if (Platform.OS !== "web") {
    return null;
  }

  if (!analyticsModulePromise) {
    analyticsModulePromise = (async () => {
      try {
        const [{ getAnalytics, isSupported, logEvent: firebaseLogEvent }, firebaseAppModule] = await Promise.all([
          import("firebase/analytics"),
          import("./firebase"),
        ]);

        const supported = await isSupported().catch(() => false);
        if (!supported) {
          return null;
        }

        return {
          analytics: getAnalytics(firebaseAppModule.default),
          logEvent: (analytics, eventName, params) => {
            firebaseLogEvent(analytics as never, eventName, params as never);
          },
        };
      } catch {
        return null;
      }
    })();
  }

  return analyticsModulePromise;
}

/**
 * Log an analytics event.
 * Native builds intentionally no-op here so startup never pulls in the web
 * Firebase Analytics bundle.
 */
export function logEvent(eventName: string, params?: Record<string, unknown>) {
  if (Platform.OS !== "web") {
    return;
  }

  void loadAnalyticsModule()
    .then((module) => {
      if (!module) {
        return;
      }

      module.logEvent(module.analytics, eventName, params);
    })
    .catch(() => {});
}

export function logAppOpen() {
  logEvent("app_open");
}

export function logScreenView(screenName: string, screenClass?: string) {
  logEvent("screen_view", {
    screen_name: screenName,
    screen_class: screenClass || screenName,
  });
}

export function logLogin(method: string) {
  logEvent("login", { method });
}

export function logSignUp(method: string) {
  logEvent("sign_up", { method });
}

function logSearch(searchTerm: string) {
  logEvent("search", { search_term: searchTerm });
}

function logSelectContent(contentType: string, itemId: string) {
  logEvent("select_content", {
    content_type: contentType,
    item_id: itemId,
  });
}

import { Platform } from "react-native";
import * as Crypto from "expo-crypto";

type AppleAuthenticationModule = typeof import("expo-apple-authentication");
type AppleFullName = import("expo-apple-authentication").AppleAuthenticationFullName;

export type AppleMobileCredential = {
  idToken: string;
  rawNonce: string;
  email?: string | null;
  fullName?: string | null;
  user?: string | null;
  authorizationCode?: string | null;
};

const NONCE_CHARSET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-._";

function getAppleAuthenticationModule(actionLabel: string): AppleAuthenticationModule {
  try {
    return require("expo-apple-authentication") as AppleAuthenticationModule;
  } catch {
    throw new Error(
      `${actionLabel} requires a custom development build or production app build with Apple Sign-In enabled.`
    );
  }
}

function createNonce(length = 32): string {
  const randomBytes = Crypto.getRandomBytes(length);
  return Array.from(randomBytes, (byte) => NONCE_CHARSET[byte % NONCE_CHARSET.length]).join("");
}

function formatFullName(fullName: AppleFullName | null | undefined): string | null {
  if (!fullName) return null;

  const primaryName = [
    fullName.namePrefix,
    fullName.givenName,
    fullName.middleName,
    fullName.familyName,
    fullName.nameSuffix,
  ]
    .flatMap((part) => {
      const trimmed = String(part || "").trim();
      return trimmed ? [trimmed] : [];
    })
    .join(" ")
    .trim();

  return primaryName || String(fullName.nickname || "").trim() || null;
}

export async function isAppleSignInAvailable(): Promise<boolean> {
  if (Platform.OS !== "ios") {
    return false;
  }

  try {
    const AppleAuthentication = getAppleAuthenticationModule("Apple Sign-In");
    return await AppleAuthentication.isAvailableAsync();
  } catch {
    return false;
  }
}

export async function getAppleMobileCredential(
  actionLabel: string = "Apple Sign-In"
): Promise<AppleMobileCredential> {
  if (Platform.OS !== "ios") {
    throw new Error(`${actionLabel} is only available on Apple devices.`);
  }

  const AppleAuthentication = getAppleAuthenticationModule(actionLabel);
  const available = await AppleAuthentication.isAvailableAsync();
  if (!available) {
    throw new Error(`${actionLabel} is not available on this device.`);
  }

  const rawNonce = createNonce();
  const hashedNonce = await Crypto.digestStringAsync(
    Crypto.CryptoDigestAlgorithm.SHA256,
    rawNonce
  );

  try {
    const credential = await AppleAuthentication.signInAsync({
      requestedScopes: [
        AppleAuthentication.AppleAuthenticationScope.FULL_NAME,
        AppleAuthentication.AppleAuthenticationScope.EMAIL,
      ],
      nonce: hashedNonce,
    });

    if (!credential.identityToken) {
      throw new Error(`Could not complete ${actionLabel}. No Apple identity token received.`);
    }

    return {
      idToken: credential.identityToken,
      rawNonce,
      email: credential.email,
      fullName: formatFullName(credential.fullName),
      user: credential.user,
      authorizationCode: credential.authorizationCode,
    };
  } catch (error: any) {
    if (String(error?.code || "") === "ERR_REQUEST_CANCELED") {
      throw new Error(`${actionLabel} was cancelled.`);
    }

    throw error;
  }
}

/**
 * Client-Side Cache Manager
 * Reduces Firebase reads by 60-70% through intelligent caching
 */

interface CacheEntry<T> {
  data: T;
  timestamp: number;
  ttl: number; // Time to live in milliseconds
}

class CacheManager {
  private cache: Map<string, CacheEntry<any>>;
  private memoryCache: Map<string, any>; // Session-only cache

  constructor() {
    this.cache = new Map();
    this.memoryCache = new Map();
  }

  /**
   * Set cache with TTL
   */
  set<T>(key: string, data: T, ttlMinutes: number = 5): void {
    const entry: CacheEntry<T> = {
      data,
      timestamp: Date.now(),
      ttl: ttlMinutes * 60 * 1000,
    };
    this.cache.set(key, entry);
  }

  /**
   * Get cached data if not expired
   */
  get<T>(key: string): T | null {
    const entry = this.cache.get(key);
    
    if (!entry) {
      return null;
    }

    const now = Date.now();
    const age = now - entry.timestamp;

    if (age > entry.ttl) {
      this.cache.delete(key);
      return null;
    }

    return entry.data as T;
  }

  /**
   * Check if cache has valid entry
   */
  has(key: string): boolean {
    return this.get(key) !== null;
  }

  /**
   * Clear specific cache entry
   */
  clear(key: string): void {
    this.cache.delete(key);
  }

  /**
   * Clear all cache
   */
  clearAll(): void {
    this.cache.clear();
    this.memoryCache.clear();
  }

  /**
   * Clear cache by pattern (e.g., "user:*")
   */
  clearPattern(pattern: string): void {
    const regex = new RegExp(pattern.replace('*', '.*'));
    const keysToDelete: string[] = [];

    this.cache.forEach((_, key) => {
      if (regex.test(key)) {
        keysToDelete.push(key);
      }
    });

    keysToDelete.forEach(key => this.cache.delete(key));
  }

  /**
   * Set memory-only cache (cleared on app restart)
   */
  setMemory<T>(key: string, data: T): void {
    this.memoryCache.set(key, data);
  }

  /**
   * Get memory cache
   */
  getMemory<T>(key: string): T | null {
    return this.memoryCache.get(key) || null;
  }

  /**
   * Get cache statistics
   */
  getStats() {
    return {
      entries: this.cache.size,
      memoryEntries: this.memoryCache.size,
    };
  }
}

// Singleton instance
export const cache = new CacheManager();

/**
 * Cache key generators
 */
const CacheKeys = {
  // User-specific
  userPlaylists: (userId: string) => `user:${userId}:playlists`,
  userLikedSongs: (userId: string) => `user:${userId}:liked`,
  userProfile: (userId: string) => `user:${userId}:profile`,
  
  // Public data
  publicPlaylists: () => 'public:playlists',
  playlist: (playlistId: string) => `playlist:${playlistId}`,
  
  // JioSaavn
  jiosaavnPlaylist: (playlistId: string) => `jiosaavn:playlist:${playlistId}`,
  jiosaavnSearch: (query: string) => `jiosaavn:search:${query}`,
  jiosaavnTrending: () => 'jiosaavn:trending',
};

/**
 * Cache TTL configurations (in minutes)
 */
const CacheTTL = {
  // User data - shorter TTL for freshness
  userPlaylists: 2,
  userLikedSongs: 1,
  userProfile: 5,
  
  // Public data - longer TTL
  publicPlaylists: 10,
  playlist: 5,
  
  // JioSaavn - medium TTL
  jiosaavnPlaylist: 15,
  jiosaavnSearch: 10,
  jiosaavnTrending: 30,
};

/**
 * Cached fetch wrapper
 */
async function cachedFetch<T>(
  key: string,
  fetcher: () => Promise<T>,
  ttlMinutes: number = 5
): Promise<T> {
  const cached = cache.get<T>(key);
  if (cached !== null) {
    return cached;
  }

  const data = await fetcher();
  cache.set(key, data, ttlMinutes);
  
  return data;
}

/**
 * Clear user-specific cache on logout
 */
export function clearUserCache(userId: string): void {
  cache.clearPattern(`user:${userId}:*`);
}

function clearAllCache(): void {
  cache.clearAll();
}

import { collection, getDocs, limit, orderBy, query, where, type Firestore } from "firebase/firestore";
import { type Song } from "@/lib/musicData";

const SONG_LIMIT = 30;

let _db: Firestore | null = null;
function getDb(): Firestore | null {
  if (_db) return _db;
  try {
    const { db } = require("@/lib/firebase");
    _db = db;
    return _db;
  } catch {
    return null;
  }
}

function mapSong(id: string, data: Record<string, any>): Song | null {
  const audioUrl = data.audioUrl || data.streamUrl || data.url;
  if (!data.title || !audioUrl) {
    return null;
  }

  let imageUrl = data.imageUrl || data.coverUrl || "";
  if (!imageUrl && Array.isArray(data.image)) {
    imageUrl = data.image[data.image.length - 1]?.url || data.image[data.image.length - 1]?.link || "";
  }

  return {
    id,
    title: String(data.title || data.name || ""),
    artist: String(data.artist || data.primaryArtists || "Unknown Artist"),
    album: typeof data.album === "object" ? String(data.album?.name || "") : String(data.album || ""),
    duration: Number(data.duration) || 0,
    coverUrl: imageUrl,
    genre: String(data.genre || data.language || ""),
    mood: data.mood || data.moods || undefined,
    audioUrl: String(audioUrl),
    year: data.year ? String(data.year) : "",
    language: String(data.language || ""),
    popularity: Number(data.popularity || 0) || undefined,
    source: "local",
  };
}

export async function getCatalogSongs(): Promise<Song[]> {
  const db = getDb();
  if (!db) return [];

  try {
    let snapshot;
    try {
      const songsQuery = query(
        collection(db, "songs"),
        orderBy("popularity", "desc"),
        limit(SONG_LIMIT)
      );
      snapshot = await getDocs(songsQuery);
    } catch {
      const fallbackQuery = query(collection(db, "songs"), limit(SONG_LIMIT));
      snapshot = await getDocs(fallbackQuery);
    }

    return snapshot.docs.flatMap((doc) => {
      const song = mapSong(doc.id, doc.data());
      return song !== null ? [song] : [];
    });
  } catch {
    return [];
  }
}

export async function searchCatalog(searchText: string): Promise<Song[]> {
  const db = getDb();
  if (!db) return [];

  const text = searchText.trim();
  if (text.length < 2) {
    return [];
  }

  try {
    const normalized = text.toLowerCase();
    const songsQuery = query(
      collection(db, "songs"),
      where("titleLower", ">=", normalized),
      where("titleLower", "<=", `${normalized}\uf8ff`),
      limit(20)
    );
    const snapshot = await getDocs(songsQuery);

    return snapshot.docs.flatMap((doc) => {
      const song = mapSong(doc.id, doc.data());
      return song !== null ? [song] : [];
    });
  } catch {
    return [];
  }
}

/**
 * colorExtractor.ts — Artwork Color Extraction Architecture
 *
 * 1. Native Layer (Android):
 *    - Uses AndroidX Palette (`androidx.palette.graphics.Palette`) to extract:
 *      • 6 Standard Color Profiles: Vibrant, Vibrant Dark, Vibrant Light, Muted, Muted Dark, Muted Light
 *      • Dominant Swatch: Swatch with greatest pixel population (`getDominantSwatch()`)
 *      • Safely handles nullable profile swatches with prioritized fallback chaining.
 *
 * 2. Native Layer (iOS):
 *    - Uses `UIImageColors` to extract background, primary, secondary, and detail.
 *
 * 3. JS Fallback Layer (Expo Go / Web):
 *    - Pure-JS decode + sampled RGB/HSL extraction.
 *
 * 4. Mavrixfy Presentation Layer:
 *    - Custom Spotify-inspired transforms (`getSpotifyMiniPlayerBg`, `ensureDarkHexColor`)
 *      to ensure consistent dark-mode styling and WCAG readable text contrast across the UI.
 */

import { useState, useEffect } from "react";
import Constants from "expo-constants";
import * as FileSystem from "expo-file-system/legacy";
import { Platform } from "react-native";

type ImageColorsResult =
  | {
      platform: "android";
      vibrant?: string;
      lightVibrant?: string;
      darkVibrant?: string;
      darkMuted?: string;
      muted?: string;
      dominant?: string;
      average?: string;
    }
  | {
      platform: "ios";
      background?: string;
      primary?: string;
      secondary?: string;
      detail?: string;
    }
  | {
      platform: "web";
      vibrant?: string;
      lightVibrant?: string;
      darkVibrant?: string;
      darkMuted?: string;
      muted?: string;
      dominant?: string;
    };

type NativeGetColors = (uri: string, config?: Record<string, unknown>) => Promise<ImageColorsResult>;

export interface ArtworkPalette {
  /** Controlled background color for screen/card top gradients. Preserves exact hue and adapts lightness seamlessly. */
  background: string;
  /** Primary vibrant accent for interactive controls, badges, waves, buttons */
  accent: string;
  /** Text color dynamically calculated for highest contrast readability */
  text: string;
  isDark: boolean;
  /** Accent color alias for older call sites. */
  primary: string;
  /** Raw dominant color straight from native extraction without alteration */
  rawDominant?: string;
  /** Raw vibrant color straight from native extraction without alteration */
  rawVibrant?: string;
  /** All extracted discrete color swatches directly from the artwork. */
  swatches?: string[];
}

/** @deprecated Use ArtworkPalette */
export type ColorResult = ArtworkPalette;

export interface SpotifyColorTheme {
  accent: string;
  accentSoft: string;
  onAccent: string;
  border: string;
  playerGradient: [string, string, string, string];
  playlistBackdrop: [string, string, string, string, string];
}

export const DEFAULT_ARTWORK_PALETTE: ArtworkPalette = {
  background: "#0E1016",
  accent: "#26E19A",
  text: "#FFFFFF",
  isDark: true,
  primary: "#26E19A",
  rawDominant: "#0E1016",
  rawVibrant: "#26E19A",
  swatches: ["#142820", "#122030", "#281420", "#241A10", "#181A20"],
};

export function getSpotifyMiniPlayerBg(color: string, defaultBg = "#16181D"): string {
  const normalized = normalizeHexColor(color);
  if (!normalized) return defaultBg;
  return transformToSeamlessBackground(normalized);
}

/**
 * Transforms an extracted artwork color into a seamless, elegant top-gradient background.
 * Follows the Apple Music & Spotify color science:
 * - Retains exact artwork hue (H).
 * - Light/pastel colors (e.g. Benson Boone pale blue/green, Taylor Swift turquoise, Billie Eilish lime):
 *   Lightness is gently adapted into a rich, visible range (0.24 - 0.32) so the true pastel/light
 *   hue is clearly noticeable and gorgeous, without blinding or breaking white text contrast.
 * - Dark colors (e.g. Bruno Mars black/gray, Weeknd dark crimson):
 *   Lightness is gently lifted if too pitch black (0.13 - 0.18) so details don't get lost.
 * - Saturation is balanced (0.35 - 0.72) to prevent harsh neon while avoiding dull muddy gray.
 */
export function transformToSeamlessBackground(hexColor: string): string {
  const normalized = normalizeHexColor(hexColor) ?? DEFAULT_ARTWORK_PALETTE.background;
  const r = parseInt(normalized.slice(1, 3), 16);
  const g = parseInt(normalized.slice(3, 5), 16);
  const b = parseInt(normalized.slice(5, 7), 16);
  const { h, s, l } = rgbToHsl(r, g, b);

  // Pure grayscale or near-neutral (Bruno Mars, etc.)
  if (s < 0.08) {
    const clampedL = Math.max(0.08, Math.min(0.14, l));
    const rgb = hslToRgb(h, 0.03, clampedL);
    return rgbToHex(rgb.r, rgb.g, rgb.b);
  }

  // Accurate dark background: Keep exact hue, keep saturation true to artwork,
  // target rich dark lightness (0.09 - 0.16) so text contrast is 100% and background
  // is solid, deep, and perfectly matches the artwork tone
  let targetL = 0.09 + l * 0.12;
  targetL = Math.max(0.08, Math.min(0.16, targetL));

  // Maintain natural saturation of the extracted color (accurate, no artificial neon or wash):
  const targetS = Math.min(0.85, Math.max(0.32, s));

  const darkRgb = hslToRgb(h, targetS, targetL);
  return rgbToHex(darkRgb.r, darkRgb.g, darkRgb.b);
}

/**
 * Transforms an extracted color into a vibrant, high-energy accent for buttons and badges.
 */
export function transformToVibrantAccent(hexColor: string): string {
  const normalized = normalizeHexColor(hexColor) ?? DEFAULT_ARTWORK_PALETTE.accent;
  const r = parseInt(normalized.slice(1, 3), 16);
  const g = parseInt(normalized.slice(3, 5), 16);
  const b = parseInt(normalized.slice(5, 7), 16);
  const { h, s, l } = rgbToHsl(r, g, b);

  if (s < 0.08) {
    return "#FFFFFF";
  }

  const targetL = Math.max(0.50, Math.min(0.70, l > 0.30 ? l : 0.56));
  const targetS = Math.max(0.70, Math.min(1.0, s * 1.25));

  const rgb = hslToRgb(h, targetS, targetL);
  return rgbToHex(rgb.r, rgb.g, rgb.b);
}

export function ensureDarkHexColor(
  hexColor: string,
  _maxLightness?: number,
  _minLightness?: number
): string {
  return transformToSeamlessBackground(hexColor);
}

const COLOR_CACHE_MAX_ENTRIES = 200;
const paletteCache = new Map<string, ArtworkPalette>();
const pendingRequests = new Map<string, Promise<ArtworkPalette>>();

let nativeGetColors: NativeGetColors | null | undefined;

export function normalizeArtworkUrl(url: string | null | undefined): string {
  if (!url || typeof url !== "string") return "";
  let clean = url.trim();
  if (!clean) return "";

  // Upgrade insecure http:// to https:// to satisfy iOS ATS in release/IPA builds
  if (clean.startsWith("http://")) {
    clean = "https://" + clean.slice(7);
  }

  // Handle potential unencoded characters in URL (spaces, unicode)
  try {
    clean = encodeURI(decodeURI(clean));
  } catch {
    // Keep as is if encoding fails
  }

  return clean;
}

export function getColorStats(hex: string | undefined | null) {
  const norm = normalizeHexColor(hex);
  if (!norm) return null;
  const r = parseInt(norm.slice(1, 3), 16);
  const g = parseInt(norm.slice(3, 5), 16);
  const b = parseInt(norm.slice(5, 7), 16);
  const { h, s, l } = rgbToHsl(r, g, b);
  // Vibrancy score favors saturated colors with moderate lightness (avoids pitch black and blinding white)
  const vibrancy = s * (1 - Math.abs(l - 0.55) * 1.3);
  return { hex: norm, h, s, l, vibrancy };
}

export function extractArtworkColors(imageUrl: string): Promise<ArtworkPalette> {
  const rawKey = (imageUrl || "").trim();
  if (!rawKey) return Promise.resolve(DEFAULT_ARTWORK_PALETTE);

  const cacheKey = normalizeArtworkUrl(rawKey);

  const cached = paletteCache.get(cacheKey) || paletteCache.get(rawKey);
  if (cached) {
    paletteCache.delete(cacheKey);
    paletteCache.set(cacheKey, cached);
    return Promise.resolve(cached);
  }

  const pending = pendingRequests.get(cacheKey) || pendingRequests.get(rawKey);
  if (pending) return pending;

  const request = extractArtworkColorsUncached(cacheKey).finally(() => {
    pendingRequests.delete(cacheKey);
    pendingRequests.delete(rawKey);
  });
  pendingRequests.set(cacheKey, request);
  if (rawKey !== cacheKey) {
    pendingRequests.set(rawKey, request);
  }
  return request;
}

export function preloadDominantColors(imageUrls: (string | null | undefined)[]): void {
  // If native image-colors is not available (e.g. Expo Go / JS fallback),
  // do NOT aggressively preload 50 songs in JS because decoding 50 JPEGs concurrently causes heating.
  if (!canUseNativeImageColors()) return;

  for (const rawUrl of imageUrls) {
    const url = rawUrl?.trim();
    if (!url || paletteCache.has(url) || pendingRequests.has(url)) continue;
    void extractArtworkColors(url).catch(() => {});
  }
}

export function getImmediateArtworkPalette(imageUrl: string | null | undefined): ArtworkPalette {
  const rawKey = (imageUrl || "").trim();
  if (!rawKey) return DEFAULT_ARTWORK_PALETTE;

  const cacheKey = normalizeArtworkUrl(rawKey);

  const cached = paletteCache.get(cacheKey) || paletteCache.get(rawKey);
  if (!cached) return DEFAULT_ARTWORK_PALETTE;

  paletteCache.delete(cacheKey);
  paletteCache.set(cacheKey, cached);
  return cached;
}

/**
 * Reusable hook for reactive artwork color extraction with instant cache retrieval.
 */
export function useArtworkPalette(imageUrl: string | null | undefined): ArtworkPalette {
  const [palette, setPalette] = useState<ArtworkPalette>(() =>
    getImmediateArtworkPalette(imageUrl)
  );

  useEffect(() => {
    const key = (imageUrl || "").trim();
    if (!key) {
      // Clear colors from the previous image as soon as the source disappears.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setPalette(DEFAULT_ARTWORK_PALETTE);
      return;
    }

    let isMounted = true;
    void extractArtworkColors(key).then((extracted) => {
      if (isMounted) {
        setPalette(extracted);
      }
    });

    return () => {
      isMounted = false;
    };
  }, [imageUrl]);

  return palette;
}

function canUseNativeImageColors(): boolean {
  if (Platform.OS === "web") return true;
  // Expo Go cannot load custom native modules like ImageColors.
  if (Constants.executionEnvironment === "storeClient") return false;
  if (Constants.appOwnership === "expo") return false;
  return true;
}

function resolveNativeGetColors(): NativeGetColors | null {
  if (nativeGetColors !== undefined) return nativeGetColors;
  nativeGetColors = null;

  if (!canUseNativeImageColors()) return null;

  try {
    // Must not be imported at file scope — module load throws in Expo Go.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    nativeGetColors = require("react-native-image-colors").getColors as NativeGetColors;
  } catch {
    nativeGetColors = null;
  }

  return nativeGetColors;
}

async function extractArtworkColorsUncached(rawKey: string): Promise<ArtworkPalette> {
  const cacheKey = normalizeArtworkUrl(rawKey);
  if (!cacheKey) return DEFAULT_ARTWORK_PALETTE;

  const getColors = resolveNativeGetColors();

  if (getColors) {
    const sources = await buildArtworkSources(cacheKey);

    for (let i = 0; i < sources.length; i++) {
      try {
        const result = await getColors(sources[i], {
          fallback: "#000000",
          cache: false,
          quality: "high",
          key: cacheKey,
          ...(Platform.OS === "android" ? { pixelSpacing: 5 } : {}),
        });

        const palette = mapImageColorsToPalette(result);
        if (!isDefaultPalette(palette)) {
          setCachedPalette(cacheKey, palette);
          if (rawKey !== cacheKey) {
            setCachedPalette(rawKey, palette);
          }
          return palette;
        }
      } catch {
        // Try next source.
      }
    }
  }

  // JS Fallback Layer (Expo Go / Web / Native Fallback):
  try {
    const palette = await extractArtworkColorsWithJsDecoder(cacheKey);
    setCachedPalette(cacheKey, palette);
    if (rawKey !== cacheKey) {
      setCachedPalette(rawKey, palette);
    }
    return palette;
  } catch {
    const fallbackPalette = buildPaletteFromUrlHash(cacheKey);
    setCachedPalette(cacheKey, fallbackPalette);
    if (rawKey !== cacheKey) {
      setCachedPalette(rawKey, fallbackPalette);
    }
    return fallbackPalette;
  }
}

async function extractArtworkColorsWithJsDecoder(cacheKey: string): Promise<ArtworkPalette> {
  try {
    const localUri = await cacheRemoteArtwork(cacheKey);
    const bytes = await FileSystem.readAsStringAsync(localUri, {
      encoding: "base64",
    }).then(base64ToBytes).catch(() => new Uint8Array());

    if (bytes.length >= 2 && bytes[0] === 0xff && bytes[1] === 0xd8) {
      return extractPaletteFromJpeg(bytes);
    }
  } catch {
    // Graceful fallback
  }

  return buildPaletteFromUrlHash(cacheKey);
}

function extractPaletteFromJpeg(bytes: Uint8Array): ArtworkPalette {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const jpeg = require("jpeg-js") as {
    decode: (
      input: Uint8Array,
      options: { useTArray: boolean; formatAsRGBA: boolean; maxMemoryUsageInMB?: number }
    ) => { data: Uint8Array; width: number; height: number };
  };

  const { data, width, height } = jpeg.decode(bytes, {
    useTArray: true,
    formatAsRGBA: false, // 3 channels (RGB)
    maxMemoryUsageInMB: 6,
  });

  const swatchesRgb = sampleDominantSwatchesFromPixels(data, width, height, 3);
  const primary = swatchesRgb[0] || { r: 35, g: 45, b: 60 };
  const rawHexSwatches = swatchesRgb.map((s) => rgbToHex(s.r, s.g, s.b));
  const rawDomHex = rgbToHex(primary.r, primary.g, primary.b);
  const rawVibHex = rawHexSwatches[1] || rawDomHex;

  const background = transformToSeamlessBackground(rawDomHex);
  const accent = transformToVibrantAccent(rawVibHex);
  const swatches = dedupeAndDarkenSwatches(rawHexSwatches, background);

  return {
    background,
    accent,
    text: "#FFFFFF",
    isDark: true,
    primary: accent,
    rawDominant: rawDomHex,
    rawVibrant: rawVibHex,
    swatches,
  };
}

const PRESET_JEWEL_PALETTES: [string, string][] = [
  ["#0D2420", "#26E19A"], // Emerald Teal
  ["#111D30", "#3E8BFF"], // Sapphire Ocean
  ["#231530", "#A259FF"], // Royal Amethyst
  ["#281912", "#FF7A45"], // Sepia Ember
  ["#1F2420", "#52C41A"], // Forest Jade
  ["#28141F", "#FF4D88"], // Ruby Crimson
  ["#1A2228", "#13C2C2"], // Cyan Marine
  ["#221E14", "#FAAD14"], // Sunset Topaz
  ["#1A162B", "#8C65FF"], // Lavender Velvet
  ["#261B20", "#FF6B8B"], // Rose Plum
];

export function buildPaletteFromUrlHash(url: string): ArtworkPalette {
  let hash = 0;
  for (let i = 0; i < url.length; i++) {
    hash = (hash << 5) - hash + url.charCodeAt(i);
    hash |= 0;
  }
  const idx = Math.abs(hash) % PRESET_JEWEL_PALETTES.length;
  const [bg, accent] = PRESET_JEWEL_PALETTES[idx];
  const background = transformToSeamlessBackground(bg);
  const vibrantAccent = transformToVibrantAccent(accent);
  const swatches = dedupeAndDarkenSwatches([bg, accent]);
  return {
    background,
    accent: vibrantAccent,
    text: "#FFFFFF",
    isDark: true,
    primary: vibrantAccent,
    rawDominant: bg,
    rawVibrant: accent,
    swatches,
  };
}

function sampleDominantSwatchesFromPixels(
  data: Uint8Array,
  width: number,
  height: number,
  channels = 3
): { r: number; g: number; b: number }[] {
  const step = Math.max(6, Math.floor(Math.sqrt((width * height) / 350)));
  const bins: { rSum: number; gSum: number; bSum: number; count: number; maxSat: number }[] = Array.from(
    { length: 13 },
    () => ({ rSum: 0, gSum: 0, bSum: 0, count: 0, maxSat: 0 })
  );

  for (let y = 0; y < height; y += step) {
    for (let x = 0; x < width; x += step) {
      const index = (y * width + x) * channels;
      if (index + 2 >= data.length) continue;
      const alpha = channels === 4 ? data[index + 3] : 255;
      if (alpha < 32) continue;

      const r = data[index];
      const g = data[index + 1];
      const b = data[index + 2];
      const { h, s, l } = rgbToHsl(r, g, b);

      if (l < 0.06 || l > 0.94) continue;

      let binIdx = 12; // neutral
      if (s >= 0.10) {
        binIdx = Math.min(11, Math.floor(h / 30));
      }

      bins[binIdx].rSum += r;
      bins[binIdx].gSum += g;
      bins[binIdx].bSum += b;
      bins[binIdx].count += 1;
      bins[binIdx].maxSat = Math.max(bins[binIdx].maxSat, s);
    }
  }

  // Populate bins that have pixels
  const populated = bins.filter((b) => b.count > 0);

  if (populated.length === 0) {
    return [{ r: 83, g: 83, b: 86 }];
  }

  // 1. Dominant: Highest pixel count (true dominant color of the image)
  const sortedByCount = [...populated].sort((a, b) => b.count - a.count);
  const dominantBin = sortedByCount[0];

  // 2. Vibrant: Highest vibrancy / saturation (avoiding neutral bin 12 if possible)
  const coloredBins = populated.filter((b) => b !== bins[12] && b.maxSat >= 0.18);
  const vibrantBin =
    coloredBins.length > 0
      ? coloredBins.sort((a, b) => b.count * b.maxSat - a.count * a.maxSat)[0]
      : sortedByCount[1] || dominantBin;

  const result: { r: number; g: number; b: number }[] = [];
  result.push({
    r: Math.round(dominantBin.rSum / dominantBin.count),
    g: Math.round(dominantBin.gSum / dominantBin.count),
    b: Math.round(dominantBin.bSum / dominantBin.count),
  });

  if (vibrantBin !== dominantBin) {
    result.push({
      r: Math.round(vibrantBin.rSum / vibrantBin.count),
      g: Math.round(vibrantBin.gSum / vibrantBin.count),
      b: Math.round(vibrantBin.bSum / vibrantBin.count),
    });
  }

  for (const b of sortedByCount) {
    if (b !== dominantBin && b !== vibrantBin) {
      result.push({
        r: Math.round(b.rSum / b.count),
        g: Math.round(b.gSum / b.count),
        b: Math.round(b.bSum / b.count),
      });
    }
  }

  return result;
}

export function dedupeAndDarkenSwatches(swatches: (string | undefined | null)[], primaryBg?: string): string[] {
  const result: string[] = [];
  const seen = new Set<string>();

  if (primaryBg) {
    const dark = transformToSeamlessBackground(primaryBg);
    result.push(dark);
    seen.add(dark);
  }

  for (const raw of swatches) {
    const norm = normalizeHexColor(raw);
    if (!norm) continue;
    const dark = transformToSeamlessBackground(norm);
    if (!seen.has(dark)) {
      result.push(dark);
      seen.add(dark);
    }
    if (result.length >= 5) break;
  }

  // If fewer than 5 swatches, generate harmonious variations from primary base
  const base = result[0] || DEFAULT_ARTWORK_PALETTE.background;
  const baseRgb = {
    r: parseInt(base.slice(1, 3), 16),
    g: parseInt(base.slice(3, 5), 16),
    b: parseInt(base.slice(5, 7), 16),
  };
  const { h, s, l } = rgbToHsl(baseRgb.r, baseRgb.g, baseRgb.b);

  const hueOffsets = [35, -35, 70, 180, -70];
  let offsetIdx = 0;
  while (result.length < 5 && offsetIdx < hueOffsets.length) {
    const newH = (h + hueOffsets[offsetIdx] + 360) % 360;
    const newRgb = hslToRgb(newH, Math.max(0.40, s), Math.max(0.12, Math.min(0.20, l)));
    const hex = rgbToHex(newRgb.r, newRgb.g, newRgb.b);
    if (!seen.has(hex)) {
      result.push(hex);
      seen.add(hex);
    }
    offsetIdx++;
  }

  return result.slice(0, 5);
}

function buildSpotifyStylePaletteFromRgb(r: number, g: number, b: number): ArtworkPalette {
  const hex = rgbToHex(r, g, b);
  const background = transformToSeamlessBackground(hex);
  const accent = transformToVibrantAccent(hex);

  return {
    background,
    accent,
    text: "#FFFFFF",
    isDark: true,
    primary: accent,
    rawDominant: hex,
    rawVibrant: hex,
  };
}

async function buildArtworkSources(cacheKey: string): Promise<string[]> {
  const normalized = normalizeArtworkUrl(cacheKey);
  if (!normalized) return [];

  if (normalized.startsWith("file://") || normalized.startsWith("data:") || normalized.startsWith("content://")) {
    return [normalized];
  }

  if (!normalized.startsWith("http")) {
    return [normalized];
  }

  // On iOS: react-native-image-colors uses URLSession.shared.dataTask which directly downloads
  // HTTP/HTTPS in memory. Passing local file:// URLs to URLSession on iOS fails with error -1002 (unsupported URL).
  // Thus, the remote HTTPS URL must be the primary source on iOS.
  if (Platform.OS === "ios") {
    return [normalized];
  }

  // On Android, attempt caching for fast local decode, fallback to remote URL
  try {
    const localUri = await cacheRemoteArtwork(normalized);
    return [localUri, normalized];
  } catch {
    return [normalized];
  }
}

async function cacheRemoteArtwork(remoteUrl: string): Promise<string> {
  const extensionMatch = remoteUrl.match(/\.(jpe?g|png|webp|gif)(\?|#|$)/i);
  const extension = extensionMatch?.[1]?.toLowerCase() ?? "jpg";
  const fileName = `art-${hashString(remoteUrl)}.${extension}`;
  const cacheDir = FileSystem.cacheDirectory;
  if (!cacheDir) {
    throw new Error("Cache directory unavailable.");
  }
  const localUri = `${cacheDir}${fileName}`;

  try {
    const existing = await FileSystem.getInfoAsync(localUri).catch(() => ({ exists: false }));
    if (existing.exists) {
      return localUri;
    }
    const downloaded = await FileSystem.downloadAsync(remoteUrl, localUri);
    return downloaded.uri;
  } catch (e) {
    throw e;
  }
}

function mapImageColorsToPalette(result: ImageColorsResult): ArtworkPalette {
  if (result.platform === "ios") {
    const bgStats = getColorStats(result.background);
    const primaryStats = getColorStats(result.primary);
    const secondaryStats = getColorStats(result.secondary);
    const detailStats = getColorStats(result.detail);

    const candidates = [primaryStats, secondaryStats, detailStats, bgStats].filter(
      (c): c is NonNullable<typeof c> => c !== null && c.hex !== "#000000" && c.hex !== "#0E1016"
    );

    // Pick the most vibrant color as accent:
    // Vibrancy rewards saturation while avoiding pitch black or blinding white
    let bestAccent = candidates.length > 0
      ? candidates.slice().sort((a, b) => b.vibrancy - a.vibrancy)[0].hex
      : result.primary || result.detail || result.background || DEFAULT_ARTWORK_PALETTE.accent;

    // Pick the dominant background:
    // 1. If result.background has color (s >= 0.10) and is not washed-out white (l < 0.88), it's the natural dominant tone.
    // 2. If result.background is near-white or black/fallback, check for a rich colored candidate swatch.
    let bestDominant = result.background;
    if (!bgStats || bgStats.hex === "#000000" || bgStats.hex === "#0E1016" || bgStats.l > 0.88 || bgStats.s < 0.10) {
      const coloredCandidate = candidates.find((c) => c.s >= 0.15 && c.l >= 0.10 && c.l <= 0.85);
      if (coloredCandidate) {
        bestDominant = coloredCandidate.hex;
      } else if (bgStats && bgStats.hex !== "#000000" && bgStats.l < 0.88) {
        bestDominant = bgStats.hex;
      } else if (primaryStats && primaryStats.hex !== "#000000" && primaryStats.hex !== "#0E1016") {
        bestDominant = primaryStats.hex;
      } else {
        bestDominant = DEFAULT_ARTWORK_PALETTE.background;
      }
    }

    const rawDom = normalizeHexColor(bestDominant) ?? DEFAULT_ARTWORK_PALETTE.background;
    const rawVib = normalizeHexColor(bestAccent) ?? DEFAULT_ARTWORK_PALETTE.accent;

    const background = transformToSeamlessBackground(rawDom);
    const accent = transformToVibrantAccent(rawVib);

    const swatches = dedupeAndDarkenSwatches(
      [rawVib, rawDom, result.background, result.primary, result.secondary, result.detail],
      background
    );

    return {
      background,
      accent,
      text: "#FFFFFF",
      isDark: true,
      primary: accent,
      rawDominant: rawDom,
      rawVibrant: rawVib,
      swatches,
    };
  }

  // Android / Web: Prioritize true dominant color for background, and vibrant for accent
  const rawDom = pickColor(
    result.dominant,
    result.darkVibrant,
    result.vibrant,
    result.darkMuted,
    result.platform === "android" ? result.average : undefined
  ) ?? DEFAULT_ARTWORK_PALETTE.background;

  const rawVib = pickColor(
    result.vibrant,
    result.lightVibrant,
    result.darkVibrant,
    result.dominant,
    result.platform === "android" ? result.average : undefined
  ) ?? DEFAULT_ARTWORK_PALETTE.accent;

  const background = transformToSeamlessBackground(rawDom);
  const accent = transformToVibrantAccent(rawVib);

  const swatches = dedupeAndDarkenSwatches(
    [
      result.vibrant,
      result.lightVibrant,
      result.dominant,
      rawDom,
      result.darkVibrant,
      result.muted,
      result.platform === "android" ? result.average : undefined,
    ],
    background
  );

  return {
    background,
    accent,
    text: "#FFFFFF",
    isDark: true,
    primary: accent,
    rawDominant: rawDom,
    rawVibrant: rawVib,
    swatches,
  };
}

function buildPalette(background: string, accent: string, swatches?: string[]): ArtworkPalette {
  const bg = normalizeHexColor(background) ?? DEFAULT_ARTWORK_PALETTE.background;
  const darkBg = transformToSeamlessBackground(bg);
  const accentColor = normalizeHexColor(accent) ?? DEFAULT_ARTWORK_PALETTE.accent;
  const vibrantAccent = transformToVibrantAccent(accentColor);

  return {
    background: darkBg,
    accent: vibrantAccent,
    text: "#FFFFFF",
    isDark: true,
    primary: vibrantAccent,
    rawDominant: bg,
    rawVibrant: accentColor,
    swatches: swatches && swatches.length >= 3 ? swatches : dedupeAndDarkenSwatches([darkBg, vibrantAccent]),
  };
}

function isDefaultPalette(palette: ArtworkPalette): boolean {
  return (
    palette.background === DEFAULT_ARTWORK_PALETTE.background &&
    palette.accent === DEFAULT_ARTWORK_PALETTE.accent &&
    palette.rawDominant === DEFAULT_ARTWORK_PALETTE.rawDominant &&
    palette.rawVibrant === DEFAULT_ARTWORK_PALETTE.rawVibrant
  );
}

function setCachedPalette(key: string, value: ArtworkPalette): void {
  paletteCache.set(key, value);
  while (paletteCache.size > COLOR_CACHE_MAX_ENTRIES) {
    const oldestKey = paletteCache.keys().next().value;
    if (!oldestKey) break;
    paletteCache.delete(oldestKey);
  }
}

function pickColor(...candidates: (string | undefined | null)[]): string | null {
  for (const candidate of candidates) {
    const normalized = normalizeHexColor(candidate);
    if (normalized) return normalized;
  }
  return null;
}

function base64ToBytes(base64: string): Uint8Array {
  const binary = globalThis.atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function hashString(value: string): string {
  let hash = 0;
  for (let i = 0; i < value.length; i++) {
    hash = (hash << 5) - hash + value.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

function rgbToHex(r: number, g: number, b: number): string {
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

function rgbToHsl(r: number, g: number, b: number): { h: number; s: number; l: number } {
  const rn = r / 255;
  const gn = g / 255;
  const bn = b / 255;
  const max = Math.max(rn, gn, bn);
  const min = Math.min(rn, gn, bn);
  const delta = max - min;
  let h = 0;

  if (delta !== 0) {
    if (max === rn) h = ((gn - bn) / delta) % 6;
    else if (max === gn) h = (bn - rn) / delta + 2;
    else h = (rn - gn) / delta + 4;
    h *= 60;
    if (h < 0) h += 360;
  }

  const l = (max + min) / 2;
  const s = delta === 0 ? 0 : delta / (1 - Math.abs(2 * l - 1));
  return { h, s, l };
}

function hslToRgb(h: number, s: number, l: number): { r: number; g: number; b: number } {
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = l - c / 2;
  let rn = 0;
  let gn = 0;
  let bn = 0;

  if (h >= 0 && h < 60) {
    rn = c; gn = x; bn = 0;
  } else if (h < 120) {
    rn = x; gn = c; bn = 0;
  } else if (h < 180) {
    rn = 0; gn = c; bn = x;
  } else if (h < 240) {
    rn = 0; gn = x; bn = c;
  } else if (h < 300) {
    rn = x; gn = 0; bn = c;
  } else {
    rn = c; gn = 0; bn = x;
  }

  return {
    r: (rn + m) * 255,
    g: (gn + m) * 255,
    b: (bn + m) * 255,
  };
}

function normalizeHexColor(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const color = value.trim();
  if (!color) return null;

  if (/^[0-9a-fA-F]{6}$/.test(color)) {
    return `#${color.toUpperCase()}`;
  }

  if (/^[0-9a-fA-F]{3}$/.test(color)) {
    return `#${color[0]}${color[0]}${color[1]}${color[1]}${color[2]}${color[2]}`.toUpperCase();
  }

  const shortHexMatch = color.match(/^#([0-9a-fA-F]{3})$/);
  if (shortHexMatch) {
    const shortHex = shortHexMatch[1];
    return `#${shortHex[0]}${shortHex[0]}${shortHex[1]}${shortHex[1]}${shortHex[2]}${shortHex[2]}`.toUpperCase();
  }

  const fullHexMatch = color.match(/^#([0-9a-fA-F]{6})$/);
  if (fullHexMatch) {
    return `#${fullHexMatch[1].toUpperCase()}`;
  }

  const rgbaHexMatch = color.match(/^#([0-9a-fA-F]{8})$/);
  if (rgbaHexMatch) {
    return `#${rgbaHexMatch[1].slice(0, 6).toUpperCase()}`;
  }

  const rgbMatch = color.match(/^rgba?\((\d+),\s*(\d+),\s*(\d+)/i);
  if (rgbMatch) {
    const r = clamp(Number(rgbMatch[1]), 0, 255);
    const g = clamp(Number(rgbMatch[2]), 0, 255);
    const b = clamp(Number(rgbMatch[3]), 0, 255);
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  }

  return null;
}



function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function toHex(channel: number): string {
  return clamp(Math.round(channel), 0, 255).toString(16).padStart(2, "0").toUpperCase();
}

export function colorWithAlpha(hex: string, alpha: number, fallback = "rgba(255,255,255,1)"): string {
  const normalized = normalizeHexColor(hex);
  if (!normalized) return fallback;
  const r = parseInt(normalized.slice(1, 3), 16);
  const g = parseInt(normalized.slice(3, 5), 16);
  const b = parseInt(normalized.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${clamp(alpha, 0, 1)})`;
}

/**
 * Audio Quality — Utilities for quality-based audio URL selection
 */

import { type DownloadQuality } from "@/types/downloads";

/**
 * Map download quality preference to audio bitrate
 */
function qualityToBitrate(quality: DownloadQuality): string {
  switch (quality) {
    case "low":
      return "48kbps";
    case "medium":
      return "128kbps";
    case "high":
    default:
      return "320kbps";
  }
}

const JIOSAAVN_HOST_SUFFIXES = ["saavncdn.com", "saavn.com", "jiosaavn.com"] as const;

/**
 * Attempt to construct a quality-specific audio URL
 * JioSaavn CDN URLs encode the bitrate in the filename, e.g.:
 * - https://aac.saavncdn.com/<hash>/<bitrate>_<hash>.mp4
 * - https://preview.saavncdn.com/<hash>/<bitrate>_<hash>.mp4
 * Legacy responses may also embed /<bitrate>/ as a path segment.
 */
export function getAudioUrlByQuality(baseUrl: string, quality: DownloadQuality): string {
  if (!baseUrl || typeof baseUrl !== "string") {
    return baseUrl;
  }

  const targetBitrate = qualityToBitrate(quality);
  const bitrateNum = targetBitrate.replace("kbps", "");

  // Pattern 1: /320/ or /128/ or /96/ etc — but only on known audio CDN hosts
  // to avoid false positives on unrelated numeric path segments.
  try {
    const { host } = new URL(baseUrl);
    const isJioHost = JIOSAAVN_HOST_SUFFIXES.some((h) => host.endsWith(h));
    if (isJioHost) {
      const withSlashes = baseUrl.replace(
        /\/(?:320|256|192|160|128|96|64|48|32)\//g,
        `/${bitrateNum}/`
      );
      if (withSlashes !== baseUrl) {
        return withSlashes;
      }
    }
  } catch {
    // Not an absolute URL — skip the host-scoped slash pattern.
  }

  // Pattern 2: _320 or _128 etc in filename (the real JioSaavn encoding).
  // Anchored before a file extension, trailing underscore, or end of path.
  const withUnderscore = baseUrl.replace(/_(?:320|256|192|160|128|96|64|48|32)(?=\.|_|$)/g, `_${bitrateNum}`);
  if (withUnderscore !== baseUrl) {
    return withUnderscore;
  }

  // Pattern 3: -320 or -128 etc
  const withDash = baseUrl.replace(/-(?:320|256|192|160|128|96|64|48|32)(?=\.|_|$|-)/g, `-${bitrateNum}`);
  if (withDash !== baseUrl) {
    return withDash;
  }

  // If no pattern matched, return original URL
  // (it's likely already the best quality)
  return baseUrl;
}

/**
 * Get the bitrate for a download quality for UI display
 */
function getQualityLabel(quality: DownloadQuality): string {
  switch (quality) {
    case "low":
      return "~48 kbps";
    case "medium":
      return "~128 kbps";
    case "high":
    default:
      return "~320 kbps";
  }
}

/**
 * Device Info — stable deviceId and platform metadata for download device registration.
 */

import AsyncStorage from "@react-native-async-storage/async-storage";
import { logger } from "@/lib/logger";
import { IS_ANDROID, IS_IOS } from "@/constants/platform";

const KEY_DEVICE_ID = "@mavrixfy_device_id";

let cachedDeviceId: string | null = null;

/** Generate a random UUID-like string. */
function generateId(): string {
  const hex = () => Math.floor(Math.random() * 0x10000).toString(16).padStart(4, "0");
  return `${hex()}${hex()}-${hex()}-4${hex().slice(1)}-${hex()}-${hex()}${hex()}${hex()}`;
}

/**
 * Returns a stable device ID that persists across app restarts.
 * Generated once and stored in AsyncStorage.
 */
export async function getDeviceId(): Promise<string> {
  if (cachedDeviceId) return cachedDeviceId;

  try {
    const stored = await AsyncStorage.getItem(KEY_DEVICE_ID);
    if (stored) {
      cachedDeviceId = stored;
      return stored;
    }

    const newId = generateId();
    await AsyncStorage.setItem(KEY_DEVICE_ID, newId);
    cachedDeviceId = newId;
    return newId;
  } catch (err) {
    logger.error("[DeviceInfo] getDeviceId failed", err);
    // Return a session-only ID as fallback.
    const fallback = generateId();
    cachedDeviceId = fallback;
    return fallback;
  }
}

export interface DeviceInfo {
  platform: "android" | "ios" | "web";
  appVersion: string;
  modelName: string;
}

/** Returns basic device metadata for Firestore device registration. */
export function getDeviceInfo(): Promise<DeviceInfo> {
  let modelName = "Unknown Device";

  // Try to get the device model name from expo-device if available.
  try {
    const Device = require("expo-device");
    modelName = Device.modelName ?? Device.deviceName ?? "Unknown Device";
  } catch {
    // expo-device not available — use platform string.
    modelName = IS_ANDROID ? "Android Device" : IS_IOS ? "iOS Device" : "Web";
  }

  let appVersion = "1.0.0";
  try {
    const Constants = require("expo-constants");
    appVersion =
      Constants.default?.nativeAppVersion ??
      Constants.default?.expoConfig?.version ??
      Constants.default?.manifest?.version ??
      "1.0.0";
  } catch {
    // ignore
  }

  const platform: "android" | "ios" | "web" =
    IS_ANDROID ? "android" : IS_IOS ? "ios" : "web";

  return Promise.resolve({ platform, appVersion, modelName });
}

import { getAccountScope, isCurrentAccount } from "@/lib/accountScope";
/**
 * Download Manager — public API used by UI and playback.
 *
 * This is the single entry point for all download operations.
 * It enforces entitlement, device, territory, and storage rules before
 * delegating to the queue.
 */

import { type Song } from "@/lib/musicData";
import { type DownloadItem, type DownloadPreferences, type StorageSummary } from "@/types/downloads";
import {
  loadAllDownloads,
  loadDownload,
  getDownloadSync,
  saveDownload,
  removeDownload,
  patchDownload,
} from "@/lib/downloads/downloadStore";
import {
  enqueueDownload,
  pauseDownload,
  resumeDownload,
  cancelDownload,
  retryDownload,
  onQueueEvent,
} from "@/lib/downloads/downloadQueue";
import {
  getDownloadEntitlement,
  getTrackRights,
  isTerritoryAllowed,
} from "@/lib/downloads/entitlement";
import { issueOfflineLicense, refreshLicenses } from "@/lib/downloads/licenseSync";
import { deleteTrackFiles, deleteAllTrackFiles, trackFileExists, getTrackFileSize, type getTrackFileUri, getValidatedTrackFileUri, hasSufficientStorage } from "@/lib/downloads/filesystem";
import { logger } from "@/lib/logger";

// ─── Types ────────────────────────────────────────────────────────────────────

export type DownloadResult =
  | { ok: true }
  | { ok: false; reason: string };

// ─── Re-export event subscription ────────────────────────────────────────────

export { onQueueEvent };

// ─── Download a song ─────────────────────────────────────────────────────────

/**
 * Queue a song for download.
 *
 * Enforces:
 * - Entitlement (premium required)
 * - Device registration
 * - Track rights (offlineAllowed, territory)
 * - Storage safety
 * - Duplicate detection (idempotent)
 */
export async function downloadSong(
  song: Song,
  uid: string,
  prefs: DownloadPreferences,
  options?: {
    collectionId?: string;
    userCountry?: string | null;
  }
): Promise<DownloadResult> {
  try {
    const scope = getAccountScope();
    if (scope.accountId !== uid) return { ok: false, reason: "Account changed. Try again." };
    // 1. Check entitlement.
    const entitlement = await getDownloadEntitlement(uid);
    if (!entitlement.canDownload) {
      return { ok: false, reason: entitlement.blockedReason ?? "Downloads not available" };
    }

    // 2. Register device.
    // License issuance registers the device on the server.

    // 3. Storage safety check.
    const storageOk = await hasSufficientStorage();
    if (!storageOk) {
      return {
        ok: false,
        reason: "Low device storage. Free up space to continue downloading.",
      };
    }

    // 4. Track rights check.
    const rights = await getTrackRights(song.id);
    if (!rights.offlineAllowed) {
      return { ok: false, reason: "This track is not available for offline download." };
    }
    if (!isTerritoryAllowed(rights.territoryRights, options?.userCountry ?? null)) {
      return { ok: false, reason: "This track is not available in your region." };
    }

    // 5. Idempotency — if already downloaded or in progress, return ok.
    const existing = await loadDownload(song.id);
    if (existing) {
      if (existing.status === "completed") {
        return { ok: true };
      }
      if (
        existing.status === "downloading" ||
        existing.status === "queued" ||
        existing.status === "waiting_for_wifi" ||
        existing.status === "waiting_for_charging"
      ) {
        return { ok: true };
      }
    }

    const license = await issueOfflineLicense(uid, song.id, prefs.quality);
    // 6. Build the download item.
    const item: DownloadItem = {
      accountId: uid,
      songId: song.id,
      title: song.title,
      artist: song.artist,
      album: song.album ?? "",
      coverUrl: song.coverUrl ?? "",
      audioUrl: song.audioUrl,
      duration: song.duration,
      quality: license.quality,
      status: "queued",
      progress: 0,
      bytesDownloaded: 0,
      totalBytes: 0,
      localPath: null,
      collectionRefs: options?.collectionId ? [options.collectionId] : [],
      retryCount: 0,
      queuedAt: new Date().toISOString(),
      completedAt: null,
      failedAt: null,
      failureReason: null,
      licenseExpiresAt: license.expiresAt,
    };

    // 7. Persist and enqueue.
    if (!isCurrentAccount(scope)) return { ok: false, reason: "Account changed. Try again." };
    await saveDownload(item);
    await enqueueDownload(item, prefs);

    return { ok: true };
  } catch (err: any) {
    logger.error("[DownloadManager] downloadSong failed", err);
    return { ok: false, reason: err?.message ?? "Download failed unexpectedly" };
  }
}

// ─── Download a collection (album / playlist) ────────────────────────────────

export async function downloadCollection(
  songs: Song[],
  collectionId: string,
  uid: string,
  prefs: DownloadPreferences,
  userCountry?: string | null
): Promise<{ queued: number; skipped: number; failed: number }> {
  const results = await Promise.all(
    songs.map(async (song) => {
      const existing = getDownloadSync(song.id);
      if (existing?.status === "completed") {
        return "skipped" as const;
      }

      const res = await downloadSong(song, uid, prefs, {
        collectionId,
        userCountry,
      });

      return res.ok ? ("queued" as const) : ("failed" as const);
    })
  );

  let queued = 0;
  let skipped = 0;
  let failed = 0;

  for (const result of results) {
    if (result === "queued") {
      queued++;
    } else if (result === "skipped") {
      skipped++;
    } else {
      failed++;
    }
  }

  return { queued, skipped, failed };
}

// ─── Playback URL resolution ─────────────────────────────────────────────────

/**
 * Returns the local file URI for a song if it is fully downloaded and the
 * file physically exists and is non-empty on disk. Returns null otherwise.
 */
export async function getLocalPlaybackUrl(songId: string): Promise<string | null> {
  try {
    const item = await loadDownload(songId);
    if (!item || item.status !== "completed") return null;

    const expiry = item.licenseExpiresAt ? Date.parse(item.licenseExpiresAt) : NaN;
    if (!Number.isFinite(expiry) || Date.now() > expiry + 7 * 24 * 60 * 60 * 1000) return null;
    return getValidatedTrackFileUri(songId);
  } catch {
    return null;
  }
}

// ─── Queue management ─────────────────────────────────────────────────────────

export async function pauseSongDownload(songId: string): Promise<void> {
  await pauseDownload(songId);
}

export async function resumeSongDownload(
  songId: string,
  prefs: DownloadPreferences
): Promise<void> {
  await resumeDownload(songId, prefs);
}

export async function retrySongDownload(
  songId: string,
  prefs: DownloadPreferences
): Promise<void> {
  await retryDownload(songId, prefs);
}

/**
 * Remove a song download and delete its local audio and artwork files.
 */
export async function removeSongDownload(songId: string): Promise<void> {
  try {
    await Promise.all([
      cancelDownload(songId),
      deleteTrackFiles(songId),
      removeDownload(songId),
    ]);
  } catch (err) {
    logger.error("[DownloadManager] removeSongDownload failed", err);
  }
}

/** Remove all downloaded songs and delete all track files. */
export async function removeAllDownloads(): Promise<void> {
  try {
    const all = await loadAllDownloads();
    await Promise.all(all.map((item) => cancelDownload(item.songId)));
    await deleteAllTrackFiles();
    await Promise.all(all.map((item) => removeDownload(item.songId)));
  } catch (err) {
    logger.error("[DownloadManager] removeAllDownloads failed", err);
  }
}

// ─── License sync ────────────────────────────────────────────────────────────

/**
 * Sync licenses with Firestore. Revokes local playback for any tracks whose
 * licenses have expired or been revoked server-side.
 */
export async function syncLicenses(uid: string): Promise<void> {
  try {
    const revokedIds = await refreshLicenses(uid);

    await Promise.all(
      [...revokedIds].map((songId) =>
        patchDownload(songId, {
          status: "revoked",
          licenseExpiresAt: null,
        })
      )
    );
  } catch (err) {
    logger.error("[DownloadManager] syncLicenses failed", err);
  }
}

// ─── Storage summary ──────────────────────────────────────────────────────────

export async function getStorageSummary(): Promise<StorageSummary> {
  try {
    const all = await loadAllDownloads();
    let totalBytes = 0;
    let completed = 0;
    let pending = 0;
    let failed = 0;

    const completedSizes = await Promise.all(
      all.map(async (item) => {
        if (item.status === "completed") {
          return { status: "completed" as const, size: await getTrackFileSize(item.songId) };
        }
        if (
          item.status === "queued" ||
          item.status === "downloading" ||
          item.status === "paused" ||
          item.status === "waiting_for_wifi" ||
          item.status === "waiting_for_charging"
        ) {
          return { status: "pending" as const, size: 0 };
        }
        if (item.status === "failed") {
          return { status: "failed" as const, size: 0 };
        }
        return { status: "other" as const, size: 0 };
      })
    );

    for (const item of completedSizes) {
      if (item.status === "completed") {
        completed++;
        totalBytes += item.size;
      } else if (item.status === "pending") {
        pending++;
      } else if (item.status === "failed") {
        failed++;
      }
    }

    return {
      totalDownloadedBytes: totalBytes,
      totalDownloadedTracks: completed + pending + failed,
      completedTracks: completed,
      pendingTracks: pending,
      failedTracks: failed,
    };
  } catch {
    return {
      totalDownloadedBytes: 0,
      totalDownloadedTracks: 0,
      completedTracks: 0,
      pendingTracks: 0,
      failedTracks: 0,
    };
  }
}

// ─── Query helpers ────────────────────────────────────────────────────────────

export function getAllDownloads(): Promise<DownloadItem[]> {
  return loadAllDownloads();
}

export function getSongDownload(songId: string): Promise<DownloadItem | null> {
  return loadDownload(songId);
}

export async function isDownloaded(songId: string): Promise<boolean> {
  const item = await loadDownload(songId);
  if (item?.status !== "completed") return false;
  return trackFileExists(songId);
}

import { getAccountScope, isCurrentAccount } from "@/lib/accountScope";
/**
 * Download Queue — concurrency-limited, race-condition-free download engine.
 *
 * Design:
 * - MAX_CONCURRENT downloads run at once (default 2). Others wait in a pending list.
 * - A per-song mutex (startingSet) prevents two concurrent calls for the same song
 *   from both passing the "already running" guard.
 * - Progress callbacks update the in-memory store only (no AsyncStorage read per tick).
 * - When a slot frees up, the next pending song is automatically started.
 */

import {
  createDownloadResumable,
  DownloadResumable,
} from "expo-file-system/legacy";
import { type DownloadItem, type DownloadStatus, type DownloadPreferences } from "@/types/downloads";
import {
  saveDownload,
  loadDownload,
  updateDownloadMemory,
} from "@/lib/downloads/downloadStore";
import {
  ensureDownloadsDirs,
  getTempDownloadUri,
  getTrackFileUri,
  getArtworkFileUri,
  promoteTempToTrack,
  hasSufficientStorage,
} from "@/lib/downloads/filesystem";
import { getAudioUrlByQuality } from "@/lib/downloads/audioQuality";
import { getMusicApiUrl } from "@/lib/api-config";
import { getBestAudioUrlWithQuality } from "@/lib/musicData";
import { logger } from "@/lib/logger";
import * as Network from "expo-network";

// ─── Concurrency config ───────────────────────────────────────────────────────

const MAX_CONCURRENT = 2;
let suspended = false;
const runningTasks = new Set<Promise<void>>();

// ─── Event emitter ────────────────────────────────────────────────────────────

type QueueEventType = "progress" | "status" | "completed" | "failed";
type QueueListener = (songId: string, item: DownloadItem) => void;

const listeners = new Map<QueueEventType, Set<QueueListener>>();

export function onQueueEvent(event: QueueEventType, fn: QueueListener): () => void {
  if (!listeners.has(event)) listeners.set(event, new Set());
  listeners.get(event)!.add(fn);
  return () => listeners.get(event)?.delete(fn);
}

function emitQueueEvent(event: QueueEventType, songId: string, item: DownloadItem) {
  listeners.get(event)?.forEach((fn) => {
    try { fn(songId, item); } catch { /* ignore */ }
  });
}

// ─── Queue state ──────────────────────────────────────────────────────────────

/** Songs actively downloading right now. */
const activeHandles = new Map<string, DownloadResumable>();

/** Songs waiting for a free slot. */
const pendingQueue: string[] = [];

/** Guards against two concurrent startDownload calls for the same songId. */
const startingSet = new Set<string>();
const lastProgressPersistAt = new Map<string, number>();
const retryTimers = new Map<string, ReturnType<typeof setTimeout>>();
const wifiOnlySongs = new Set<string>();
let networkListener: { remove: () => void } | null = null;
const PROGRESS_PERSIST_INTERVAL_MS = 1500;

// ─── Slot management ──────────────────────────────────────────────────────────

function activeCount(): number {
  return new Set([...activeHandles.keys(), ...startingSet]).size;
}

function launchDownload(songId: string): void {
  startingSet.add(songId);
  const task = executeDownload(songId).catch((error) => {
    logger.error("[DownloadQueue] Could not start download", { songId, error });
  }).finally(() => {
    startingSet.delete(songId);
    runningTasks.delete(task);
    drainQueue();
  });
  runningTasks.add(task);
}

/** Called when a download finishes (success, fail, or cancel) to free its slot. */
function releaseSlot(songId: string) {
  activeHandles.delete(songId);
  startingSet.delete(songId);
  lastProgressPersistAt.delete(songId);
  drainQueue();
}

function clearRetryTimer(songId: string): void {
  const timer = retryTimers.get(songId);
  if (timer) {
    clearTimeout(timer);
    retryTimers.delete(songId);
  }
}

function hasWifi(type?: Network.NetworkStateType): boolean {
  return type === Network.NetworkStateType.WIFI || type === Network.NetworkStateType.ETHERNET;
}

function watchWifi(): void {
  if (networkListener) return;
  networkListener = Network.addNetworkStateListener(({ type }) => {
    for (const songId of wifiOnlySongs) {
      void loadDownload(songId).then(async (item) => {
        if (!item || item.status === "completed" || item.status === "deleted") {
          wifiOnlySongs.delete(songId);
          return;
        }
        if (hasWifi(type)) {
          if (item.status === "waiting_for_wifi") void startDownload(songId);
        } else if (item.status === "downloading" || item.status === "queued") {
          await pauseDownload(songId);
          await updateStatus(songId, "waiting_for_wifi");
        }
      });
    }
  });
}

/** Start the next pending song if a slot is free. */
function drainQueue() {
  if (suspended) return;
  while (activeCount() < MAX_CONCURRENT && pendingQueue.length > 0) {
    const next = pendingQueue.shift()!;
    // Fire and forget — errors are handled inside executeDownload
    launchDownload(next);
  }
}

// ─── Status helper ────────────────────────────────────────────────────────────

async function updateStatus(
  songId: string,
  status: DownloadStatus,
  extra?: Partial<DownloadItem>
): Promise<DownloadItem | null> {
  const item = await loadDownload(songId);
  if (!item) return null;
  const updated: DownloadItem = { ...item, status, ...extra };
  await saveDownload(updated);
  emitQueueEvent("status", songId, updated);
  return updated;
}

// ─── URL refresh ─────────────────────────────────────────────────────────────

/**
 * Resolve all redirects to get the final download URL.
 * This is critical for Gaana URLs which use multiple redirects.
 */
async function resolveRedirects(url: string): Promise<string> {
  try {
    let currentUrl = url;
    let redirectCount = 0;
    const MAX_REDIRECTS = 10;

    while (redirectCount < MAX_REDIRECTS) {
      const response = await fetch(currentUrl, {
        method: 'HEAD',
        redirect: 'manual', // Don't follow redirects automatically
      });

      // Check if it's a redirect (301, 302, 307, 308)
      if (response.status >= 300 && response.status < 400) {
        const location = response.headers.get('location');
        if (!location) break;

        // Handle relative URLs
        currentUrl = location.startsWith('http') 
          ? location 
          : new URL(location, currentUrl).href;

        redirectCount++;
        logger.debug(`[DownloadQueue] Redirect ${redirectCount}: ${currentUrl.substring(0, 100)}...`);
      } else {
        // No more redirects
        break;
      }
    }

    if (currentUrl !== url) {
      logger.info(`[DownloadQueue] Resolved ${redirectCount} redirects for download`);
    }

    return currentUrl;
  } catch (err) {
    logger.warn('[DownloadQueue] Failed to resolve redirects, using original URL', err);
    return url;
  }
}

/**
 * Fetch a fresh downloadUrl for a JioSaavn song right before starting the
 * actual download. CDN signed URLs expire in ~15–30 minutes, so the URL stored
 * in the queue at the time the user tapped "Download" may already be stale by
 * the time the download slot opens.
 *
 * Falls back to the original URL if the API call fails or times out.
 */
async function refreshAudioUrl(songId: string, originalUrl: string, quality: DownloadItem["quality"]): Promise<string> {
  // Only attempt refresh for JioSaavn songs (numeric IDs or short alphanumeric)
  // YouTube and Cloudinary URLs have their own expiry handling
  if (!songId || songId.startsWith("youtube_") || originalUrl.includes("cloudinary")) {
    return getAudioUrlByQuality(originalUrl, quality);
  }

  try {
    const apiBase = getMusicApiUrl().replace(/\/$/, "");
    const url = `${apiBase}/songs?id=${encodeURIComponent(songId)}`;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 8000);

    const res = await fetch(url, {
      headers: { Accept: "application/json" },
      signal: controller.signal,
    });
    clearTimeout(timer);

    if (!res.ok) throw new Error(`API ${res.status}`);
    const json = await res.json();

    // Response shape: { success: true, data: { songs: [...] } } or { success: true, data: [...] }
    const songs: any[] =
      Array.isArray(json?.data) ? json.data :
      Array.isArray(json?.data?.songs) ? json.data.songs :
      Array.isArray(json?.data?.results) ? json.data.results :
      [];

    const song = songs[0];
    const freshDownloadUrl = song?.downloadUrl ?? song?.download_url ?? song?.audioUrl;

    if (freshDownloadUrl) {
      const qualityMap = { low: "low" as const, medium: "medium" as const, high: "high" as const };
      const resolved = getBestAudioUrlWithQuality(freshDownloadUrl, qualityMap[quality] ?? "high");
      if (resolved && resolved.startsWith("http")) {
        logger.debug("[DownloadQueue] Refreshed audio URL for", songId);
        return resolved;
      }
    }
  } catch (err: any) {
    logger.warn("[DownloadQueue] URL refresh failed, using original", { songId, error: err?.message });
  }

  return getAudioUrlByQuality(originalUrl, quality);
}

// ─── Core download execution ──────────────────────────────────────────────────

async function executeDownload(songId: string): Promise<void> {
  // Double-check guard — prevents re-entry if somehow called twice
  if (suspended || activeHandles.has(songId)) return;

  const item = await loadDownload(songId);
  if (!item) return;

  if (wifiOnlySongs.has(songId) && !hasWifi((await Network.getNetworkStateAsync()).type)) {
    await updateStatus(songId, "waiting_for_wifi");
    return;
  }

  // If it was cancelled while waiting in the pending queue, skip it
  if (item.status === "deleted" || item.status === "completed") return;

  const tempUri = getTempDownloadUri(songId);
  const finalUri = getTrackFileUri(songId);

  // Fetch fresh audio URL and resolve redirects while updating status and ensuring directories in parallel
  const [, , audioUrl] = await Promise.all([
    ensureDownloadsDirs(),
    updateStatus(songId, "downloading"),
    refreshAudioUrl(songId, item.audioUrl, item.quality).then(resolveRedirects),
  ]);
  if (suspended || (await loadDownload(songId))?.status !== "downloading") return;

  const handle = createDownloadResumable(
    audioUrl,
    tempUri,
    {},
    (progress) => {
      // Progress callback: update cache only — no AsyncStorage read per tick
      const { totalBytesWritten, totalBytesExpectedToWrite } = progress;
      const pct =
        totalBytesExpectedToWrite > 0
          ? Math.round((totalBytesWritten / totalBytesExpectedToWrite) * 100)
          : 0;

      // Read from cache synchronously (no await needed — cache is always current)
      loadDownload(songId).then((current) => {
        if (!current || current.status !== "downloading") return;
        const patched: DownloadItem = {
          ...current,
          progress: pct,
          bytesDownloaded: totalBytesWritten,
          totalBytes: totalBytesExpectedToWrite,
        };
        updateDownloadMemory(patched);
        emitQueueEvent("progress", songId, patched);

        const now = Date.now();
        const lastPersistedAt = lastProgressPersistAt.get(songId) ?? 0;
        if (now - lastPersistedAt >= PROGRESS_PERSIST_INTERVAL_MS || pct >= 100) {
          lastProgressPersistAt.set(songId, now);
          void saveDownload(patched);
        }
      });
    }
  );

  activeHandles.set(songId, handle);

  try {
    const result = await handle.downloadAsync();

    if (!result) {
      // Paused / cancelled by user
      if ((await loadDownload(songId))?.status === "downloading") {
        await updateStatus(songId, "paused");
      }
      releaseSlot(songId);
      return;
    }

    if ((await loadDownload(songId))?.status !== "downloading") {
      const { deleteAsync } = await import("expo-file-system/legacy");
      await deleteAsync(tempUri, { idempotent: true }).catch(() => {});
      releaseSlot(songId);
      return;
    }

    const contentType = result.headers?.["Content-Type"] || result.headers?.["content-type"] || "";
    if (result.status < 200 || result.status >= 300 || /^(text\/|application\/(json|xml))/i.test(contentType)) {
      throw new Error(`Audio download returned HTTP ${result.status}${contentType ? ` (${contentType})` : ""}`);
    }

    // Atomically promote verified temp file to final permanent track location
    const promoted = await promoteTempToTrack(songId);
    if (!promoted) {
      logger.warn("[DownloadQueue] Downloaded temp file verification failed", { songId });
      const { deleteAsync } = await import("expo-file-system/legacy");
      await deleteAsync(tempUri, { idempotent: true }).catch(() => {});
      await updateStatus(songId, "failed", {
        failureReason: "Downloaded file was empty or missing — stream URL may have expired",
        failedAt: new Date().toISOString(),
      });
      releaseSlot(songId);
      return;
    }

    // Optional background artwork download (non-blocking)
    if (item.coverUrl && item.coverUrl.startsWith("http")) {
      const artworkUri = getArtworkFileUri(songId);
      const { downloadAsync } = await import("expo-file-system/legacy");
      downloadAsync(item.coverUrl, artworkUri).catch(() => {});
    }

    const completedItem = await updateStatus(songId, "completed", {
      progress: 100,
      localPath: finalUri,
      totalBytes: result.headers?.["Content-Length"]
        ? parseInt(result.headers["Content-Length"], 10)
        : (result as any).totalBytesExpectedToWrite ?? 0,
      bytesDownloaded: (result as any).totalBytesWritten ?? 0,
      completedAt: new Date().toISOString(),
      failureReason: null,
      failedAt: null,
    });

    if (completedItem) emitQueueEvent("completed", songId, completedItem);
    releaseSlot(songId);

  } catch (err: any) {
    const { deleteAsync } = await import("expo-file-system/legacy");
    await deleteAsync(tempUri, { idempotent: true }).catch(() => {});
    const wasCancelled =
      err?.code === "ERR_TASK_CANCELLED" ||
      err?.message?.includes("cancel") ||
      err?.message?.includes("cancelled");

    if (wasCancelled) {
      if ((await loadDownload(songId))?.status === "downloading") {
        await updateStatus(songId, "paused");
      }
      releaseSlot(songId);
      return;
    }

    logger.error("[DownloadQueue] download failed", { songId, error: err?.message });

    const current = await loadDownload(songId);
    const retryCount = (current?.retryCount ?? 0) + 1;
    const MAX_RETRIES = 3;

    releaseSlot(songId); // free the slot before retry delay

    if (!suspended && retryCount <= MAX_RETRIES) {
      await updateStatus(songId, "queued", {
        retryCount,
        failureReason: err?.message ?? "Unknown error",
        failedAt: new Date().toISOString(),
      });
      // Delays for attempts 1, 2, 3 → 2s, 5s, 10s (exponential backoff).
      const delays = [2000, 5000, 10000];
      clearRetryTimer(songId);
      const retryTimer = setTimeout(async () => {
        retryTimers.delete(songId);
        const latest = await loadDownload(songId);
        if (!latest || latest.status !== "queued") return;
        // Re-add to pending queue for the next available slot
        if (!pendingQueue.includes(songId) && !activeHandles.has(songId)) {
          pendingQueue.push(songId);
          drainQueue();
        }
      }, delays[retryCount - 1] ?? 10000);
      retryTimers.set(songId, retryTimer);
    } else {
      const failedItem = await updateStatus(songId, "failed", {
        retryCount,
        failureReason: err?.message ?? "Download failed after retries",
        failedAt: new Date().toISOString(),
      });
      if (failedItem) emitQueueEvent("failed", songId, failedItem);
    }
  }
}

// ─── Public API ───────────────────────────────────────────────────────────────

export async function enqueueDownload(
  item: DownloadItem,
  prefs: DownloadPreferences
): Promise<void> {
  const scope = getAccountScope();
  if (suspended || (item.accountId && item.accountId !== scope.accountId)) return;
  const songId = item.songId;
  clearRetryTimer(songId);

  // Idempotency: skip if already active or pending
  if (activeHandles.has(songId) || pendingQueue.includes(songId) || startingSet.has(songId)) {
    return;
  }

  startingSet.add(songId);
  if (prefs.wifiOnly) {
    wifiOnlySongs.add(songId);
    watchWifi();
  } else {
    wifiOnlySongs.delete(songId);
  }
  await saveDownload({ ...item, status: "queued" });
  emitQueueEvent("status", songId, { ...item, status: "queued" });

  const hasSpace = await hasSufficientStorage();
  if (!hasSpace) {
    await updateStatus(songId, "paused", { failureReason: "Insufficient storage" });
    startingSet.delete(songId);
    return;
  }

  if (prefs.wifiOnly && !hasWifi((await Network.getNetworkStateAsync()).type)) {
    await updateStatus(songId, "waiting_for_wifi");
    startingSet.delete(songId);
    return;
  }

  if (suspended || !isCurrentAccount(scope)) { startingSet.delete(songId); return; }
  if (activeCount() <= MAX_CONCURRENT) {
    launchDownload(songId);
  } else {
    // Queue it — will start when a slot opens
    startingSet.delete(songId);
    pendingQueue.push(songId);
    await updateStatus(songId, "queued");
  }
}

async function startDownload(songId: string): Promise<void> {
  clearRetryTimer(songId);
  if (suspended || activeHandles.has(songId) || startingSet.has(songId)) return;

  if (activeCount() < MAX_CONCURRENT) {
    launchDownload(songId);
  } else {
    if (!pendingQueue.includes(songId)) {
      pendingQueue.push(songId);
    }
    await updateStatus(songId, "queued");
  }
}

export async function pauseDownload(songId: string): Promise<void> {
  clearRetryTimer(songId);
  // Remove from pending queue if waiting
  const pendingIdx = pendingQueue.indexOf(songId);
  if (pendingIdx !== -1) pendingQueue.splice(pendingIdx, 1);

  const handle = activeHandles.get(songId);
  if (handle) {
    try { await handle.pauseAsync(); } catch { /* ignore */ }
    // releaseSlot called inside executeDownload catch block
  }
  await updateStatus(songId, "paused");
}

export async function resumeDownload(
  songId: string,
  prefs: DownloadPreferences
): Promise<void> {
  const item = await loadDownload(songId);
  if (!item) return;
  clearRetryTimer(songId);
  if (item.status !== "paused" && item.status !== "queued" && item.status !== "failed" && item.status !== "waiting_for_wifi") return;
  if (activeHandles.has(songId) || startingSet.has(songId)) return;

  const hasSpace = await hasSufficientStorage();
  if (!hasSpace) {
    void updateStatus(songId, "paused", { failureReason: "Insufficient storage" });
    return;
  }

  if (prefs.wifiOnly) {
    wifiOnlySongs.add(songId);
    watchWifi();
    if (!hasWifi((await Network.getNetworkStateAsync()).type)) {
      await updateStatus(songId, "waiting_for_wifi");
      return;
    }
  } else {
    wifiOnlySongs.delete(songId);
  }

  return startDownload(songId);
}

export async function cancelDownload(songId: string): Promise<void> {
  wifiOnlySongs.delete(songId);
  clearRetryTimer(songId);
  // Remove from pending queue
  const pendingIdx = pendingQueue.indexOf(songId);
  if (pendingIdx !== -1) pendingQueue.splice(pendingIdx, 1);

  const handle = activeHandles.get(songId);
  if (handle) {
    try { await handle.cancelAsync(); } catch { /* ignore */ }
    releaseSlot(songId);
  }
  await updateStatus(songId, "deleted");
}

export function retryDownload(
  songId: string,
  prefs: DownloadPreferences
): Promise<void> {
  clearRetryTimer(songId);
  void updateStatus(songId, "queued", {
    retryCount: 0,
    failureReason: null,
    failedAt: null,
  });
  return resumeDownload(songId, prefs);
}

/** How many downloads are currently active (for debug/UI). */
function getActiveDownloadCount(): number {
  return activeHandles.size;
}

/** How many downloads are waiting for a slot (for debug/UI). */
function getPendingQueueLength(): number {
  return pendingQueue.length;
}

export async function suspendDownloadQueue(): Promise<void> {
  suspended = true;
  pendingQueue.length = 0;
  wifiOnlySongs.clear();
  networkListener?.remove();
  networkListener = null;
  for (const songId of retryTimers.keys()) clearRetryTimer(songId);
  await Promise.allSettled([...activeHandles.values()].map(handle => handle.cancelAsync()));
  await Promise.allSettled([...runningTasks]);
  activeHandles.clear();
  startingSet.clear();
}
export function resumeDownloadQueue(): void { suspended = false; }

import { getAccountScope } from "@/lib/accountScope";
/**
 * Filesystem — Canonical paths, directory setup, and file operations for offline downloads.
 *
 * Persistent directory layout:
 *   <documentDirectory>/mavrixfy_downloads/
 *     ├── tracks/
 *     │   └── <songId>/
 *     │       ├── track.mp3
 *     │       └── artwork.jpg
 *     └── temp/
 *         └── <songId>.download
 */

import { Platform } from "react-native";
import {
  documentDirectory,
  getInfoAsync,
  makeDirectoryAsync,
  deleteAsync,
  moveAsync,
  getFreeDiskStorageAsync,
} from "expo-file-system/legacy";
import { MIN_FREE_STORAGE_BYTES } from "@/types/downloads";
import { logger } from "@/lib/logger";

// ─── Canonical Paths ──────────────────────────────────────────────────────────

/** Root directory URI for all offline downloads (in persistent app storage). */
export function getDownloadsRootUri(): string {
  const base = documentDirectory ?? "";
  return `${base}mavrixfy_downloads/accounts/${encodeURIComponent(getAccountScope().accountId ?? "guest")}/`;
}

export function getTracksRootUri(): string {
  return `${getDownloadsRootUri()}tracks/`;
}

export function getTempRootUri(): string {
  return `${getDownloadsRootUri()}temp/`;
}

export function getTrackDirUri(songId: string): string {
  return `${getTracksRootUri()}${encodeURIComponent(songId)}/`;
}

/** Full file URI for a permanent downloaded track. */
export function getTrackFileUri(songId: string): string {
  return `${getTrackDirUri(songId)}track.mp3`;
}

/** In-flight temporary download file URI. */
export function getTempDownloadUri(songId: string): string {
  return `${getTempRootUri()}${encodeURIComponent(songId)}.download`;
}

/** Full file URI for offline artwork. */
export function getArtworkFileUri(songId: string): string {
  return `${getTrackDirUri(songId)}artwork.jpg`;
}

// ─── Directory Management ────────────────────────────────────────────────────

/** Ensure the downloads and temp directories exist in persistent storage. */
export async function ensureDownloadsDirs(): Promise<void> {
  try {
    const root = getDownloadsRootUri();
    const tracks = getTracksRootUri();
    const temp = getTempRootUri();

    const [rootInfo, tracksInfo, tempInfo] = await Promise.all([
      getInfoAsync(root),
      getInfoAsync(tracks),
      getInfoAsync(temp),
    ]);

    if (!rootInfo.exists) {
      await makeDirectoryAsync(root, { intermediates: true });
    }
    if (!tracksInfo.exists) {
      await makeDirectoryAsync(tracks, { intermediates: true });
    }
    if (!tempInfo.exists) {
      await makeDirectoryAsync(temp, { intermediates: true });
    }

    if (Platform.OS === "ios") {
      try {
        const ExpoFS = require("expo-file-system/legacy");
        if (typeof ExpoFS.setExcludedFromBackupAsync === "function") {
          await ExpoFS.setExcludedFromBackupAsync(root, true);
        }
      } catch {
        // Fall through
      }
    }
  } catch (err) {
    logger.error("[Filesystem] ensureDownloadsDirs failed", err);
  }
}

/** Ensure directory for a specific track exists. */
export async function ensureTrackDir(songId: string): Promise<void> {
  try {
    const dir = getTrackDirUri(songId);
    const info = await getInfoAsync(dir);
    if (!info.exists) {
      await makeDirectoryAsync(dir, { intermediates: true });
    }
  } catch (err) {
    logger.error("[Filesystem] ensureTrackDir failed", err);
  }
}

// ─── Storage Checks ──────────────────────────────────────────────────────────

/** Returns true if there is enough free disk space to start a download. */
export async function hasSufficientStorage(): Promise<boolean> {
  if (Platform.OS === "web") return true;
  try {
    const free = await getFreeDiskStorageAsync();
    return free > MIN_FREE_STORAGE_BYTES;
  } catch {
    return true;
  }
}

// ─── File Validation & Operations ────────────────────────────────────────────

/**
 * Returns the local audio file URI if the file physically exists and is non-empty.
 * Otherwise returns null.
 */
export async function getValidatedTrackFileUri(songId: string): Promise<string | null> {
  try {
    const uri = getTrackFileUri(songId);
    const info = await getInfoAsync(uri);
    if (info.exists && !info.isDirectory && ((info as any).size ?? 0) > 1024) {
      return uri.startsWith("file://") ? uri : `file://${uri}`;
    }
    return null;
  } catch {
    return null;
  }
}

/** Check whether a valid non-empty audio file exists for the song. */
export async function trackFileExists(songId: string): Promise<boolean> {
  const uri = await getValidatedTrackFileUri(songId);
  return Boolean(uri);
}

/** Get the byte size of a track file, or 0 if missing. */
export async function getTrackFileSize(songId: string): Promise<number> {
  try {
    const info = await getInfoAsync(getTrackFileUri(songId));
    if (!info.exists) return 0;
    return (info as any).size ?? 0;
  } catch {
    return 0;
  }
}

/** Atomically moves completed temp file into final track location. */
export async function promoteTempToTrack(songId: string): Promise<boolean> {
  try {
    const tempUri = getTempDownloadUri(songId);
    const destUri = getTrackFileUri(songId);

    const tempInfo = await getInfoAsync(tempUri);
    if (!tempInfo.exists || ((tempInfo as any).size ?? 0) < 1024) {
      return false;
    }

    await ensureTrackDir(songId);
    await moveAsync({ from: tempUri, to: destUri });
    return true;
  } catch (err) {
    logger.error("[Filesystem] promoteTempToTrack failed", err);
    return false;
  }
}

/** Delete track audio & artwork files. */
export async function deleteTrackFiles(songId: string): Promise<void> {
  try {
    const dir = getTrackDirUri(songId);
    const temp = getTempDownloadUri(songId);
    await Promise.all([
      deleteAsync(dir, { idempotent: true }).catch(() => {}),
      deleteAsync(temp, { idempotent: true }).catch(() => {}),
    ]);
  } catch (err) {
    logger.error("[Filesystem] deleteTrackFiles failed", err);
  }
}

/** Delete all downloaded tracks and temp files. */
export async function deleteAllTrackFiles(): Promise<void> {
  try {
    const root = getDownloadsRootUri();
    await deleteAsync(root, { idempotent: true }).catch(() => {});
    await ensureDownloadsDirs();
  } catch (err) {
    logger.error("[Filesystem] deleteAllTrackFiles failed", err);
  }
}

// ─── Utilities ───────────────────────────────────────────────────────────────

export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB", "PB"];
  const i = Math.min(units.length - 1, Math.floor(Math.log(bytes) / Math.log(1024)));
  const value = bytes / Math.pow(1024, i);
  return `${value.toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}

import { type ParsedSong, type FileParseResult } from "@/types/import";

/**
 * Parse CSV file content
 * Handles quoted fields, multiple formats, and headers
 * Enhanced to support Spotify export format with Track URI, ISRC, etc.
 */
function parseCSV(content: string): FileParseResult {
  const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');
  const songs: ParsedSong[] = [];
  const errors: string[] = [];

  if (lines.length === 0) {
    return { songs: [], errors: ['File is empty'], totalLines: 0 };
  }

  // Parse CSV line handling quoted fields
  const parseCSVLine = (line: string): string[] => {
    const result: string[] = [];
    let current = '';
    let inQuotes = false;
    
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      const nextChar = line[i + 1];
      
      if (char === '"') {
        if (inQuotes && nextChar === '"') {
          current += '"';
          i++; // Skip next quote
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char === ',' && !inQuotes) {
        result.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    result.push(current.trim());
    return result;
  };

  // Parse header to detect column indices
  const headerLine = parseCSVLine(lines[0]);
  const headers = headerLine.map(h => h.toLowerCase().trim());
  
  // Detect column indices for Spotify format and generic formats
  const trackUriIdx = headers.findIndex(h => h.includes('track uri'));
  const trackNameIdx = headers.findIndex(h => 
    h.includes('track name') || h.includes('song') || h.includes('title') || h === 'name'
  );
  const artistNameIdx = headers.findIndex(h => 
    h.includes('artist name') && !h.includes('album artist')
  );
  const artistIdx = artistNameIdx !== -1 ? artistNameIdx : headers.findIndex(h => 
    h.includes('artist') || h.includes('singer')
  );
  const albumNameIdx = headers.findIndex(h => 
    h.includes('album name') && !h.includes('album artist')
  );
  const albumIdx = albumNameIdx !== -1 ? albumNameIdx : headers.findIndex(h => 
    h.includes('album')
  );
  const durationIdx = headers.findIndex(h => 
    h.includes('duration') || h.includes('length')
  );
  const isrcIdx = headers.findIndex(h => h.includes('isrc'));
  const popularityIdx = headers.findIndex(h => h.includes('popularity'));
  const explicitIdx = headers.findIndex(h => h.includes('explicit'));

  // If no proper headers found, assume simple format: title, artist
  const hasHeaders = trackNameIdx !== -1 || artistIdx !== -1;
  const startIdx = hasHeaders ? 1 : 0;

  for (let i = startIdx; i < lines.length; i++) {
    try {
      const columns = parseCSVLine(lines[i]);
      
      if (columns.length < 2) {
        errors.push(`Line ${i + 1}: Not enough columns`);
        continue;
      }

      let title = '';
      let artist = '';
      let album = '';
      let duration = '';
      let trackUri = '';
      let isrc = '';
      let popularity = '';
      let explicit = false;

      if (hasHeaders) {
        // Use detected column indices
        trackUri = trackUriIdx !== -1 ? columns[trackUriIdx] : '';
        title = trackNameIdx !== -1 ? columns[trackNameIdx] : columns[1];
        artist = artistIdx !== -1 ? columns[artistIdx] : columns[3];
        album = albumIdx !== -1 ? columns[albumIdx] : '';
        duration = durationIdx !== -1 ? columns[durationIdx] : '';
        isrc = isrcIdx !== -1 ? columns[isrcIdx] : '';
        popularity = popularityIdx !== -1 ? columns[popularityIdx] : '';
        explicit = explicitIdx !== -1 ? columns[explicitIdx]?.toUpperCase() === 'TRUE' : false;
      } else {
        // Simple format: title, artist
        title = columns[0];
        artist = columns[1];
        duration = columns[2] || '';
      }

      // Clean up the data
      trackUri = trackUri.replace(/^["']|["']$/g, '').trim();
      title = title.replace(/^["']|["']$/g, '').trim();
      artist = artist.replace(/^["']|["']$/g, '').trim();
      album = album.replace(/^["']|["']$/g, '').trim();
      isrc = isrc.replace(/^["']|["']$/g, '').trim();
      
      // Clean up artist names - remove trailing commas and extra spaces
      artist = artist.replace(/,\s*$/, '').replace(/,\s+/g, ', ').trim();
      
      // Convert duration from ms to seconds if needed
      if (duration && !/:/.test(duration)) {
        const ms = parseInt(duration);
        if (!isNaN(ms)) {
          const seconds = Math.floor(ms / 1000);
          const mins = Math.floor(seconds / 60);
          const secs = seconds % 60;
          duration = `${mins}:${secs.toString().padStart(2, '0')}`;
        }
      }

      if (title && artist) {
        songs.push({
          title,
          artist,
          album,
          duration: duration || '0:00',
          status: 'ready',
          spotifyUri: trackUri || undefined,
          isrc: isrc || undefined,
          popularity: popularity ? parseInt(popularity) : undefined,
          explicit: explicit || undefined,
        });
      } else {
        errors.push(`Line ${i + 1}: Missing title or artist`);
      }
    } catch (error) {
      errors.push(`Line ${i + 1}: Parse error`);
    }
  }
  
  return { songs, errors, totalLines: lines.length };
}

/**
 * Parse TXT file content
 * Handles multiple separators: -, by, tab
 */
function parseTXT(content: string): FileParseResult {
  const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');
  const songs: ParsedSong[] = [];
  const errors: string[] = [];

  if (lines.length === 0) {
    return { songs: [], errors: ['File is empty'], totalLines: 0 };
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    
    // Skip empty lines
    if (!line) continue;
    
    let columns;
    
    try {
      if (line.includes(' - ')) {
        // Format: Artist - Title
        columns = line.split(' - ').map(part => part.trim());
        if (columns.length >= 2 && columns[0] && columns[1]) {
          songs.push({
            title: columns[1],
            artist: columns[0],
            status: 'ready'
          });
        } else {
          errors.push(`Line ${i + 1}: Invalid format (expected: Artist - Title)`);
        }
      } else if (line.includes(' by ')) {
        // Format: Title by Artist
        columns = line.split(' by ').map(part => part.trim());
        if (columns.length >= 2 && columns[0] && columns[1]) {
          songs.push({
            title: columns[0],
            artist: columns[1],
            status: 'ready'
          });
        } else {
          errors.push(`Line ${i + 1}: Invalid format (expected: Title by Artist)`);
        }
      } else if (line.includes('\t')) {
        // Tab-separated
        columns = line.split('\t').map(part => part.trim());
        if (columns.length >= 2 && columns[0] && columns[1]) {
          songs.push({
            title: columns[0],
            artist: columns[1],
            status: 'ready'
          });
        } else {
          errors.push(`Line ${i + 1}: Invalid format (expected: Title[TAB]Artist)`);
        }
      } else if (line.includes(',')) {
        // Comma-separated (simple CSV)
        columns = line.split(',').map(part => part.trim());
        if (columns.length >= 2 && columns[0] && columns[1]) {
          songs.push({
            title: columns[0],
            artist: columns[1],
            status: 'ready'
          });
        } else {
          errors.push(`Line ${i + 1}: Invalid format (expected: Title,Artist)`);
        }
      } else {
        // Just use as title with unknown artist
        songs.push({
          title: line,
          artist: 'Unknown Artist',
          status: 'ready'
        });
      }
    } catch (error) {
      errors.push(`Line ${i + 1}: Parse error - ${error}`);
    }
  }
  
  return { songs, errors, totalLines: lines.length };
}

/**
 * Parse file based on extension
 */
export function parseFile(content: string, fileName: string): FileParseResult {
  const extension = fileName.toLowerCase().split('.').pop();
  
  if (extension === 'csv') {
    return parseCSV(content);
  } else if (extension === 'txt') {
    return parseTXT(content);
  } else {
    return {
      songs: [],
      errors: ['Unsupported file format. Please use CSV or TXT files.'],
      totalLines: 0
    };
  }
}

import { initializeApp, getApps } from "firebase/app";
import { getAuth, initializeAuth } from "firebase/auth";
import { getFirestore, initializeFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Platform } from "react-native";
import { getExpoExtra } from "./expoExtra";

const { getReactNativePersistence } = require("firebase/auth") as {
  getReactNativePersistence: (storage: typeof AsyncStorage) => unknown;
};

const expoExtra = getExpoExtra();

const firebaseConfig = {
  apiKey:            (expoExtra.firebaseApiKey            as string | undefined) || process.env.EXPO_PUBLIC_FIREBASE_API_KEY,
  authDomain:        (expoExtra.firebaseAuthDomain        as string | undefined) || process.env.EXPO_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId:         (expoExtra.firebaseProjectId         as string | undefined) || process.env.EXPO_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket:     (expoExtra.firebaseStorageBucket     as string | undefined) || process.env.EXPO_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: (expoExtra.firebaseMessagingSenderId as string | undefined) || process.env.EXPO_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId:             (expoExtra.firebaseAppId             as string | undefined) || process.env.EXPO_PUBLIC_FIREBASE_APP_ID,
  measurementId:     (expoExtra.firebaseMeasurementId     as string | undefined) || process.env.EXPO_PUBLIC_FIREBASE_MEASUREMENT_ID,
};

// Reuse existing app instance if already initialized (handles fast-refresh / module reloads)
const app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApps()[0];

// initializeAuth throws if called a second time on the same app instance.
// getAuth() returns the existing instance safely.
export const auth = (() => {
  if (Platform.OS === "web") return getAuth(app);
  try {
    return initializeAuth(app, {
      persistence: getReactNativePersistence(AsyncStorage) as never,
    });
  } catch {
    // Already initialized — return the existing instance
    return getAuth(app);
  }
})();

export const db = (() => {
  try {
    return initializeFirestore(app, {
      experimentalAutoDetectLongPolling: true,
      ignoreUndefinedProperties: true,
    });
  } catch {
    return getFirestore(app);
  }
})();

export const storage = getStorage(app);

export { firebaseConfig };
export default app;

import { Platform } from "react-native";
import Constants from "expo-constants";
import { getExpoExtra } from "@/lib/expoExtra";

type GoogleSigninModule = typeof import("@react-native-google-signin/google-signin");

export async function getGoogleMobileIdToken(actionLabel: string = "Google Sign-In"): Promise<string> {
  if (Platform.OS === "web") {
    throw new Error(`${actionLabel} does not need a mobile token on web.`);
  }

  if (Constants.appOwnership === "expo") {
    throw new Error(
      `${actionLabel} requires a custom development build or production app build. Expo Go does not include the native Google Sign-In module.`
    );
  }

  const expoExtra = getExpoExtra();
  const webClientId =
    (expoExtra.googleWebClientId as string | undefined)?.trim() ||
    process.env.EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID?.trim();
  const iosClientId =
    (expoExtra.googleIosClientId as string | undefined)?.trim() ||
    process.env.EXPO_PUBLIC_GOOGLE_IOS_CLIENT_ID?.trim();

  if (!webClientId) {
    throw new Error(
      `${actionLabel} is not configured. Set EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID to your Firebase Google Web Client ID.`
    );
  }

  let nativeStatusCodes: GoogleSigninModule["statusCodes"] | undefined;

  try {
    let googleSigninModule: GoogleSigninModule;

    try {
      googleSigninModule = require("@react-native-google-signin/google-signin") as GoogleSigninModule;
    } catch {
      throw new Error(
        `${actionLabel} requires a custom development build or production app build. Expo Go does not include the native Google Sign-In module.`
      );
    }

    const { GoogleSignin, statusCodes } = googleSigninModule;
    nativeStatusCodes = statusCodes;

    GoogleSignin.configure({
      webClientId,
      ...(Platform.OS === "ios" && iosClientId ? { iosClientId } : {}),
    });

    if (Platform.OS === "android") {
      await GoogleSignin.hasPlayServices({
        showPlayServicesUpdateDialog: true,
      });
    }

    const response = await GoogleSignin.signIn();
    if (response.type === "cancelled") {
      throw new Error(`${actionLabel} was cancelled.`);
    }

    const signInIdToken = response.data.idToken?.trim();
    const tokenResponse = signInIdToken ? null : await GoogleSignin.getTokens();
    const idToken = signInIdToken || tokenResponse?.idToken?.trim();

    if (!idToken) {
      throw new Error(`Could not complete ${actionLabel}. No Google ID token received.`);
    }

    return idToken;
  } catch (error: any) {
    const code = String(error?.code || "");
    const message = String(error?.message || "");

    if (message.includes("RNGoogleSignin") || message.includes("TurboModuleRegistry")) {
      throw new Error(
        `${actionLabel} requires a custom development build or production app build. Expo Go does not include the native Google Sign-In module.`
      );
    }

    if (code === nativeStatusCodes?.SIGN_IN_CANCELLED) {
      throw new Error(`${actionLabel} was cancelled.`);
    }

    if (code === nativeStatusCodes?.IN_PROGRESS) {
      throw new Error(`${actionLabel} is already in progress.`);
    }

    if (code === nativeStatusCodes?.PLAY_SERVICES_NOT_AVAILABLE) {
      throw new Error("Google Play Services is unavailable or needs an update.");
    }

    throw error;
  }
}

