import { doc, getDoc, serverTimestamp, setDoc } from "firebase/firestore";
import { db } from "@/lib/firebase";
import { toTrimmedString } from "@/utils/stringUtils";

export type HomeHeroConfig = {
  enabled: boolean;
  title: string;
  videoUrl: string;
  posterUrl: string;
  adUnitId?: string;
  adSlotEnabled?: boolean;
  items: HomeHeroVideoItem[];
};

export type HomeHeroLinkedSong = {
  id: string;
  title: string;
  artist: string;
  album: string;
  duration: number;
  coverUrl: string;
  audioUrl: string;
  genre: string;
};

export type HomeHeroVideoItem = {
  id: string;
  kind?: "video" | "ad";
  enabled: boolean;
  title: string;
  videoUrl: string;
  posterUrl: string;
  adUnitId?: string;
  linkUrl: string;
  songId: string;
  song: HomeHeroLinkedSong | null;
  linkType?: 'song' | 'album' | 'playlist';
  album?: any | null;
  playlist?: any | null;
};

export const DEFAULT_HOME_HERO_CONFIG: HomeHeroConfig = {
  enabled: true,
  title: "COCKTAIL 2",
  videoUrl:
    "https://res.cloudinary.com/djqq8kba8/video/upload/f_mp4,vc_h264,c_crop,g_center,w_1440,h_810/c_fill,w_1080,h_608,q_auto:good/v1780900137/Cocktail_2_Official_Trailer___Shahid_Kapoor_Kriti_Sanon_Rashmika_Mandanna___In_Cinemas_19th_June_1440p_dwlaum.mp4",
  posterUrl:
    "https://res.cloudinary.com/djqq8kba8/video/upload/so_2,c_crop,g_center,w_1440,h_810/c_fill,w_1080,h_608,q_auto,f_jpg/v1780900137/Cocktail_2_Official_Trailer___Shahid_Kapoor_Kriti_Sanon_Rashmika_Mandanna___In_Cinemas_19th_June_1440p_dwlaum.jpg",
  adUnitId: "",
  adSlotEnabled: false,
  items: [
    {
      id: "default-home-video",
      kind: "video",
      enabled: true,
      title: "COCKTAIL 2",
      videoUrl:
        "https://res.cloudinary.com/djqq8kba8/video/upload/f_mp4,vc_h264,c_crop,g_center,w_1440,h_810/c_fill,w_1080,h_608,q_auto:good/v1780900137/Cocktail_2_Official_Trailer___Shahid_Kapoor_Kriti_Sanon_Rashmika_Mandanna___In_Cinemas_19th_June_1440p_dwlaum.mp4",
      posterUrl:
        "https://res.cloudinary.com/djqq8kba8/video/upload/so_2,c_crop,g_center,w_1440,h_810/c_fill,w_1080,h_608,q_auto,f_jpg/v1780900137/Cocktail_2_Official_Trailer___Shahid_Kapoor_Kriti_Sanon_Rashmika_Mandanna___In_Cinemas_19th_June_1440p_dwlaum.jpg",
      linkUrl: "",
      songId: "",
      song: null,
      linkType: 'song',
      album: null,
      playlist: null,
    },
  ],
};

const DISABLED_HOME_HERO_CONFIG: HomeHeroConfig = {
  ...DEFAULT_HOME_HERO_CONFIG,
  enabled: false,
  adUnitId: "",
  adSlotEnabled: false,
  items: [],
};

const HOME_HERO_CONFIG_REF = doc(db, "appConfig", "homeHero");



function toFiniteNumber(value: unknown): number {
  const next = typeof value === "number" ? value : Number(value);
  return Number.isFinite(next) && next > 0 ? next : 0;
}

function normalizeLinkedSong(value: unknown): HomeHeroLinkedSong | null {
  const record = value && typeof value === "object" ? (value as Record<string, unknown>) : {};
  const id = toTrimmedString(record.id);
  const title = toTrimmedString(record.title);
  const audioUrl = toTrimmedString(record.audioUrl);

  if (!id || !title || !audioUrl) return null;

  return {
    id,
    title,
    artist: toTrimmedString(record.artist) || "Unknown Artist",
    album: toTrimmedString(record.album),
    duration: toFiniteNumber(record.duration),
    coverUrl: toTrimmedString(record.coverUrl) || toTrimmedString(record.imageUrl),
    audioUrl,
    genre: toTrimmedString(record.genre),
  };
}

function normalizeVideoItem(value: unknown, index: number): HomeHeroVideoItem | null {
  const record = value && typeof value === "object" ? (value as Record<string, unknown>) : {};
  const videoUrl = toTrimmedString(record.videoUrl);
  const adUnitId = toTrimmedString(record.adUnitId);
  const kind = record.kind === "ad" || (!videoUrl && adUnitId) ? "ad" : "video";
  if (kind === "ad" && !adUnitId) return null;
  if (kind === "video" && !videoUrl) return null;

  const linkedSong = normalizeLinkedSong(record.song);
  const songId = toTrimmedString(record.songId) || linkedSong?.id || "";

  return {
    id: toTrimmedString(record.id) || `home-video-${index + 1}`,
    kind,
    enabled: typeof record.enabled === "boolean" ? record.enabled : true,
    title: toTrimmedString(record.title) || (kind === "ad" ? "Sponsored" : DEFAULT_HOME_HERO_CONFIG.title),
    videoUrl: kind === "ad" ? "" : videoUrl,
    posterUrl: kind === "ad" ? "" : toTrimmedString(record.posterUrl),
    adUnitId: kind === "ad" ? adUnitId : "",
    linkUrl: toTrimmedString(record.linkUrl),
    songId: kind === "ad" ? "" : songId,
    song: kind === "ad" ? null : linkedSong,
    linkType: (record.linkType === 'song' || record.linkType === 'album' || record.linkType === 'playlist') ? record.linkType : 'song',
    album: kind === "ad" ? null : record.album || null,
    playlist: kind === "ad" ? null : record.playlist || null,
  };
}

function buildHomeHeroAdItem(adUnitId: string, enabled = true): HomeHeroVideoItem {
  return {
    id: "home-native-video-ad",
    kind: "ad",
    enabled,
    title: "Sponsored",
    videoUrl: "",
    posterUrl: "",
    adUnitId,
    linkUrl: "",
    songId: "",
    song: null,
    linkType: "song",
    album: null,
    playlist: null,
  };
}

function normalizeHomeHeroConfig(data: unknown): HomeHeroConfig {
  const record = data && typeof data === "object" ? (data as Record<string, unknown>) : {};
  const title = toTrimmedString(record.title) || DEFAULT_HOME_HERO_CONFIG.title;
  const videoUrl = toTrimmedString(record.videoUrl) || DEFAULT_HOME_HERO_CONFIG.videoUrl;
  const posterUrl = toTrimmedString(record.posterUrl) || DEFAULT_HOME_HERO_CONFIG.posterUrl;
  const rawItems = Array.isArray(record.items) ? record.items : [];
  const legacyItemAdUnitId = rawItems
    .map((item) => (item && typeof item === "object" ? toTrimmedString((item as Record<string, unknown>).adUnitId) : ""))
    .find(Boolean) || "";
  const adUnitId = toTrimmedString(record.adUnitId) || legacyItemAdUnitId;
  const adSlotEnabled =
    typeof record.adSlotEnabled === "boolean" ? record.adSlotEnabled : Boolean(adUnitId);
  const configuredItems = Array.isArray(record.items)
    ? record.items.flatMap((item, index) => {
        const normalized = normalizeVideoItem(item, index);
        return normalized ? [normalized] : [];
      })
    : [];
  const fallbackItems = [
    {
      ...DEFAULT_HOME_HERO_CONFIG.items[0],
      id: "home-video-1",
      kind: "video" as const,
      title,
      videoUrl,
      posterUrl,
      adUnitId: "",
    },
  ];
  const baseItems = configuredItems.length > 0 ? configuredItems : fallbackItems;
  const adFilteredBaseItems = adSlotEnabled ? baseItems : baseItems.filter((item) => item.kind !== "ad");
  const sourceItems = adFilteredBaseItems.length > 0 ? adFilteredBaseItems : fallbackItems;
  const hasAdItem = sourceItems.some((item) => item.kind === "ad");
  const items =
    adSlotEnabled && adUnitId && !hasAdItem
      ? [...sourceItems, buildHomeHeroAdItem(adUnitId)]
      : sourceItems;
  const firstVisibleVideoItem =
    items.find((item) => item.enabled && item.kind !== "ad") ||
    items.find((item) => item.kind !== "ad") ||
    fallbackItems[0];

  return {
    enabled: typeof record.enabled === "boolean" ? record.enabled : DEFAULT_HOME_HERO_CONFIG.enabled,
    title: firstVisibleVideoItem.title || title,
    videoUrl: firstVisibleVideoItem.videoUrl || videoUrl,
    posterUrl: firstVisibleVideoItem.posterUrl || posterUrl,
    adUnitId,
    adSlotEnabled,
    items,
  };
}

export async function getHomeHeroConfig(): Promise<HomeHeroConfig> {
  try {
    const snapshot = await getDoc(HOME_HERO_CONFIG_REF);
    return snapshot.exists() ? normalizeHomeHeroConfig(snapshot.data()) : DEFAULT_HOME_HERO_CONFIG;
  } catch {
    return DEFAULT_HOME_HERO_CONFIG;
  }
}



export async function saveHomeHeroConfig(config: HomeHeroConfig, updatedBy?: string): Promise<void> {
  const normalized = normalizeHomeHeroConfig(config);
  await setDoc(
    HOME_HERO_CONFIG_REF,
    {
      ...normalized,
      schemaVersion: 3,
      updatedAt: serverTimestamp(),
      updatedBy: updatedBy || null,
    },
    { merge: true }
  );
}

/**
 * Module-level singleton that remembers the last artist mix params.
 * Supports React subscriptions so the mini player re-renders when a mix is set.
 */
import { useSyncExternalStore } from "react";

export interface LastMixParams {
  ids: string;
  names: string;
  images: string;
  songIds: string;
  [key: string]: string;
}

let _lastMix: LastMixParams | null = null;
const _listeners = new Set<() => void>();

function _notify() {
  _listeners.forEach((fn) => fn());
}

export function setLastMix(params: LastMixParams): void {
  _lastMix = params;
  _notify();
}

function getLastMix(): LastMixParams | null {
  return _lastMix;
}

export function clearLastMix(): void {
  _lastMix = null;
  _notify();
}

function subscribe(cb: () => void) {
  _listeners.add(cb);
  return () => _listeners.delete(cb);
}

function getSnapshot() {
  return _lastMix;
}

/** React hook — re-renders the component whenever the mix changes */
export function useLastMix(): LastMixParams | null {
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

import { mapFilter, sortedCopy } from "@/lib/arrayUtils";
import { toDurationSeconds } from "@/utils/timeFormatters";
export interface Song {
  id: string;
  title: string;
  artist: string;
  album: string;
  duration: number;
  coverUrl: string;
  genre: string;
  mood?: string | string[];
  audioUrl: string;
  year?: string;
  language?: string;
  popularity?: number;
  source?: "jiosaavn" | "gaana" | "local" | "youtube";
  playCount?: number;
  videoId?: string;
  youtubeVideoId?: string;
  youtubeVisualVideoId?: string;
  youtubeVideoType?: string;
  youtubeNativeAudio?: boolean;
  youtubeAudioExpiresAt?: number;
  playbackHeaders?: Record<string, string>;
  downloadUrl?: unknown;
}

export interface JioSaavnImage {
  quality: string;
  url: string;
}

export interface JioSaavnSong {
  id: string;
  name: string;
  type: string;
  year: string;
  duration: number;
  language: string;
  album: { id: string; name: string; url: string };
  artists: {
    primary: { id: string; name: string; image: JioSaavnImage[]; url: string }[];
    featured: { id: string; name: string; image: JioSaavnImage[]; url: string }[];
    all: { id: string; name: string; role: string; image: JioSaavnImage[]; url: string }[];
  };
  image: JioSaavnImage[];
  downloadUrl?: unknown;
  audioUrl?: unknown;
  url?: string;
}

export interface JioSaavnPlaylist {
  id: string;
  name: string;
  type: string;
  image: JioSaavnImage[];
  url: string;
  songCount: number;
  language: string;
  description?: string;
  songs?: JioSaavnSong[];
}

export interface Playlist {
  id: string;
  name: string;
  description: string;
  coverUrl: string;
  songs: string[];
  songData?: Song[];
  isUserCreated?: boolean;
  isJioSaavn?: boolean;
  jiosaavnId?: string;
  songCount?: number;
}

export interface Genre {
  id: string;
  name: string;
  color: string;
}

function normalizeJioSaavnImageUrl(rawUrl: string): string {
  let trimmed = String(rawUrl || "").trim();
  if (!trimmed) return "";

  // Upgrade insecure http:// to https:// to satisfy iOS ATS in release/IPA builds
  if (trimmed.startsWith("http://")) {
    trimmed = "https://" + trimmed.slice(7);
  }

  // Prefer higher-res covers (500x500) over lower resolutions (50x50, 150x150).
  return trimmed.replace(/[-_]?(50x50|150x150)(?=\b|\.jpg)/gi, (match) => {
    return match.startsWith("-") ? "-500x500" : match.startsWith("_") ? "_500x500" : "500x500";
  });
}

function qualityScore(quality: string | undefined, url: string | undefined): number {
  const qualityKey = String(quality || "").trim().toLowerCase();
  const direct: Record<string, number> = {
    "1200x1200": 5,
    "1000x1000": 4,
    "500x500": 3,
    "150x150": 2,
    "50x50": 1,
  };
  if (qualityKey in direct) return direct[qualityKey];

  const match = String(url || "").match(/(\d{2,4})x(\d{2,4})/i);
  if (!match) return 0;
  const width = Number(match[1]) || 0;
  const height = Number(match[2]) || 0;
  return Math.max(width, height);
}

export function getBestImageUrl(images: JioSaavnImage[]): string {
  if (!images || images.length === 0) return "";
  const sorted = sortedCopy(images, (a, b) => {
    return qualityScore(b.quality, b.url) - qualityScore(a.quality, a.url);
  });
  return normalizeJioSaavnImageUrl(sorted[0]?.url || "");
}

export type AudioCandidate = {
  quality: string;
  url: string;
};

export function normalizeAudioCandidates(downloadUrls: unknown): AudioCandidate[] {
  if (!downloadUrls) return [];

  if (typeof downloadUrls === "string") {
    const url = downloadUrls.trim();
    return url ? [{ quality: "320kbps", url }] : [];
  }

  if (Array.isArray(downloadUrls)) {
    return mapFilter(downloadUrls, (item) => {
        if (typeof item === "string") {
          const url = item.trim();
          return url ? { quality: "", url } : null;
        }

        if (!item || typeof item !== "object") return null;
        const obj = item as { quality?: unknown; url?: unknown; link?: unknown };
        const urlValue = typeof obj.url === "string" ? obj.url : typeof obj.link === "string" ? obj.link : "";
        const qualityValue = typeof obj.quality === "string" ? obj.quality : "";
        const url = urlValue.trim();
        if (!url) return null;
        return { quality: qualityValue, url };
      }, (item): item is AudioCandidate => Boolean(item));
  }

  if (typeof downloadUrls === "object") {
    const obj = downloadUrls as { url?: unknown; link?: unknown };
    const urlValue = typeof obj.url === "string" ? obj.url : typeof obj.link === "string" ? obj.link : "";
    const url = urlValue.trim();
    if (url) return [{ quality: "", url }];
  }

  return [];
}

export function getBestAudioUrl(downloadUrls: unknown): string {
  if (typeof downloadUrls === "string") return downloadUrls.trim();
  const candidates = normalizeAudioCandidates(downloadUrls);
  if (candidates.length === 0) return "";

  const sorted = sortedCopy(candidates, (a, b) => {
    const qualityOrder: Record<string, number> = { "320kbps": 4, "160kbps": 3, "96kbps": 2, "48kbps": 1, "12kbps": 0 };
    return (qualityOrder[b.quality] || 0) - (qualityOrder[a.quality] || 0);
  });
  return sorted[0]?.url || "";
}

export type StreamingQuality = "auto" | "low" | "medium" | "high";

export interface ResolvedAudioStream {
  url: string;
  bitrate: number;
  qualityLabel: string;
  isFallback: boolean;
}

export function parseBitrateFromQuality(quality: string | undefined): number {
  if (!quality) return 0;
  const match = String(quality).match(/(\d+)\s*k/i);
  if (match) return parseInt(match[1], 10);
  const direct: Record<string, number> = {
    "320kbps": 320,
    "160kbps": 160,
    "96kbps": 96,
    "48kbps": 48,
    "12kbps": 12,
  };
  return direct[quality.toLowerCase()] || 0;
}

export const QUALITY_LADDER: Record<StreamingQuality, number[]> = {
  auto: [160, 96, 48, 320, 12],
  low: [96, 48, 12, 160, 320],
  medium: [160, 96, 48, 320, 12],
  high: [320, 160, 96, 48, 12],
} as const;

export const QUALITY_LABELS: Record<StreamingQuality, string[]> = {
  auto: ["160kbps", "96kbps", "48kbps", "320kbps", "12kbps"],
  low: ["96kbps", "48kbps", "12kbps", "160kbps", "320kbps"],
  medium: ["160kbps", "96kbps", "48kbps", "320kbps", "12kbps"],
  high: ["320kbps", "160kbps", "96kbps", "48kbps", "12kbps"],
};

export function resolveAudioStreamWithQuality(
  downloadUrls: unknown,
  quality: StreamingQuality = "medium"
): ResolvedAudioStream | null {
  const candidates = normalizeAudioCandidates(downloadUrls);
  if (candidates.length === 0) return null;

  const targetPreferences = QUALITY_LABELS[quality] || QUALITY_LABELS.medium;
  const candidatesByQuality = new Map(
    candidates.map((candidate) => [candidate.quality.toLowerCase(), candidate])
  );

  for (let i = 0; i < targetPreferences.length; i++) {
    const pref = targetPreferences[i].toLowerCase();
    const found = candidatesByQuality.get(pref);
    if (found && found.url) {
      const bitrate = parseBitrateFromQuality(found.quality) || (quality === "high" ? 320 : quality === "medium" ? 160 : 96);
      return {
        url: found.url,
        bitrate,
        qualityLabel: found.quality || `${bitrate}kbps`,
        isFallback: i > 0,
      };
    }
  }

  const bestUrl = getBestAudioUrl(downloadUrls);
  if (!bestUrl) return null;

  return {
    url: bestUrl,
    bitrate: 160,
    qualityLabel: "160kbps",
    isFallback: true,
  };
}

export function getBestAudioUrlWithQuality(
  downloadUrls: unknown,
  quality: StreamingQuality = "medium"
): string {
  const resolved = resolveAudioStreamWithQuality(downloadUrls, quality);
  return resolved?.url || "";
}

export function convertJioSaavnSong(song: JioSaavnSong): Song {
  const artistNames = song.artists?.primary?.map(a => a.name).join(", ") || "Unknown Artist";
  
  // Detect provider from song ID or URL
  // JioSaavn IDs are numeric, Gaana IDs are alphanumeric with hyphens
  const isGaanaSong = !/^\d+$/.test(song.id) || song.url?.includes('gaana.com');
  
  return {
    id: song.id,
    title: song.name || "Unknown",
    artist: artistNames,
    album: song.album?.name || "",
    duration: toDurationSeconds(song.duration),
    coverUrl: getBestImageUrl(song.image),
    genre: song.language || "",
    audioUrl: getBestAudioUrl(song.downloadUrl || song.audioUrl || song.url),
    downloadUrl: song.downloadUrl || song.audioUrl || song.url,
    year: song.year,
    language: song.language,
    source: isGaanaSong ? undefined : "jiosaavn",  // Don't set source for Gaana songs
  };
}

function convertJioSaavnPlaylist(playlist: JioSaavnPlaylist): Playlist {
  const convertedSongs = playlist.songs?.map(convertJioSaavnSong) || [];
  return {
    id: `jiosaavn_${playlist.id}`,
    name: playlist.name,
    description: playlist.description || `${playlist.songCount || 0} songs`,
    coverUrl: getBestImageUrl(playlist.image),
    songs: convertedSongs.map(s => s.id),
    songData: convertedSongs,
    isJioSaavn: true,
    jiosaavnId: playlist.id,
    songCount: playlist.songCount,
  };
}

const genres: Genre[] = [
  { id: "bollywood", name: "Bollywood", color: "#E13300" },
  { id: "punjabi", name: "Punjabi", color: "#BA5D07" },
  { id: "romantic", name: "Romantic", color: "#DC148C" },
  { id: "party", name: "Party", color: "#7358FF" },
  { id: "devotional", name: "Devotional", color: "#ffa726" },
  { id: "retro", name: "Retro Hits", color: "#ab47bc" },
  { id: "pop", name: "Pop", color: "#8C67AC" },
  { id: "hip-hop", name: "Hip-Hop", color: "#E8115B" },
  { id: "tamil", name: "Tamil", color: "#26a69a" },
  { id: "telugu", name: "Telugu", color: "#1ABC9C" },
  { id: "english", name: "English", color: "#42a5f5" },
  { id: "lofi", name: "Lo-Fi", color: "#477D95" },
];

export { formatDuration } from "@/utils/timeFormatters";

import { QueryClient, type QueryFunction } from "@tanstack/react-query";
import { getApiUrl } from "./api-config";
export { getApiUrl };

export class ApiError extends Error {
  status: number;

  constructor(status: number, message: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}




async function apiRequest(
  method: string,
  route: string,
  data?: unknown | undefined,
): Promise<Response> {
  const baseUrl = getApiUrl();
  const url = new URL(route, baseUrl);

  const res = await fetch(url.toString(), {
    method,
    headers: data ? { "Content-Type": "application/json" } : {},
    body: data ? JSON.stringify(data) : undefined,
    credentials: "include",
  });

  if (!res.ok) {
    throw new ApiError(res.status, res.statusText);
  }
  return res;
}

type UnauthorizedBehavior = "returnNull" | "throw";
const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
    async ({ queryKey }) => {
      const baseUrl = getApiUrl();
      const url = new URL(queryKey.join("/") as string, baseUrl);

      const res = await fetch(url.toString(), {
        credentials: "include",
      });

      if (unauthorizedBehavior === "returnNull" && res.status === 401) {
        return null;
      }

      if (!res.ok) {
        throw new ApiError(res.status, res.statusText);
      }
      return res.json();
    };

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      queryFn: getQueryFn({ on401: "throw" }),
      refetchInterval: false,
      refetchOnWindowFocus: false,
      staleTime: 5 * 60 * 1000, // 5 minutes
      gcTime: 10 * 60 * 1000, // 10 minutes
      retry: (failureCount, error) => {
        if (error instanceof ApiError && error.status >= 400 && error.status < 500) {
          return false;
        }
        return failureCount < 2;
      },
      retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),
      networkMode: "online",
    },
    mutations: {
      retry: 1,
      networkMode: "online",
    },
  },
});

/**
 * Client-Side Rate Limiter
 * Provides basic protection against brute force attacks
 * 
 * NOTE: This is CLIENT-SIDE protection only. True rate limiting
 * must be implemented on the backend/Firebase side.
 */

import AsyncStorage from '@react-native-async-storage/async-storage';

interface RateLimitConfig {
  maxAttempts: number;
  windowMs: number;
  blockDurationMs: number;
}

// Rate limit configurations for different actions
const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  'auth:login': {
    maxAttempts: 5, // 5 failed login attempts
    windowMs: 15 * 60 * 1000, // within 15 minutes
    blockDurationMs: 15 * 60 * 1000, // block for 15 minutes
  },
  'auth:register': {
    maxAttempts: 3, // 3 registration attempts
    windowMs: 60 * 60 * 1000, // within 1 hour
    blockDurationMs: 60 * 60 * 1000, // block for 1 hour
  },
  'auth:passwordReset': {
    maxAttempts: 3, // 3 password reset requests
    windowMs: 60 * 60 * 1000, // within 1 hour
    blockDurationMs: 60 * 60 * 1000, // block for 1 hour
  },
  'auth:deleteAccount': {
    maxAttempts: 2, // 2 deletion attempts
    windowMs: 60 * 60 * 1000, // within 1 hour
    blockDurationMs: 60 * 60 * 1000, // block for 1 hour
  },
  'upload:image': {
    maxAttempts: 10, // 10 image uploads
    windowMs: 60 * 60 * 1000, // within 1 hour
    blockDurationMs: 60 * 60 * 1000, // block for 1 hour
  },
};

interface RateLimitData {
  attempts: number[];
  blockedUntil: number;
}

/**
 * Check if an action is rate limited
 * @param action Action identifier (e.g., 'auth:login')
 * @param identifier Optional additional identifier (e.g., email address for per-user limits)
 * @returns Object with allowed status and optional retry time
 */
export async function checkRateLimit(
  action: string,
  identifier?: string
): Promise<{ allowed: boolean; retryAfter?: number; attemptsRemaining?: number }> {
  const config = RATE_LIMIT_CONFIGS[action];
  
  // If no config exists for this action, allow it
  if (!config) {
    return { allowed: true };
  }

  const key = `ratelimit:${action}${identifier ? ':' + identifier : ''}`;
  const dataStr = await AsyncStorage.getItem(key);
  const now = Date.now();

  let data: RateLimitData = dataStr
    ? JSON.parse(dataStr)
    : { attempts: [], blockedUntil: 0 };

  // Check if currently blocked
  if (data.blockedUntil && now < data.blockedUntil) {
    const retryAfter = Math.ceil((data.blockedUntil - now) / 1000);
    return { allowed: false, retryAfter };
  }

  // Clear block if it has expired
  if (data.blockedUntil && now >= data.blockedUntil) {
    data.blockedUntil = 0;
    data.attempts = [];
  }

  // Remove attempts outside the time window
  data.attempts = data.attempts.filter(
    (timestamp: number) => now - timestamp < config.windowMs
  );

  // Check if limit exceeded
  if (data.attempts.length >= config.maxAttempts) {
    data.blockedUntil = now + config.blockDurationMs;
    try {
      await AsyncStorage.setItem(key, JSON.stringify(data));
    } catch {
      // Storage full or unavailable — still enforce the block in-memory for this session
    }
    const retryAfter = Math.ceil(config.blockDurationMs / 1000);
    return { allowed: false, retryAfter };
  }

  // Calculate remaining attempts
  const attemptsRemaining = config.maxAttempts - data.attempts.length;

  // Record this attempt
  data.attempts.push(now);
  try {
    await AsyncStorage.setItem(key, JSON.stringify(data));
  } catch {
    // Storage full or unavailable — allow the action; rate limit state is best-effort
  }

  return { allowed: true, attemptsRemaining };
}

/**
 * Clear rate limit for an action (e.g., after successful login)
 * @param action Action identifier
 * @param identifier Optional identifier
 */
export async function clearRateLimit(
  action: string,
  identifier?: string
): Promise<void> {
  const key = `ratelimit:${action}${identifier ? ':' + identifier : ''}`;
  await AsyncStorage.removeItem(key);
}

/**
 * Format retry time in human-readable format
 * @param seconds Number of seconds
 * @returns Formatted string
 */
export function formatRetryAfter(seconds: number): string {
  if (seconds < 60) {
    return `${seconds} second${seconds !== 1 ? 's' : ''}`;
  }
  
  const minutes = Math.ceil(seconds / 60);
  if (minutes < 60) {
    return `${minutes} minute${minutes !== 1 ? 's' : ''}`;
  }
  
  const hours = Math.ceil(minutes / 60);
  return `${hours} hour${hours !== 1 ? 's' : ''}`;
}

/**
 * Get remaining attempts for an action
 * @param action Action identifier
 * @param identifier Optional identifier
 * @returns Number of attempts remaining, or null if no limit
 */
async function getRemainingAttempts(
  action: string,
  identifier?: string
): Promise<number | null> {
  const config = RATE_LIMIT_CONFIGS[action];
  if (!config) return null;

  const key = `ratelimit:${action}${identifier ? ':' + identifier : ''}`;
  const dataStr = await AsyncStorage.getItem(key);
  const now = Date.now();

  if (!dataStr) {
    return config.maxAttempts;
  }

  const data: RateLimitData = JSON.parse(dataStr);

  // If blocked, return 0
  if (data.blockedUntil && now < data.blockedUntil) {
    return 0;
  }

  // Filter valid attempts
  const validAttempts = data.attempts.filter(
    (timestamp: number) => now - timestamp < config.windowMs
  );

  return Math.max(0, config.maxAttempts - validAttempts.length);
}

