import { createAudioPlayer, setAudioModeAsync } from "expo-audio";
import type { AudioPlayer, AudioSample } from "expo-audio";
import type { Song } from "@/lib/musicData";
import { publishPlaybackAudioSample, resetPlaybackAudioLevels } from "./PlaybackAudioLevels";

// ─── singletons ───────────────────────────────────────────────────────────────

// The one and only active player. Any new loadAndPlay call replaces it.
let activePlayer: AudioPlayer | null = null;
let currentUrl: string | null = null;
let seekBlockUntil = 0;
let seekResetTimer: ReturnType<typeof setTimeout> | null = null;
type PlayerSubscription = {
  remove?: () => void;
};

type PlayerSubscriptions = {
  status?: PlayerSubscription;
  sample?: PlayerSubscription;
};

const playerSubscriptions = new WeakMap<AudioPlayer, PlayerSubscriptions>();

// Monotonically increasing request id.
// Every loadAndPlay increments this. Callbacks from older players are dropped.
let generation = 0;

// audioMode only needs to be set once per app session.
let audioModeSet = false;

// ─── callbacks ────────────────────────────────────────────────────────────────

type StatusCallback = (s: {
  isPlaying: boolean;
  position: number;
  duration: number;
  didJustFinish: boolean;
}) => void;

type ErrorCallback = (err: string) => void;

let statusCb: StatusCallback | null = null;
let errorCb: ErrorCallback | null = null;

export function onStatusUpdate(cb: StatusCallback) { statusCb = cb; }
function onError(cb: ErrorCallback) { errorCb = cb; }
function clearListeners(): void {
  statusCb = null;
  errorCb = null;
}

// ─── internal helpers ─────────────────────────────────────────────────────────

/**
 * Immediately silence + destroy a player instance.
 * Safe to call with null.
 */
function killPlayer(p: AudioPlayer | null): void {
  if (!p) return;
  try { (p as any).clearLockScreenControls?.(); } catch {}
  try { (p as any).setActiveForLockScreen?.(false); } catch {}
  const subscriptions = playerSubscriptions.get(p);
  try { subscriptions?.status?.remove?.(); } catch {}
  try { subscriptions?.sample?.remove?.(); } catch {}
  playerSubscriptions.delete(p);
  try { p.setAudioSamplingEnabled(false); } catch {}
  try { p.pause(); } catch {}   // stop audio output immediately
  try { p.release(); } catch {}  // release native resources
  resetPlaybackAudioLevels();
}

function clearSeekResetTimer(): void {
  if (seekResetTimer) {
    clearTimeout(seekResetTimer);
    seekResetTimer = null;
  }
  seekBlockUntil = 0;
}

async function ensureAudioMode(): Promise<void> {
  if (audioModeSet) return;
  try {
    await setAudioModeAsync({
      playsInSilentMode: true,
      shouldPlayInBackground: true,
      interruptionMode: "doNotMix",
    });
    audioModeSet = true;
  } catch {
    // Non-fatal
  }
}

function attachListener(p: AudioPlayer, gen: number): void {
  const status = p.addListener("playbackStatusUpdate", (status) => {
    if (gen !== generation || !statusCb) return;
    if (Date.now() < seekBlockUntil && !status.didJustFinish) return;
    statusCb({
      isPlaying: status.playing,
      position: status.currentTime ?? 0,
      duration: status.duration ?? 0,
      didJustFinish: status.didJustFinish ?? false,
    });
  });

  let sample: PlayerSubscription | undefined;
  if (p.isAudioSamplingSupported) {
    try {
      p.setAudioSamplingEnabled(true);
      sample = p.addListener("audioSampleUpdate", (audioSample: AudioSample) => {
        if (gen !== generation) return;
        publishPlaybackAudioSample(audioSample);
      });
    } catch {
      resetPlaybackAudioLevels();
    }
  }

  playerSubscriptions.set(p, { status: status ?? {}, sample });
}

// ─── public API ───────────────────────────────────────────────────────────────

export async function loadAndPlay(url: string, song?: Partial<Song> | null, shouldPlay: () => boolean = () => true): Promise<void> {
  if (!url) {
    errorCb?.("No audio URL provided");
    return;
  }

  // 1. Bump generation and capture the snapshot for this call.
  generation += 1;
  const myGen = generation;

  // 2. Kill the current player RIGHT NOW — before any await.
  //    This stops audio output immediately and prevents two songs playing.
  const prev = activePlayer;
  activePlayer = null;
  clearSeekResetTimer();
  killPlayer(prev);

  try {
    if (myGen !== generation) return;

    // 3. Set audio mode once (cached after first call).
    await ensureAudioMode();

    // 4. If another loadAndPlay fired while we awaited, it already owns playback.
    if (myGen === generation) {
      // 5. Create the new player (synchronous in expo-audio).
      currentUrl = url;
      seekBlockUntil = 0;
      const p = createAudioPlayer(url, { updateInterval: 500 });

      // 6. Guard again — another call may have arrived during createAudioPlayer.
      if (myGen !== generation) {
        killPlayer(p);
        return;
      }

      // 7. Register as the active player, wire events, start playback.
      activePlayer = p;
      attachListener(p, myGen);

      if (typeof (p as any).setActiveForLockScreen === "function") {
        try {
          (p as any).setActiveForLockScreen(
            true,
            {
              title: song?.title || "Unknown",
              artist: song?.artist || "Mavrixfy",
              albumTitle: song?.album || undefined,
              artworkUrl: song?.coverUrl || undefined,
            },
            {
              showSeekBackward: false,
              showSeekForward: true,
              isLiveStream: false,
            }
          );
        } catch {
          // non-fatal
        }
      }

      if (shouldPlay()) p.play();
    }
  } catch (err: any) {
    if (myGen === generation) {
      errorCb?.(err?.message || String(err) || "Playback failed");
      throw err;
    }
  }
}

export function play(): void {
  try { activePlayer?.play(); } catch {}
}

export function pause(): void {
  try { activePlayer?.pause(); } catch {}
}

function stop(): void {
  generation += 1;
  const p = activePlayer;
  activePlayer = null;
  currentUrl = null;
  clearSeekResetTimer();
  killPlayer(p);
  resetPlaybackAudioLevels();
}

export function destroy(): void {
  clearListeners();
  stop();
}

export async function seekTo(seconds: number): Promise<void> {
  if (!activePlayer) return;
  try {
    if (seekResetTimer) {
      clearTimeout(seekResetTimer);
    }
    seekBlockUntil = Date.now() + 700;
    await activePlayer.seekTo(seconds);
    seekResetTimer = setTimeout(() => {
      seekBlockUntil = 0;
      seekResetTimer = null;
    }, 700);
  } catch {}
}

export function isLoaded(): boolean { return activePlayer !== null; }
function getCurrentUrl(): string | null { return currentUrl; }

import { useSyncExternalStore } from "react";

export type PlaybackAudioLevels = readonly [number, number, number];

export type PlaybackAudioLevelFrame = {
  levels: PlaybackAudioLevels;
  hasSignal: boolean;
  updatedAt: number;
};

type AudioSampleLike = {
  channels: { frames: number[] }[];
};

type Listener = () => void;

const IDLE_LEVELS: PlaybackAudioLevels = [0.24, 0.32, 0.2];
const SAMPLE_PUBLISH_INTERVAL_MS = 36;
const MAX_SAMPLES_PER_SEGMENT = 96;

const listeners = new Set<Listener>();
let frame: PlaybackAudioLevelFrame = {
  levels: IDLE_LEVELS,
  hasSignal: false,
  updatedAt: 0,
};
let lastSamplePublishedAt = 0;

function emitAudioLevels(): void {
  listeners.forEach((listener) => listener());
}

function clampLevel(value: number): number {
  return Math.max(0.16, Math.min(1, value));
}

function getSegmentLevel(sample: AudioSampleLike, segmentIndex: number): number {
  let squaredTotal = 0;
  let peak = 0;
  let sampleCount = 0;

  sample.channels.forEach((channel) => {
    const segmentSize = Math.ceil(channel.frames.length / 3);
    const start = Math.max(0, segmentIndex * segmentSize);
    const end = Math.min(channel.frames.length, start + segmentSize);
    const stride = Math.max(1, Math.floor((end - start) / MAX_SAMPLES_PER_SEGMENT));

    for (let index = start; index < end; index += stride) {
      const value = channel.frames[index];
      if (!Number.isFinite(value)) continue;

      const magnitude = Math.abs(value);
      squaredTotal += magnitude * magnitude;
      peak = Math.max(peak, magnitude);
      sampleCount += 1;
    }
  });

  if (sampleCount === 0) return IDLE_LEVELS[segmentIndex];

  const rms = Math.sqrt(squaredTotal / sampleCount);
  const amplified = Math.max(rms * 4.2, peak * 0.92);
  return clampLevel(0.16 + Math.min(1, amplified) * 0.84);
}

function smoothLevel(previous: number, next: number): number {
  const nextWeight = next >= previous ? 0.72 : 0.42;
  return clampLevel(previous * (1 - nextWeight) + next * nextWeight);
}

function toAudioLevels(sample: AudioSampleLike): PlaybackAudioLevels {
  const rawLevels: PlaybackAudioLevels = [
    getSegmentLevel(sample, 0),
    getSegmentLevel(sample, 1),
    getSegmentLevel(sample, 2),
  ];

  if (!frame.hasSignal) return rawLevels;

  return [
    smoothLevel(frame.levels[0], rawLevels[0]),
    smoothLevel(frame.levels[1], rawLevels[1]),
    smoothLevel(frame.levels[2], rawLevels[2]),
  ];
}

export function publishPlaybackAudioSample(sample: AudioSampleLike): void {
  const now = Date.now();
  if (now - lastSamplePublishedAt < SAMPLE_PUBLISH_INTERVAL_MS) return;

  lastSamplePublishedAt = now;
  frame = {
    levels: toAudioLevels(sample),
    hasSignal: true,
    updatedAt: now,
  };
  emitAudioLevels();
}

export function resetPlaybackAudioLevels(): void {
  if (!frame.hasSignal && frame.updatedAt === 0) return;

  lastSamplePublishedAt = 0;
  frame = {
    levels: IDLE_LEVELS,
    hasSignal: false,
    updatedAt: 0,
  };
  emitAudioLevels();
}

function subscribeAudioLevels(listener: Listener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function getAudioLevelsSnapshot(): PlaybackAudioLevelFrame {
  return frame;
}

function usePlaybackAudioLevels(): PlaybackAudioLevelFrame {
  return useSyncExternalStore(subscribeAudioLevels, getAudioLevelsSnapshot, getAudioLevelsSnapshot);
}

