import { PermissionsAndroid, Platform } from "react-native";
import TrackPlayer, {
  Capability,
  AppKilledPlaybackBehavior,
  AndroidAudioContentType,
  IOSCategory,
  IOSCategoryMode,
  IOSCategoryOptions,
} from "react-native-track-player";
import { logger } from "@/lib/logger";

export async function trackPlayerService(): Promise<void> {
  await Promise.resolve();
  try {
    const Event = require("react-native-track-player").Event;
    if (!TrackPlayer?.addEventListener || !Event) return;

    TrackPlayer.addEventListener(Event.RemotePlay, () => {
      TrackPlayer.play().catch(() => {});
    });
    TrackPlayer.addEventListener(Event.RemotePause, () => {
      TrackPlayer.pause().catch(() => {});
    });
    TrackPlayer.addEventListener(Event.RemoteStop, () => {
      TrackPlayer.stop().catch(() => {});
    });
    TrackPlayer.addEventListener(Event.RemoteSeek, (event: { position: number }) => {
      if (typeof event?.position === "number") {
        TrackPlayer.seekTo(event.position).catch(() => {});
      }
    });

    TrackPlayer.addEventListener(Event.RemoteNext, () => {
      TrackPlayer.skipToNext().catch(() => {});
    });
    TrackPlayer.addEventListener(Event.RemotePrevious, () => {
      TrackPlayer.skipToPrevious().catch(() => {});
    });
    TrackPlayer.addEventListener(
      Event.RemoteDuck,
      async (event: { paused?: boolean; permanent?: boolean; ducking?: boolean }) => {
        if (event?.permanent) {
          TrackPlayer.stop().catch(() => {});
        } else if (event?.paused) {
          TrackPlayer.pause().catch(() => {});
        }
      }
    );

    TrackPlayer.addEventListener(Event.PlaybackError, (error: any) => {
      logger.error("[TrackPlayer] Playback error:", error);
      if (error?.code) logger.error("[TrackPlayer] Error code:", error.code);
      if (error?.message) logger.error("[TrackPlayer] Error message:", error.message);
    });
  } catch (error) {
    logger.error("[TrackPlayer] Service registration failed:", error);
  }
}

let playerReady = false;
let setupPromise: Promise<void> | null = null;

function isAlreadyInitialized(error: unknown): boolean {
  return (error as { code?: string } | undefined)?.code === "player_already_initialized";
}

export async function setupPlayer(): Promise<void> {
  if (playerReady) return;
  if (setupPromise) return setupPromise;

  setupPromise = setupPlayerInternal();
  try {
    await setupPromise;
    playerReady = true;
  } catch (error) {
    logger.error("[TrackPlayerAdapter] setupPlayer failed:", error);
    setupPromise = null;
    throw error;
  }
}

async function setupPlayerInternal(): Promise<void> {
  if (!TrackPlayer?.setupPlayer) {
    logger.error("[TrackPlayerAdapter] TrackPlayer.setupPlayer method is missing!");
    return;
  }

  if (Platform.OS === "android" && Number(Platform.Version) >= 33) {
    try {
      await PermissionsAndroid.request(PermissionsAndroid.PERMISSIONS.POST_NOTIFICATIONS);
    } catch {
      // non-fatal
    }
  }

  try {
    await TrackPlayer.setupPlayer({
      autoHandleInterruptions: true,
      // SwiftAudioEx owns iOS elapsed time, duration, and playback rate for
      // Now Playing. Do not manually overwrite these values from JavaScript.
      autoUpdateMetadata: true,
      androidAudioContentType: AndroidAudioContentType?.Music ?? 2,
      minBuffer: 15,
      maxBuffer: 45,
      playBuffer: 2,
      backBuffer: 10,
      ...(Platform.OS === "ios"
        ? {
          iosCategory: IOSCategory?.Playback ?? "playback",
          iosCategoryMode: IOSCategoryMode?.Default ?? "default",
          iosCategoryOptions: [
            IOSCategoryOptions?.AllowAirPlay ?? 1,
            IOSCategoryOptions?.AllowBluetooth ?? 2,
            IOSCategoryOptions?.AllowBluetoothA2DP ?? 8,
          ],
        }
        : {}),
    });
  } catch (error) {
    if (!isAlreadyInitialized(error)) throw error;
  }

  if (TrackPlayer.updateOptions) {
    await TrackPlayer.updateOptions({
      android: {
        appKilledPlaybackBehavior:
          AppKilledPlaybackBehavior?.StopPlaybackAndRemoveNotification ??
          "stop-playback-and-remove-notification",
        alwaysPauseOnInterruption: true,
        stopForegroundGracePeriod: 5,
      },
      capabilities: [
        Capability.Play,
        Capability.Pause,
        Capability.SkipToNext,
        Capability.SkipToPrevious,
        Capability.SeekTo,
        Capability.Stop,
      ],
      notificationCapabilities: [
        Capability.Play,
        Capability.Pause,
        Capability.SkipToNext,
        Capability.SkipToPrevious,
        Capability.SeekTo,
      ],
      compactCapabilities: [
        Capability.Play,
        Capability.Pause,
        Capability.SkipToNext,
      ],
      progressUpdateEventInterval: 1,
    });
  }
}

import { useCallback, useEffect, type MutableRefObject } from "react";
import type { Song } from "@/lib/musicData";
import { logger } from "@/lib/logger";
import { updatePlaybackEngineSnapshot } from "@/services/audio/PlaybackEngine";
import { playerPersistenceService } from "@/services/player/playerPersistenceService";
import * as ExpoAvPlayer from "@/services/audio/ExpoAvAdapter";
import { songToTrack, withResolvedPlaybackUrl, resolveAudioUrl } from "@/services/audio/PlayerPlaybackResolver";
import { isSameQueueContent } from "@/services/audio/audioNativeQueueLane";
import { toDurationSeconds } from "@/utils/timeFormatters";
import type { PendingPlayRequest } from "@/services/audio/usePlayerCoreState";

interface UseAudioPlaybackCommandsOptions {
  currentSongRef: MutableRefObject<Song | null>;
  setCurrentSong: (song: Song | null) => void;
  queueRef: MutableRefObject<Song[]>;
  setQueue: (songs: Song[]) => void;
  originalQueueRef: MutableRefObject<Song[]>;
  setSourceQueue: (songs: Song[]) => void;
  queueIndexRef: MutableRefObject<number>;
  setQueueIndex: (index: number) => void;
  userQueuedSongIdsRef: MutableRefObject<string[]>;
  setUserQueuedSongIds: React.Dispatch<React.SetStateAction<string[]>>;
  isShuffledRef: MutableRefObject<boolean>;
  repeatModeRef: MutableRefObject<"off" | "all" | "one">;
  isPlayingRef: MutableRefObject<boolean>;
  setIsPlaying: (playing: boolean) => void;
  playbackLoadingRef: MutableRefObject<boolean>;
  setPlaybackLoading: (loading: boolean) => void;
  desiredPlayStateRef: MutableRefObject<boolean | null>;
  playRequestIdRef: MutableRefObject<number>;
  pendingPlayRequestRef: MutableRefObject<PendingPlayRequest | null>;
  positionSecondsRef: MutableRefObject<number>;
  durationSecondsRef?: MutableRefObject<number>;
  isNativeQueueSyncedRef?: MutableRefObject<boolean>;
  setSeekOverride: (override: any) => void;
  setNativePosition: (pos: number) => void;
  streamUrlCache: MutableRefObject<Map<string, string>>;
  resolvePlaybackUrlCached: (song: Song) => Promise<string | null>;
  prefetchAdjacentTrackStreams: (queue: Song[], index: number) => void;
  enqueueNativeQueueMutation: <T>(op: () => Promise<T>) => Promise<T>;
  TrackPlayer: any;
  isPlayerReady: boolean;
  ensurePlayerReady: () => Promise<boolean>;
  State: any;
  canUseLightweightAudioFallback: boolean;
  showPlaybackNotice: (msg: string) => void;
  playSongRef: MutableRefObject<(song: Song, queue?: Song[]) => Promise<void> | void>;
  togglePlayRef: MutableRefObject<() => Promise<void> | void>;
  togglePlayInFlightRef: MutableRefObject<boolean>;
  nextSongRef: MutableRefObject<() => void>;
  prevSongRef: MutableRefObject<() => void>;
  seekToRef: MutableRefObject<(progress: number) => Promise<void> | void>;
  triggerAutoplayAppend?: (seedSong: Song, currentQueue: Song[]) => Promise<Song[]>;
  autoplaySongIdsRef?: MutableRefObject<string[]>;
  lastAutoplaySeedIdRef?: MutableRefObject<string | null>;
  sleepTimerRef?: MutableRefObject<any>;
}

export function useAudioPlaybackCommands({
  currentSongRef,
  setCurrentSong,
  queueRef,
  setQueue,
  originalQueueRef,
  setSourceQueue,
  queueIndexRef,
  setQueueIndex,
  userQueuedSongIdsRef,
  setUserQueuedSongIds,
  isShuffledRef,
  repeatModeRef,
  isPlayingRef,
  setIsPlaying,
  playbackLoadingRef,
  setPlaybackLoading,
  desiredPlayStateRef,
  playRequestIdRef,
  pendingPlayRequestRef,
  positionSecondsRef,
  durationSecondsRef,
  isNativeQueueSyncedRef,
  setSeekOverride,
  setNativePosition,
  streamUrlCache,
  resolvePlaybackUrlCached,
  prefetchAdjacentTrackStreams,
  enqueueNativeQueueMutation,
  TrackPlayer,
  isPlayerReady,
  ensurePlayerReady,
  State,
  canUseLightweightAudioFallback,
  showPlaybackNotice,
  playSongRef,
  togglePlayRef,
  togglePlayInFlightRef,
  nextSongRef,
  prevSongRef,
  seekToRef,
  triggerAutoplayAppend,
  autoplaySongIdsRef,
  lastAutoplaySeedIdRef,
  sleepTimerRef,
}: UseAudioPlaybackCommandsOptions) {
  const playSong = useCallback(
    async (song: Song, requestedQueue?: Song[]) => {
      if (!song?.id) return;
      const reqId = ++playRequestIdRef.current;
      pendingPlayRequestRef.current = {
        id: reqId,
        songId: song.id,
      };

      const hasRequestedQueue = Array.isArray(requestedQueue) && requestedQueue.length > 0;
      const songIndexInQueue = hasRequestedQueue
        ? requestedQueue.findIndex((s) => s.id === song.id)
        : queueRef.current.findIndex((s) => s.id === song.id);

      const isNewQueue = hasRequestedQueue
        ? !isSameQueueContent(requestedQueue, queueRef.current)
        : songIndexInQueue < 0;

      const q = hasRequestedQueue
        ? requestedQueue
        : songIndexInQueue >= 0
          ? queueRef.current
          : [song];

      const targetIndex = songIndexInQueue >= 0 ? songIndexInQueue : Math.max(0, q.findIndex((s) => s.id === song.id));
      const targetSong = q[targetIndex] || song;

      // 1. Instant local UI feedback
      setCurrentSong(targetSong);
      currentSongRef.current = targetSong;
      setQueue(q);
      queueRef.current = q;
      if (isNewQueue || !isShuffledRef.current) {
        originalQueueRef.current = q;
        setSourceQueue(q);
      }
      setQueueIndex(targetIndex);
      queueIndexRef.current = targetIndex;

      if (isNewQueue) {
        setUserQueuedSongIds([]);
        userQueuedSongIdsRef.current = [];
        if (autoplaySongIdsRef) autoplaySongIdsRef.current = [];
        if (lastAutoplaySeedIdRef) lastAutoplaySeedIdRef.current = null;
        if (isNativeQueueSyncedRef) isNativeQueueSyncedRef.current = false;
      } else {
        const prevIds = userQueuedSongIdsRef.current;
        if (prevIds.includes(targetSong.id)) {
          const next = prevIds.filter((id) => id !== targetSong.id);
          userQueuedSongIdsRef.current = next;
          setUserQueuedSongIds(next);
        }
      }

      desiredPlayStateRef.current = true;
      setIsPlaying(true);
      isPlayingRef.current = true;
      playbackLoadingRef.current = true;
      setPlaybackLoading(true);
      setSeekOverride(null);
      if (durationSecondsRef) durationSecondsRef.current = toDurationSeconds(targetSong.duration);
      positionSecondsRef.current = 0;
      setNativePosition(0);

      updatePlaybackEngineSnapshot({
        currentSong: targetSong,
        queue: q,
        sourceQueue: originalQueueRef.current,
        userQueuedSongIds: isNewQueue ? [] : userQueuedSongIdsRef.current,
        autoplaySongIds: isNewQueue ? [] : (autoplaySongIdsRef?.current || []),
        queueIndex: targetIndex,
        desiredPlayState: true,
        isPlaying: true,
        isLoading: true,
        isBuffering: false,
      });

      // Proactively fetch and append similar songs if queue is near end
      if (triggerAutoplayAppend && (q.length - targetIndex <= 2)) {
        void triggerAutoplayAppend(targetSong, q);
      }

      // 2. Offload persistence completely off the critical tap path
      setTimeout(() => {
        playerPersistenceService.addRecentlyPlayed(targetSong).catch(() => {});
        playerPersistenceService.savePlayerState({
          currentSong: targetSong,
          queue: q,
          queueIndex: targetIndex,
          positionSeconds: 0,
          updatedAt: Date.now(),
        }).catch(() => {});
      }, 800);

      try {
        const audioUrl = await Promise.race([
          resolvePlaybackUrlCached(targetSong),
          new Promise<null>((resolve) => setTimeout(() => resolve(null), 12000)),
        ]);
        if (reqId !== playRequestIdRef.current) return;

        if (!audioUrl) {
          if (pendingPlayRequestRef.current?.id === reqId) {
            pendingPlayRequestRef.current = null;
          }
          desiredPlayStateRef.current = false;
          setIsPlaying(false);
          isPlayingRef.current = false;
          updatePlaybackEngineSnapshot({ desiredPlayState: null, isPlaying: false, isLoading: false, isBuffering: false });
          showPlaybackNotice("Playback stream timed out or unavailable.");
          return;
        }

        const resolvedSong = withResolvedPlaybackUrl(targetSong, audioUrl);
        currentSongRef.current = resolvedSong;
        setCurrentSong(resolvedSong);

        if (TrackPlayer) {
          const ready = isPlayerReady || (await ensurePlayerReady());
          if (reqId !== playRequestIdRef.current) return;
          if (!ready) {
            if (pendingPlayRequestRef.current?.id === reqId) {
              pendingPlayRequestRef.current = null;
            }
            desiredPlayStateRef.current = false;
            setIsPlaying(false);
            isPlayingRef.current = false;
            updatePlaybackEngineSnapshot({ desiredPlayState: null, isPlaying: false, isLoading: false, isBuffering: false });
            showPlaybackNotice("Audio player initialization failed.");
            return;
          }

          await enqueueNativeQueueMutation(async () => {
            if (reqId !== playRequestIdRef.current) return;

            const targetTrack = songToTrack(targetSong, audioUrl, streamUrlCache.current);

            // Fast path: native queue already synchronized -> skip + play directly
            if (!isNewQueue && isNativeQueueSyncedRef?.current) {
              try {
                await TrackPlayer!.skip(targetIndex);
                if (reqId !== playRequestIdRef.current) return;
                if (desiredPlayStateRef.current === false) await TrackPlayer!.pause();
                else await TrackPlayer!.play();
                return;
              } catch {
                if (isNativeQueueSyncedRef) isNativeQueueSyncedRef.current = false;
              }
            }

            // Sync native queue without blocking on bulk URL scrape
            try {
              const nativeTracks = q.map((queueSong, index) => {
                if (index === targetIndex) return targetTrack;
                const cachedUrl = streamUrlCache.current.get(queueSong.id) || resolveAudioUrl(queueSong);
                return songToTrack(queueSong, cachedUrl || null, streamUrlCache.current);
              });

              const hasValidUrl = (t: any) => typeof t?.url === "string" && t.url.length > 5;
              const allTracksValid = nativeTracks.length === q.length && nativeTracks.every(hasValidUrl);

              if (
                typeof TrackPlayer!.setQueue === "function" &&
                allTracksValid
              ) {
                await TrackPlayer!.setQueue(nativeTracks);
                await TrackPlayer!.skip(targetIndex);
                if (isNativeQueueSyncedRef) isNativeQueueSyncedRef.current = true;
              } else if (typeof TrackPlayer!.load === "function") {
                await TrackPlayer!.load(targetTrack);
                if (isNativeQueueSyncedRef) isNativeQueueSyncedRef.current = false;
              } else {
                await TrackPlayer!.reset();
                await TrackPlayer!.add([targetTrack]);
                if (isNativeQueueSyncedRef) isNativeQueueSyncedRef.current = false;
              }
            } catch (queueErr) {
              logger.error("[Player] Native track load failed:", queueErr);
              try {
                if (typeof TrackPlayer!.load === "function") {
                  await TrackPlayer!.load(targetTrack);
                } else {
                  await TrackPlayer!.reset();
                  await TrackPlayer!.add([targetTrack]);
                }
              } catch (loadError) {
                throw loadError;
              }
              if (isNativeQueueSyncedRef) isNativeQueueSyncedRef.current = false;
            }

            if (reqId !== playRequestIdRef.current) return;
            if (desiredPlayStateRef.current === false) await TrackPlayer!.pause();
            else await TrackPlayer!.play();
          });

          if (reqId !== playRequestIdRef.current) return;
          prefetchAdjacentTrackStreams(q, targetIndex);
        } else if (canUseLightweightAudioFallback) {
          if (reqId !== playRequestIdRef.current) return;
          await ExpoAvPlayer.loadAndPlay(audioUrl, targetSong, () =>
            reqId === playRequestIdRef.current && desiredPlayStateRef.current !== false
          );
        }
      } catch (error) {
        if (reqId !== playRequestIdRef.current) return;
        logger.error("[Player] playSong failed", error);
        if (pendingPlayRequestRef.current?.id === reqId) {
          pendingPlayRequestRef.current = null;
        }
        desiredPlayStateRef.current = false;
        setIsPlaying(false);
        isPlayingRef.current = false;
        updatePlaybackEngineSnapshot({ desiredPlayState: null, isPlaying: false, isLoading: false, isBuffering: false });
        showPlaybackNotice("Could not start playback.");
      } finally {
        if (reqId === playRequestIdRef.current) {
          pendingPlayRequestRef.current = null;
          playbackLoadingRef.current = false;
          setPlaybackLoading(false);
          updatePlaybackEngineSnapshot({ isLoading: false });
        }
      }
    },
    [
      currentSongRef,
      durationSecondsRef,
      positionSecondsRef,
      enqueueNativeQueueMutation,
      ensurePlayerReady,
      isNativeQueueSyncedRef,
      isPlayerReady,
      isPlayingRef,
      isShuffledRef,
      originalQueueRef,
      playRequestIdRef,
      playbackLoadingRef,
      pendingPlayRequestRef,
      prefetchAdjacentTrackStreams,
      queueIndexRef,
      queueRef,
      resolvePlaybackUrlCached,
      setCurrentSong,
      setIsPlaying,
      setNativePosition,
      setPlaybackLoading,
      setQueue,
      setQueueIndex,
      setSeekOverride,
      setSourceQueue,
      setUserQueuedSongIds,
      showPlaybackNotice,
      streamUrlCache,
      TrackPlayer,
      userQueuedSongIdsRef,
      desiredPlayStateRef,
      canUseLightweightAudioFallback,
      autoplaySongIdsRef,
      lastAutoplaySeedIdRef,
      triggerAutoplayAppend,
    ]
  );

  useEffect(() => {
    playSongRef.current = playSong;
  }, [playSong, playSongRef]);

  const togglePlay = useCallback(async () => {
    if (togglePlayInFlightRef.current) return;
    togglePlayInFlightRef.current = true;

    const nextPlayState = !isPlayingRef.current;
    desiredPlayStateRef.current = nextPlayState;

    if (!currentSongRef.current) {
      if (queueRef.current.length > 0) {
        const target = queueRef.current[queueIndexRef.current] || queueRef.current[0];
        if (target) {
          void playSong(target, queueRef.current);
        }
      }
      togglePlayInFlightRef.current = false;
      return;
    }

    try {
      if (nextPlayState && playbackLoadingRef.current) {
        setIsPlaying(true);
        isPlayingRef.current = true;
        updatePlaybackEngineSnapshot({ desiredPlayState: true, isPlaying: true });
        return;
      }
      if (TrackPlayer) {
        if (nextPlayState) {
          setIsPlaying(true);
          isPlayingRef.current = true;
          updatePlaybackEngineSnapshot({ desiredPlayState: true, isPlaying: true });
          const ready = isPlayerReady || (await ensurePlayerReady());
          if (ready) {
            const [activeTrack, playbackState] = await Promise.all([
              TrackPlayer.getActiveTrack().catch(() => null),
              TrackPlayer.getPlaybackState().catch(() => null),
            ]);
            const rawState = typeof playbackState === "object" ? (playbackState as any)?.state : playbackState;

            // If native player has no active track, wrong track, or state is none/stopped/ended/error:
            if (
              !activeTrack ||
              !activeTrack.url ||
              rawState === State.None ||
              rawState === State.Stopped ||
              rawState === State.Ended ||
              rawState === State.Error ||
              activeTrack.id !== currentSongRef.current.id
            ) {
              await playSong(currentSongRef.current, queueRef.current);
              return;
            }

            try {
              await TrackPlayer.play();
            } catch (playErr) {
              logger.warn("[Player] TrackPlayer.play() failed, reloading track via playSong:", playErr);
              await playSong(currentSongRef.current, queueRef.current);
            }
          }
        } else {
          setIsPlaying(false);
          isPlayingRef.current = false;
          updatePlaybackEngineSnapshot({ desiredPlayState: false, isPlaying: false });
          await TrackPlayer.pause();
        }
      } else if (canUseLightweightAudioFallback) {
        if (nextPlayState) {
          if (ExpoAvPlayer.isLoaded()) {
            ExpoAvPlayer.play();
            setIsPlaying(true);
            isPlayingRef.current = true;
            updatePlaybackEngineSnapshot({ desiredPlayState: true, isPlaying: true });
          } else {
            void playSong(currentSongRef.current, queueRef.current);
          }
        } else {
          setIsPlaying(false);
          isPlayingRef.current = false;
          updatePlaybackEngineSnapshot({ desiredPlayState: false, isPlaying: false });
          try { ExpoAvPlayer.pause(); } catch {}
        }
      }
    } catch (error) {
      logger.error("[Player] togglePlay failed", error);
      if (nextPlayState && currentSongRef.current) {
        void playSong(currentSongRef.current, queueRef.current);
      }
    } finally {
      togglePlayInFlightRef.current = false;
    }
  }, [
    State,
    canUseLightweightAudioFallback,
    currentSongRef,
    desiredPlayStateRef,
    ensurePlayerReady,
    isPlayerReady,
    isPlayingRef,
    playSong,
    playbackLoadingRef,
    queueIndexRef,
    queueRef,
    setIsPlaying,
    togglePlayInFlightRef,
    TrackPlayer,
  ]);

  useEffect(() => {
    togglePlayRef.current = togglePlay;
  }, [togglePlay, togglePlayRef]);

  const nextSong = useCallback(async () => {
    const cq = queueRef.current;
    const ci = queueIndexRef.current;
    if (cq.length === 0) return;

    if (repeatModeRef.current === "all" || ci < cq.length - 1) {
      const nextIndex = (ci + 1) % cq.length;
      const targetSong = cq[nextIndex];
      if (targetSong) {
        void playSong(targetSong, cq);
      }
    } else {
      // Reached end of queue: check smart autoplay before stopping
      try {
        const { getSettings } = require("@/lib/storage");
        const settings = await getSettings();
        if (
          settings?.smartAutoplayEnabled &&
          sleepTimerRef?.current?.mode !== "end-of-stack" &&
          triggerAutoplayAppend
        ) {
          const seed = cq[ci] || currentSongRef.current;
          if (seed) {
            showPlaybackNotice("Finding similar songs...");
            const recs = await triggerAutoplayAppend(seed, cq);
            if (recs.length > 0) {
              void playSong(recs[0], queueRef.current);
              return;
            }
          }
        }
      } catch (err) {
        logger.warn("[Player] Autoplay nextSong error:", err);
      }

      setIsPlaying(false);
      isPlayingRef.current = false;
      updatePlaybackEngineSnapshot({ isPlaying: false, desiredPlayState: false });
    }
  }, [
    currentSongRef,
    isPlayingRef,
    playSong,
    queueIndexRef,
    queueRef,
    repeatModeRef,
    setIsPlaying,
    showPlaybackNotice,
    sleepTimerRef,
    triggerAutoplayAppend,
  ]);

  useEffect(() => {
    nextSongRef.current = nextSong;
  }, [nextSong, nextSongRef]);

  const seekTo = useCallback(
    async (progress: number) => {
      const durationSeconds = (durationSecondsRef?.current && durationSecondsRef.current > 0)
        ? durationSecondsRef.current
        : toDurationSeconds(currentSongRef.current?.duration);
      if (durationSeconds <= 0) return;

      const seconds = Math.max(0, Math.min(durationSeconds, progress * durationSeconds));
      setSeekOverride({
        songId: currentSongRef.current?.id || null,
        seconds,
        startedAt: Date.now(),
      });
      setNativePosition(seconds);

      if (TrackPlayer && isPlayerReady) {
        await TrackPlayer.seekTo(seconds).catch(() => {});
      } else if (canUseLightweightAudioFallback) {
        await ExpoAvPlayer.seekTo(seconds);
      }
    },
    [canUseLightweightAudioFallback, currentSongRef, durationSecondsRef, isPlayerReady, setNativePosition, setSeekOverride, TrackPlayer]
  );

  useEffect(() => {
    seekToRef.current = seekTo;
  }, [seekTo, seekToRef]);

  const prevSong = useCallback(async () => {
    if (positionSecondsRef.current > 3) {
      void seekTo(0);
      return;
    }

    const cq = queueRef.current;
    const ci = queueIndexRef.current;
    if (cq.length === 0) return;

    if (repeatModeRef.current === "all" || ci > 0) {
      const prevIndex = (ci - 1 + cq.length) % cq.length;
      const targetSong = cq[prevIndex];
      if (targetSong) {
        void playSong(targetSong, cq);
      }
    } else {
      void seekTo(0);
    }
  }, [playSong, positionSecondsRef, queueIndexRef, queueRef, repeatModeRef, seekTo]);

  useEffect(() => {
    prevSongRef.current = prevSong;
  }, [prevSong, prevSongRef]);

  return {
    playSong,
    togglePlay,
    nextSong,
    prevSong,
    seekTo,
  };
}

import { useEffect, useRef, type MutableRefObject } from "react";
import { AppState, Platform } from "react-native";
import type { Song } from "@/lib/musicData";
import { logger } from "@/lib/logger";
import { updatePlaybackEngineSnapshot } from "@/services/audio/PlaybackEngine";
import { playerPersistenceService } from "@/services/player/playerPersistenceService";
import { carPlayService } from "@/services/carPlayService";
import { songToTrack } from "@/services/audio/PlayerPlaybackResolver";
import { toDurationSeconds } from "@/utils/timeFormatters";
import type { SleepTimerState } from "@/types/playbackTypes";
import type { PendingPlayRequest } from "@/services/audio/usePlayerCoreState";

interface UseAudioSyncListenersOptions {
  isPlayerReady: boolean;
  TrackPlayer: any;
  Event: any;
  State: any;
  subscribeTrackPlayerEvent: (eventName: unknown, listener: (...args: any[]) => void) => () => void;
  currentSong: Song | null;
  currentSongRef: MutableRefObject<Song | null>;
  setCurrentSong: (song: Song | null) => void;
  queueRef: MutableRefObject<Song[]>;
  queueIndex: number;
  queueIndexRef: MutableRefObject<number>;
  setQueueIndex: (index: number) => void;
  setIsPlaying: (playing: boolean) => void;
  isPlayingRef: MutableRefObject<boolean>;
  setPlaybackLoading: (loading: boolean) => void;
  playbackLoadingRef: MutableRefObject<boolean>;
  desiredPlayStateRef: MutableRefObject<boolean | null>;
  pendingPlayRequestRef: MutableRefObject<PendingPlayRequest | null>;
  positionSecondsRef: MutableRefObject<number>;
  setNativePosition: (pos: number) => void;
  setNativeDuration: React.Dispatch<React.SetStateAction<number>>;
  setSeekOverride: (override: any) => void;
  prefetchAdjacentTrackStreams: (queue: Song[], index: number) => void;
  sleepTimerRef: MutableRefObject<SleepTimerState | null>;
  clearSleepTimer: () => void;
  showPlaybackNotice: (msg: string) => void;
  likedSongs: Song[];
  likedSongsRef: MutableRefObject<Song[]>;
  playSong: (song: Song, queue?: Song[]) => Promise<void> | void;
  isNativeQueueSyncedRef?: MutableRefObject<boolean>;
  triggerAutoplayAppend?: (seedSong: Song, currentQueue: Song[]) => Promise<Song[]>;
}

export function useAudioSyncListeners({
  isPlayerReady,
  TrackPlayer,
  Event,
  State,
  subscribeTrackPlayerEvent,
  currentSong,
  currentSongRef,
  setCurrentSong,
  queueRef,
  queueIndex,
  queueIndexRef,
  setQueueIndex,
  setIsPlaying,
  isPlayingRef,
  setPlaybackLoading,
  playbackLoadingRef,
  desiredPlayStateRef,
  pendingPlayRequestRef,
  positionSecondsRef,
  setNativePosition,
  setNativeDuration,
  setSeekOverride,
  prefetchAdjacentTrackStreams,
  sleepTimerRef,
  clearSleepTimer,
  showPlaybackNotice,
  likedSongs,
  likedSongsRef,
  playSong,
  isNativeQueueSyncedRef,
  triggerAutoplayAppend,
}: UseAudioSyncListenersOptions) {
  const publishedLockScreenDurationRef = useRef<{
    songId: string;
    duration: number;
  } | null>(null);

  // TrackPlayer native event handlers
  useEffect(() => {
    if (!isPlayerReady || !TrackPlayer) return;

    const pauseIntent = () => {
      desiredPlayStateRef.current = false;
      setIsPlaying(false);
      isPlayingRef.current = false;
      updatePlaybackEngineSnapshot({ desiredPlayState: false, isPlaying: false });
    };
    const playIntent = () => {
      desiredPlayStateRef.current = true;
      setIsPlaying(true);
      isPlayingRef.current = true;
      updatePlaybackEngineSnapshot({ desiredPlayState: true, isPlaying: true });
    };
    const unsubs = [
      subscribeTrackPlayerEvent(Event.RemotePlay, playIntent),
      subscribeTrackPlayerEvent(Event.RemotePause, pauseIntent),
      subscribeTrackPlayerEvent(Event.RemoteStop, pauseIntent),
      subscribeTrackPlayerEvent(Event.RemoteDuck, (event: any) => {
        if (event?.paused || event?.permanent) pauseIntent();
      }),
      subscribeTrackPlayerEvent(Event.PlaybackState, (event: any) => {
        const nextState = event && typeof event === "object" && "state" in event ? event.state : event;

        switch (nextState) {
          case State.Playing:
            if (playbackLoadingRef.current || desiredPlayStateRef.current === false) break;
            pendingPlayRequestRef.current = null;
            desiredPlayStateRef.current = true;
            setIsPlaying(true);
            isPlayingRef.current = true;
            setPlaybackLoading(false);
            updatePlaybackEngineSnapshot({ isPlaying: true, isLoading: false, isBuffering: false });
            break;

          case State.Paused:
          case State.Stopped:
            // Keep the intended play state through a native source change.
            if (!playbackLoadingRef.current && desiredPlayStateRef.current !== true && !pendingPlayRequestRef.current) {
              setIsPlaying(false);
              isPlayingRef.current = false;
              setPlaybackLoading(false);
              updatePlaybackEngineSnapshot({ isPlaying: false, isLoading: false, isBuffering: false });
            }
            break;

          case State.Buffering:
          case State.Loading:
            updatePlaybackEngineSnapshot({ isBuffering: true });
            break;
        }
      }),
      subscribeTrackPlayerEvent(Event.PlaybackPlayWhenReadyChanged, (event: any) => {
        if (typeof event?.playWhenReady !== "boolean") return;
        // A native queue replacement may emit a stale resume after the user
        // has paused. The explicit user intent must always win that race.
        if (desiredPlayStateRef.current === false) {
          if (event.playWhenReady) {
            void TrackPlayer?.pause?.().catch(() => {});
          }
          return;
        }
        // Queue replacement can reset native intent before our play command.
        if (playbackLoadingRef.current) return;
        desiredPlayStateRef.current = event.playWhenReady;

        if (event.playWhenReady) {
          setIsPlaying(true);
          isPlayingRef.current = true;
          updatePlaybackEngineSnapshot({ desiredPlayState: true, isPlaying: true });
          return;
        }

        pendingPlayRequestRef.current = null;
        setIsPlaying(false);
        isPlayingRef.current = false;
        setPlaybackLoading(false);
        updatePlaybackEngineSnapshot({ desiredPlayState: false, isPlaying: false, isLoading: false, isBuffering: false });
      }),
      subscribeTrackPlayerEvent(Event.PlaybackError, (error: any) => {
        logger.error("[Player] PlaybackError event", error);
        pendingPlayRequestRef.current = null;
        desiredPlayStateRef.current = false;
        setIsPlaying(false);
        isPlayingRef.current = false;
        setPlaybackLoading(false);
        updatePlaybackEngineSnapshot({ isPlaying: false, isLoading: false, isBuffering: false });

        const errorMsg = error?.message || error?.code || "Playback failed";
        showPlaybackNotice(`Playback error: ${errorMsg}`);
      }),
      subscribeTrackPlayerEvent(Event.PlaybackProgressUpdated, (event: any) => {
        if (playbackLoadingRef.current || pendingPlayRequestRef.current) return;
        if (isNativeQueueSyncedRef?.current && event?.track !== queueIndexRef.current) return;
        if (typeof event?.position === "number") {
          setNativePosition(event.position);
          positionSecondsRef.current = event.position;
        }
        const song = currentSongRef.current;
        const nativeDuration = typeof event?.duration === "number" && event.duration > 0
          ? event.duration
          : 0;
        const catalogDuration = toDurationSeconds(song?.duration);
        const duration = nativeDuration || catalogDuration;

        if (nativeDuration > 0) {
          const dur = nativeDuration;
          setNativeDuration((prev) => (Math.abs(prev - dur) > 0.5 ? dur : prev));
          if (song && (!song.duration || song.duration <= 0)) {
            song.duration = dur;
          }
        }

        // SwiftAudioEx uses its AVPlayer duration for Now Playing. Several
        // music streams report that as zero, despite the catalogue already
        // knowing the track length. Set the best available duration once per
        // track (and again only if native later reports a different value).
        const previouslyPublished = publishedLockScreenDurationRef.current;
        const shouldPublishDuration = Boolean(
          song &&
          duration > 0 &&
          (previouslyPublished?.songId !== song.id ||
            Math.abs((previouslyPublished?.duration ?? 0) - duration) > 0.5)
        );

        if (
          shouldPublishDuration &&
          song &&
          Platform.OS === "ios" &&
          typeof TrackPlayer?.updateMetadataForTrack === "function"
        ) {
          publishedLockScreenDurationRef.current = { songId: song.id, duration };
          const track = songToTrack(song);
          const trackIndex = typeof event?.track === "number" ? event.track : queueIndexRef.current;
          TrackPlayer.updateMetadataForTrack(trackIndex, {
            title: track.title,
            artist: track.artist,
            album: track.album,
            artwork: track.artwork,
            genre: track.genre,
            duration,
            isLiveStream: false,
          }).catch(() => {});
        }
      }),
      subscribeTrackPlayerEvent(Event.PlaybackActiveTrackChanged, (event: any) => {
        const currentQ = queueRef.current;
        const currentSong = currentSongRef.current;

        // 1. Identify track by ID if available from native event
        const activeTrackId =
          typeof event?.track?.id === "string"
            ? event?.track?.id
            : typeof event?.track === "string"
            ? event?.track
            : null;

        const pending = pendingPlayRequestRef.current;
        if (pending && activeTrackId !== pending.songId) return;

        // If native event confirms the song we already selected, do NOT overwrite or jump
        if (activeTrackId && currentSong && activeTrackId === currentSong.id) {
          return;
        }

        const nextIndex =
          typeof event?.index === "number"
            ? event.index
            : typeof event?.nextTrack === "number"
            ? event.nextTrack
            : -1;

        let targetSong: Song | undefined;
        let resolvedIndex = -1;

        // Match by ID first across our queue
        if (activeTrackId) {
          const foundIndex = currentQ.findIndex((s) => s.id === activeTrackId);
          if (foundIndex >= 0) {
            targetSong = currentQ[foundIndex];
            resolvedIndex = foundIndex;
          }
        }

        // Only fall back to index if the native queue is confirmed 1:1 synchronized
        if (!targetSong && isNativeQueueSyncedRef?.current && nextIndex >= 0 && nextIndex < currentQ.length) {
          targetSong = currentQ[nextIndex];
          resolvedIndex = nextIndex;
        }

        // If native queue is unsynced and no track ID matched, DO NOT blind-revert to queue[0]!
        if (!targetSong) return;

        if (targetSong.id !== currentSongRef.current?.id) {
          currentSongRef.current = targetSong;
          setCurrentSong(targetSong);
          if (resolvedIndex >= 0) {
            setQueueIndex(resolvedIndex);
            queueIndexRef.current = resolvedIndex;
          }
          setSeekOverride(null);
          setNativePosition(0);
          positionSecondsRef.current = 0;
          const initialDuration = toDurationSeconds(event?.track?.duration || targetSong.duration);
          setNativeDuration(initialDuration > 0 ? initialDuration : 0);
          updatePlaybackEngineSnapshot({
            currentSong: targetSong,
            ...(resolvedIndex >= 0 ? { queueIndex: resolvedIndex } : {}),
          });

          if (resolvedIndex >= 0) {
            prefetchAdjacentTrackStreams(currentQ, resolvedIndex);
            if (triggerAutoplayAppend && resolvedIndex >= currentQ.length - 2) {
              void triggerAutoplayAppend(targetSong, currentQ);
            }
          }
        }
      }),
      subscribeTrackPlayerEvent(Event.PlaybackQueueEnded, async () => {
        if (playbackLoadingRef.current || pendingPlayRequestRef.current) return;
        const endedSong = currentSongRef.current;
        const isStillEnded = () => currentSongRef.current === endedSong &&
          !playbackLoadingRef.current && !pendingPlayRequestRef.current;
        if (sleepTimerRef.current?.mode === "end-of-stack") {
          clearSleepTimer();
          setIsPlaying(false);
          isPlayingRef.current = false;
          setPlaybackLoading(false);
          updatePlaybackEngineSnapshot({ isPlaying: false, isLoading: false, isBuffering: false });
          return;
        }

        if (isNativeQueueSyncedRef?.current === false) {
          const next = queueRef.current[queueIndexRef.current + 1];
          if (next) {
            void playSong(next, queueRef.current);
            return;
          }
        }

        try {
          const { getSettings } = require("@/lib/storage");
          const settings = await getSettings();
          if (!isStillEnded()) return;
          if (settings?.smartAutoplayEnabled && triggerAutoplayAppend) {
            const seed = currentSongRef.current || queueRef.current[queueRef.current.length - 1];
            if (seed) {
              const recs = await triggerAutoplayAppend(seed, queueRef.current);
              if (!isStillEnded() || desiredPlayStateRef.current === false) return;
              if (recs.length > 0) {
                void playSong(recs[0], queueRef.current);
                return;
              }
            }
          }
        } catch (err) {
          logger.warn("[Player] Autoplay queue-ended continuation error:", err);
        }

        if (!isStillEnded()) return;
        desiredPlayStateRef.current = false;
        setIsPlaying(false);
        isPlayingRef.current = false;
        setPlaybackLoading(false);
        updatePlaybackEngineSnapshot({ isPlaying: false, isLoading: false, isBuffering: false });
      }),
    ];

    return () => {
      unsubs.forEach((unsub) => unsub?.());
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isPlayerReady, triggerAutoplayAppend]);

  // Save current playback state (event-driven)
  useEffect(() => {
    if (!currentSong) return;

    const persist = () => {
      if (!currentSongRef.current) return;
      playerPersistenceService.savePlayerState({
        currentSong: currentSongRef.current,
        queue: queueRef.current,
        queueIndex: queueIndexRef.current,
        positionSeconds: positionSecondsRef.current,
        updatedAt: Date.now(),
      }).catch(() => {});
    };

    persist();

    const sub = AppState.addEventListener("change", (state) => {
      if (state !== "active") persist();
    });

    return () => {
      sub.remove();
      persist();
    };
  }, [currentSong, queueIndex, queueIndexRef, queueRef, positionSecondsRef, currentSongRef]);

  // Synchronize playback progress and active track when returning to foreground
  useEffect(() => {
    const handleAppStateChange = async (nextState: string) => {
      if (nextState === "active" && TrackPlayer && isPlayerReady) {
        try {
          const [activeTrack, prog] = await Promise.all([
            TrackPlayer.getActiveTrack().catch(() => null),
            TrackPlayer.getProgress().catch(() => null),
          ]);
          if (activeTrack?.id && activeTrack.id !== currentSongRef.current?.id) {
            const foundIdx = queueRef.current.findIndex((s: Song) => s.id === activeTrack.id);
            if (foundIdx >= 0) {
              const target = queueRef.current[foundIdx];
              currentSongRef.current = target;
              setCurrentSong(target);
              setQueueIndex(foundIdx);
              queueIndexRef.current = foundIdx;
            }
          }
          if (prog) {
            if (typeof prog.position === "number") {
              setNativePosition(prog.position);
            }
            if (typeof prog.duration === "number" && prog.duration > 0) {
              setNativeDuration(prog.duration);
            }
          }
        } catch {
          // ignore non-fatal sync errors
        }
      }
    };

    const sub = AppState.addEventListener("change", handleAppStateChange);
    return () => sub.remove();
  }, [isPlayerReady, TrackPlayer, currentSongRef, queueIndexRef, queueRef, setCurrentSong, setNativeDuration, setNativePosition, setQueueIndex]);

  // Sync state and listen for playback requests from Apple CarPlay
  useEffect(() => {
    if (Platform.OS !== "ios" || !carPlayService.isAvailable()) return;

    if (likedSongs.length > 0) {
      void carPlayService.syncFavorites(likedSongs);
    }

    playerPersistenceService.getUserPlaylists()
      .then((playlists) => {
        if (playlists && playlists.length > 0) {
          void carPlayService.syncPlaylists(playlists);
        }
      })
      .catch(() => {});

    playerPersistenceService.getRecentlyPlayed()
      .then((recent) => {
        const recentSongs: Song[] = (recent || []).flatMap((item) => {
          const s = item.data as Song;
          return s && s.id ? [s] : [];
        });
        if (recentSongs.length > 0) {
          void carPlayService.syncRecent(recentSongs);
        }
      })
      .catch(() => {});

    const unsubPlay = carPlayService.onPlaySong((event) => {
      if (event.song && (event.song as Song).id) {
        void playSong(event.song as Song);
      } else if (event.songId) {
        const found =
          queueRef.current.find((s) => s.id === event.songId) ||
          likedSongsRef.current.find((s) => s.id === event.songId);
        if (found) {
          void playSong(found);
        }
      }
    });

    return () => {
      unsubPlay();
    };
  }, [likedSongs, playSong, likedSongsRef, queueRef]);
}

import type { Song } from "@/lib/musicData";
import { parseApiSong } from "@/lib/searchRepository";
import { deduplicateSongs } from "@/lib/searchUtils";
import { getApiUrl } from "@/lib/api-config";
import { fetchJson } from "@/utils/asyncUtils";
import { logger } from "@/lib/logger";
import { getSettings } from "@/lib/storage";
import type { SmartAutoplayMode } from "@/lib/smartAutoplayConfig";

const RECENT_AUTOPLAY_IDS = new Set<string>();
const MAX_RECENT_AUTOPLAY_CACHE = 60;

function rememberAutoplaySong(id: string) {
  if (!id) return;
  if (RECENT_AUTOPLAY_IDS.size >= MAX_RECENT_AUTOPLAY_CACHE) {
    const first = RECENT_AUTOPLAY_IDS.values().next().value;
    if (first) RECENT_AUTOPLAY_IDS.delete(first);
  }
  RECENT_AUTOPLAY_IDS.add(id);
}

/**
 * Cleans a song title down to its core root name, stripping parentheses,
 * version qualifiers (Remix, Lofi, From Film, Acoustic, etc.), and punctuation.
 */
export function cleanCoreTitle(title?: string | null): string {
  if (!title) return "";
  return title
    .toLowerCase()
    .replace(/&quot;/gi, "")
    .replace(/&#039;/gi, "")
    .replace(/&amp;/gi, "&")
    .replace(/\(.*?\)/g, "") // remove (From "...") or (Lofi)
    .replace(/\[.*?\]/g, "") // remove [Official Audio]
    .replace(/[-–—]\s*(new version|remix|lofi|lo-fi|acoustic|reprise|version|slowed|reverb|cover|unplugged|mashup|edit|mix|dance mix|audio).*$/i, "")
    .replace(/[^\w\s]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function extractArtistNames(artistStr?: string | null): { primary: string; secondary?: string } {
  if (!artistStr) return { primary: "" };
  const parts = artistStr
    .split(/[,&/|]/)
    .map((p) => p.trim())
    .filter(Boolean);
  return {
    primary: parts[0] || "",
    secondary: parts[1] || undefined,
  };
}

function isFuzzySameSongTitle(candTitle: string, seedTitle: string): boolean {
  if (!candTitle || !seedTitle || seedTitle.length < 3) return false;
  if (candTitle === seedTitle) return true;
  return candTitle.indexOf(seedTitle) !== -1 || seedTitle.indexOf(candTitle) !== -1;
}

export interface FetchAutoplayRecommendationsOptions {
  seedSong: Song;
  currentQueue?: Song[];
  mode?: SmartAutoplayMode;
  limit?: number;
  signal?: AbortSignal;
}

/**
 * Generates continuous, Spotify-style song recommendations based on the seed song.
 * Guaranteed to exclude the searched song and any of its variants/remixes,
 * returning distinct, related songs by similar artists and genres.
 */
export async function fetchAutoplayRecommendations({
  seedSong,
  currentQueue = [],
  mode: explicitMode,
  limit = 15,
  signal,
}: FetchAutoplayRecommendationsOptions): Promise<Song[]> {
  if (!seedSong) return [];

  let mode = explicitMode;
  if (!mode) {
    try {
      const settings = await getSettings();
      mode = settings.smartAutoplayMode || "similar-trending";
    } catch {
      mode = "similar-trending";
    }
  }

  const apiUrl = getApiUrl();
  const rawCandidates: Song[] = [];
  const { primary: primaryArtist, secondary: secondaryArtist } = extractArtistNames(seedSong.artist);
  const seedCoreTitle = cleanCoreTitle(seedSong.title);

  // Array of asynchronous queries to discover rich, diverse related songs
  const queryPromises: Promise<Song[]>[] = [];

  // 1. Suggestions API (if available for seed song ID)
  if (seedSong.id && (mode === "similar-only" || mode === "similar-trending" || mode === "mood-radio")) {
    queryPromises.push(
      fetchJson<any>(
        `${apiUrl}/api/songs/${encodeURIComponent(seedSong.id)}/suggestions?limit=${Math.max(limit, 15)}`,
        signal
      )
        .then((res) => {
          const items = res?.data || res?.results || [];
          return Array.isArray(items) ? items.map(parseApiSong).filter((s): s is Song => Boolean(s)) : [];
        })
        .catch(() => [])
    );
  }

  // 2. Primary Artist hits (e.g. "Arijit Singh hits")
  if (primaryArtist) {
    queryPromises.push(
      fetchJson<any>(
        `${apiUrl}/api/search/songs?query=${encodeURIComponent(`${primaryArtist} hits`)}&limit=15`,
        signal
      )
        .then((res) => {
          const items = res?.data?.results || res?.data || [];
          return Array.isArray(items) ? items.map(parseApiSong).filter((s): s is Song => Boolean(s)) : [];
        })
        .catch(() => [])
    );
  }

  // 3. Secondary/Collaborating Artist or Composer hits (e.g. "Pritam hits")
  if (secondaryArtist && secondaryArtist.toLowerCase() !== primaryArtist.toLowerCase()) {
    queryPromises.push(
      fetchJson<any>(
        `${apiUrl}/api/search/songs?query=${encodeURIComponent(`${secondaryArtist} hits`)}&limit=10`,
        signal
      )
        .then((res) => {
          const items = res?.data?.results || res?.data || [];
          return Array.isArray(items) ? items.map(parseApiSong).filter((s): s is Song => Boolean(s)) : [];
        })
        .catch(() => [])
    );
  }

  // 4. Genre / Mood-based hits (e.g. "hindi hits" or "bollywood popular")
  const genreQuery = seedSong.genre ? `${seedSong.genre} top hits` : "bollywood hits";
  queryPromises.push(
    fetchJson<any>(
      `${apiUrl}/api/search/songs?query=${encodeURIComponent(genreQuery)}&limit=10`,
      signal
    )
      .then((res) => {
        const items = res?.data?.results || res?.data || [];
        return Array.isArray(items) ? items.map(parseApiSong).filter((s): s is Song => Boolean(s)) : [];
      })
      .catch(() => [])
  );

  // Await all discovery queries concurrently
  const queryResults = await Promise.allSettled(queryPromises);
  for (const result of queryResults) {
    if (result.status === "fulfilled" && Array.isArray(result.value)) {
      rawCandidates.push(...result.value);
    }
  }

  // 5. Strict Deduplication & Same-Song Filtering
  // - Exclude the seed song itself by ID
  // - Exclude existing songs in the active queue by ID
  // - Exclude ANY song whose title is the same or a variant/remix of the seed song
  // - Deduplicate candidate songs against each other so no two songs share the same root title
  const existingQueueIds = new Set(currentQueue.map((s) => s.id));
  existingQueueIds.add(seedSong.id);

  const existingQueueTitles = new Set(
    currentQueue.map((s) => cleanCoreTitle(s.title)).filter(Boolean)
  );
  if (seedCoreTitle) {
    existingQueueTitles.add(seedCoreTitle);
  }

  const seenTitlesInBatch = new Set<string>();
  if (seedCoreTitle) {
    seenTitlesInBatch.add(seedCoreTitle);
  }

  const filteredRecommendations: Song[] = [];
  const dedupedRaw = deduplicateSongs(rawCandidates);

  for (const song of dedupedRaw) {
    if (!song || !song.id) continue;

    // Reject if ID is already in queue or matches seed
    if (existingQueueIds.has(song.id)) continue;

    const candCoreTitle = cleanCoreTitle(song.title);
    if (!candCoreTitle) continue;

    // Strict same-song check: Never play another version/remix of the searched song
    if (isFuzzySameSongTitle(candCoreTitle, seedCoreTitle)) {
      continue;
    }

    // Reject if this title is already present in queue
    if (existingQueueTitles.has(candCoreTitle)) continue;

    // Reject duplicates within this recommendation batch (e.g. only keep 1 version of a recommended song)
    if (seenTitlesInBatch.has(candCoreTitle)) continue;

    // Avoid repeating songs played recently in this autoplay session if we have enough
    if (RECENT_AUTOPLAY_IDS.has(song.id) && dedupedRaw.length > 8) {
      continue;
    }

    seenTitlesInBatch.add(candCoreTitle);
    rememberAutoplaySong(song.id);
    filteredRecommendations.push(song);

    if (filteredRecommendations.length >= limit) {
      break;
    }
  }

  return filteredRecommendations;
}

import { Platform, Share } from "react-native";
import * as Clipboard from "expo-clipboard";
import * as Haptics from "expo-haptics";
import type { Song } from "@/lib/musicData";
import { triggerImpact } from "@/lib/haptics";
import { showGlobalToast } from "@/utils/globalToast";
import { openShareSheet, type ShareSheetData } from "@/utils/shareSheet";
import { unescapeHtml } from "./stringUtils";

export interface ShareContentOptions {
  title: string;
  message: string;
  url?: string;
  dialogTitle?: string;
}

/**
 * Universal official share helper with platform-specific Android/iOS/Web handling
 */
export async function shareContent(options: ShareContentOptions): Promise<boolean> {
  try {
    void triggerImpact(Haptics.ImpactFeedbackStyle.Light);

    const title = unescapeHtml(options.title || "Mavrixfy");
    const message = unescapeHtml(options.message || "");
    const url = options.url?.trim();

    // On Android, the system share sheet expects the URL to be included in the message string
    const fullMessage =
      Platform.OS === "android" && url
        ? `${message}\n\n${url}`
        : message;

    if (Platform.OS === "web") {
      if (typeof navigator !== "undefined" && navigator.share) {
        await navigator.share({
          title,
          text: message,
          url: url || undefined,
        });
        return true;
      }
      // Web clipboard fallback
      const copyText = url ? `${title} - ${message}\n${url}` : `${title}\n${message}`;
      await Clipboard.setStringAsync(copyText);
      showGlobalToast("Link copied to clipboard!");
      return true;
    }

    const result = await Share.share(
      {
        title,
        message: fullMessage,
        url: url || undefined,
      },
      {
        dialogTitle: options.dialogTitle || `Share ${title}`,
        tintColor: "#00E59B",
      }
    );

    if (result.action === Share.sharedAction) {
      return true;
    }
    return false;
  } catch (err: any) {
    if (err?.message !== "User did not share") {
      const fallbackText = options.url || `${options.title} - ${options.message}`;
      await Clipboard.setStringAsync(fallbackText);
      showGlobalToast("Link copied to clipboard");
    }
    return false;
  }
}

export const MAVRIXFY_WEB_BASE = "https://mavrixfy.site";

/**
 * Universal builder for clean, Spotify-style canonical share links
 */
export function buildShareUrl(options: {
  type: "song" | "playlist" | "artist" | "mix";
  id?: string;
  title?: string;
  subtitle?: string;
  imageUrl?: string;
  ids?: string[];
  names?: string[];
}): string {
  const base = MAVRIXFY_WEB_BASE;

  if (options.type === "playlist" && options.id) {
    const params = new URLSearchParams({ playlist: options.id });
    if (options.title) params.set("name", options.title);
    return `${base}/?${params.toString()}`;
  }

  if (options.type === "artist" && options.id) {
    const params = new URLSearchParams({ artist: options.id });
    if (options.title) params.set("name", options.title);
    return `${base}/?${params.toString()}`;
  }

  if (options.type === "mix" && options.ids?.length && options.names?.length) {
    const params = new URLSearchParams({
      mix: "1",
      ids: options.ids.join(","),
      names: options.names.join(","),
    });
    return `${base}/?${params.toString()}`;
  }

  if (options.id) {
    const params = new URLSearchParams({ track: options.id });
    if (options.title) params.set("title", options.title);
    if (options.subtitle && options.subtitle !== "Song" && options.subtitle !== "Artist") {
      params.set("artist", options.subtitle);
    }
    return `${base}/?${params.toString()}`;
  }

  return base;
}

/**
 * Share a track with visual Spotify-style share sheet
 */
export function shareSong(song: Song): boolean {
  if (!song) return false;
  void triggerImpact(Haptics.ImpactFeedbackStyle.Light);
  const title = unescapeHtml(song.title);
  const artist = unescapeHtml(song.artist || "Unknown Artist");
  const imageUrl = song.coverUrl || "";
  const shareUrl = buildShareUrl({
    type: "song",
    id: song.id,
    title,
    subtitle: artist,
    imageUrl,
  });

  openShareSheet({
    title,
    subtitle: artist,
    imageUrl,
    url: shareUrl,
    type: "song",
  });
  return true;
}

/**
 * Share a playlist with visual Spotify-style share sheet
 */
export function sharePlaylist(playlist: {
  id: string;
  name: string;
  coverUrl?: string;
  songCount?: number;
}): boolean {
  if (!playlist) return false;
  void triggerImpact(Haptics.ImpactFeedbackStyle.Light);
  const name = unescapeHtml(playlist.name);
  const countText = playlist.songCount ? `${playlist.songCount} songs` : "Playlist";
  const shareUrl = buildShareUrl({
    type: "playlist",
    id: playlist.id,
    title: name,
    subtitle: countText,
    imageUrl: playlist.coverUrl,
  });

  openShareSheet({
    title: name,
    subtitle: countText,
    imageUrl: playlist.coverUrl,
    url: shareUrl,
    type: "playlist",
  });
  return true;
}

/**
 * Share an artist profile with visual Spotify-style share sheet
 */
export function shareArtist(artist: {
  id: string;
  name: string;
  coverUrl?: string;
}): boolean {
  if (!artist) return false;
  void triggerImpact(Haptics.ImpactFeedbackStyle.Light);
  const name = unescapeHtml(artist.name);
  const shareUrl = buildShareUrl({
    type: "artist",
    id: artist.id,
    title: name,
    subtitle: "Artist",
    imageUrl: artist.coverUrl,
  });

  openShareSheet({
    title: name,
    subtitle: "Artist",
    imageUrl: artist.coverUrl,
    url: shareUrl,
    type: "artist",
  });
  return true;
}

/**
 * Share an Artist Mix with visual Spotify-style share sheet
 */
export function shareArtistMix(
  names: string[],
  ids: string[],
  images?: string[]
): boolean {
  if (!names.length) return false;
  void triggerImpact(Haptics.ImpactFeedbackStyle.Light);
  const title = names.length === 1 ? `${names[0]} Mix` : `${names.slice(0, 2).join(" & ")} Mix`;
  const shareUrl = buildShareUrl({
    type: "mix",
    title,
    subtitle: `${names.length} Artists Mix`,
    imageUrl: images?.[0],
    ids,
    names,
  });

  openShareSheet({
    title,
    subtitle: `${names.length} Artists Mix`,
    imageUrl: images?.[0],
    url: shareUrl,
    type: "mix",
  });
  return true;
}
